match lit {
            Literal::Int(n) => Value::Int(n),
            Literal::Float(n) => Value::Float(n),
            Literal::Str(s) => Value::Str(s),
        }

match self {
            FunctionError::Unknown { name, arity } => {
                write!(f, "unknown function {name} with {arity} argument(s)")
            }
            FunctionError::IntegerOverflow => write!(f, "integer overflow"),
        }

match v {
        Value::Integer(i) => *i as f64,
        Value::Real(r) => *r,
        Value::Text(s) => match crate::coerce::coerce_text_to_numeric(s) {
            Value::Integer(i) => i as f64,
            Value::Real(r) => r,
            _ => 0.0,
        },
        Value::Null | Value::Blob(_) => 0.0,
    }

match crate::coerce::coerce_text_to_numeric(s) {
            Value::Integer(i) => i as f64,
            Value::Real(r) => r,
            _ => 0.0,
        }

match &args[0] {
        Value::Null => Value::Null,
        Value::Blob(b) => Value::Integer(b.len() as i64),
        Value::Text(s) => Value::Integer(s.chars().count() as i64),
        other => Value::Integer(as_text(other).chars().count() as i64),
    }

match &args[0] {
        Value::Null => Value::Null,
        Value::Text(s) => Value::Text(s.to_ascii_uppercase().into()),
        other => other.clone(),
    }

match &args[0] {
        Value::Null => Value::Null,
        Value::Text(s) => Value::Text(s.to_ascii_lowercase().into()),
        other => other.clone(),
    }

match &args[0] {
        Value::Null => Value::Null,
        Value::Integer(i) => Value::Integer(i.checked_abs().ok_or(FunctionError::IntegerOverflow)?),
        Value::Real(r) => Value::Real(r.abs()),
        // Text/blob arguments always coerce through the REAL path --
        // even a clean integer-looking string like '5' yields REAL
        // 5.0, matching sqlite-rs's own oracle-verified behavior.
        other => Value::Real(value_f64(other).abs()),
    }

match c {
        b'0'..=b'9' => Some(c.saturating_sub(b'0')),
        b'a'..=b'f' => Some(c.saturating_sub(b'a').saturating_add(10)),
        b'A'..=b'F' => Some(c.saturating_sub(b'A').saturating_add(10)),
        _ => None,
    }

match &args[0] {
        Value::Null => Value::Null,
        other => {
            let n = value_f64(other);
            Value::Integer(if n > 0.0 {
                1
            } else if n < 0.0 {
                -1
            } else {
                0
            })
        }
    }

match &args[1] {
            Value::Blob(b) => find_bytes(hay, b),
            other => find_bytes(hay, as_text(other).as_bytes()),
        }

match args.get(2) {
        Some(z) => {
            let raw = crate::coerce::cast_to_integer(z);
            if raw < 0 {
                (raw.saturating_neg(), true)
            } else {
                (raw, false)
            }
        }
        None => (i64::MAX / 2, false),
    }

match pc {
            '%' => {
                // Collapse consecutive '%' (a run behaves as one).
                while pi < p.len() && p[pi] == '%' {
                    pi = pi.saturating_add(1);
                }
                if pi == p.len() {
                    return true;
                }
                for start in ti..=t.len() {
                    if like_rec(t, p, escape, start, pi) {
                        return true;
                    }
                }
                return false;
            }
            '_' => {
                if ti >= t.len() {
                    return false;
                }
                ti = ti.saturating_add(1);
                pi = pi.saturating_add(1);
            }
            _ => {
                if ti >= t.len() || !ascii_eq(t[ti], pc) {
                    return false;
                }
                ti = ti.saturating_add(1);
                pi = pi.saturating_add(1);
            }
        }

match p[pi] {
            '*' => {
                while pi < p.len() && p[pi] == '*' {
                    pi = pi.saturating_add(1);
                }
                if pi == p.len() {
                    return true;
                }
                for start in ti..=t.len() {
                    if glob_rec(t, p, start, pi) {
                        return true;
                    }
                }
                return false;
            }
            '?' => {
                if ti >= t.len() {
                    return false;
                }
                ti = ti.saturating_add(1);
                pi = pi.saturating_add(1);
            }
            '[' => {
                let Some((matches, next_pi)) = glob_class(p, pi, t.get(ti).copied()) else {
                    return false;
                };
                if ti >= t.len() || !matches {
                    return false;
                }
                ti = ti.saturating_add(1);
                pi = next_pi;
            }
            c => {
                if ti >= t.len() || t[ti] != c {
                    return false;
                }
                ti = ti.saturating_add(1);
                pi = pi.saturating_add(1);
            }
        }

match args.get(2) {
        Some(e) => as_text(e).chars().next(),
        None => None,
    }

match &args[0] {
        Value::Null => false,
        Value::Integer(i) => *i != 0,
        Value::Real(r) => *r != 0.0,
        Value::Text(s) => match crate::coerce::coerce_text_to_numeric(s) {
            Value::Integer(i) => i != 0,
            Value::Real(r) => r != 0.0,
            _ => false,
        },
        Value::Blob(_) => false,
    }

match crate::coerce::coerce_text_to_numeric(s) {
            Value::Integer(i) => i != 0,
            Value::Real(r) => r != 0.0,
            _ => false,
        }

match f {
        Some(f) => f(args),
        None => Err(FunctionError::Unknown {
            name: name.to_string(),
            arity,
        }),
    }

match &self.peek().kind {
            TokenKind::Eof => Ok(()),
            TokenKind::Keyword(Keyword::UNION)
            | TokenKind::Keyword(Keyword::INTERSECT)
            | TokenKind::Keyword(Keyword::EXCEPT) => {
                self.unsupported("compound SELECT (UNION/INTERSECT/EXCEPT) not yet supported")
            }
            other => {
                let tok = other.clone();
                Err(ParseFail::Invalid {
                    message: format!("unexpected trailing token {tok:?}"),
                    span: self.peek().span,
                })
            }
        }

match self.peek().kind.clone() {
            TokenKind::Identifier(name) => {
                let span = self.advance_span();
                Ok((name, span))
            }
            _ => {
                let tok = self.peek().clone();
                Err(ParseFail::Invalid {
                    message: format!("expected identifier, found {:?}", tok.kind),
                    span: tok.span,
                })
            }
        }

match tok.kind {
            TokenKind::Integer(v) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Integer(v)),
                    span: tok.span,
                })
            }
            TokenKind::Float(v) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Float(v)),
                    span: tok.span,
                })
            }
            TokenKind::String(s) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Str(s)),
                    span: tok.span,
                })
            }
            TokenKind::Blob(b) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Blob(*b)),
                    span: tok.span,
                })
            }
            TokenKind::Null => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Null),
                    span: tok.span,
                })
            }
            TokenKind::True => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::True),
                    span: tok.span,
                })
            }
            TokenKind::False => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::False),
                    span: tok.span,
                })
            }
            TokenKind::Keyword(Keyword::CURRENT_TIME)
            | TokenKind::Keyword(Keyword::CURRENT_DATE)
            | TokenKind::Keyword(Keyword::CURRENT_TIMESTAMP) => {
                self.unsupported("CURRENT_TIME/CURRENT_DATE/CURRENT_TIMESTAMP not yet supported")
            }
            _ => self.invalid("expected literal value after DEFAULT"),
        }

match self.peek().kind.clone() {
            TokenKind::Identifier(text) if text.eq_ignore_ascii_case("wal") => {
                let span = self.advance_span();
                Ok((PragmaJournalMode::Wal, span))
            }
            TokenKind::Keyword(Keyword::DELETE) => {
                let span = self.advance_span();
                Ok((PragmaJournalMode::Delete, span))
            }
            _ => self.unsupported("unsupported journal_mode value (only WAL/DELETE are supported)"),
        }

match self.peek().kind.clone() {
            TokenKind::Identifier(text) if text.eq_ignore_ascii_case("off") => {
                Ok((PragmaSynchronous::Off, self.advance_span()))
            }
            TokenKind::Identifier(text) if text.eq_ignore_ascii_case("normal") => {
                Ok((PragmaSynchronous::Normal, self.advance_span()))
            }
            // `FULL` is a reserved keyword (used in `FULL [OUTER] JOIN`),
            // never tokenized as a plain identifier -- same reason
            // `journal_mode`'s `DELETE` value needs its own keyword
            // match arm rather than falling out of `identifier()`.
            TokenKind::Keyword(Keyword::FULL) => Ok((PragmaSynchronous::Full, self.advance_span())),
            TokenKind::Integer(0) => Ok((PragmaSynchronous::Off, self.advance_span())),
            TokenKind::Integer(1) => Ok((PragmaSynchronous::Normal, self.advance_span())),
            TokenKind::Integer(2) => Ok((PragmaSynchronous::Full, self.advance_span())),
            _ => self.unsupported(
                "unsupported synchronous value (only OFF/NORMAL/FULL/0/1/2 are supported)",
            ),
        }

match self.peek().kind.clone() {
                TokenKind::Eq => {
                    self.advance();
                    let rhs = self.binary_expr(1)?;
                    bin(BinaryOp::Eq, lhs, rhs)
                }
                TokenKind::Ne => {
                    self.advance();
                    let rhs = self.binary_expr(1)?;
                    bin(BinaryOp::Ne, lhs, rhs)
                }
                TokenKind::Keyword(Keyword::IS) => {
                    self.advance();
                    let negated = self.eat_kw(Keyword::NOT);
                    let rhs = self.binary_expr(1)?;
                    let span = join_span(lhs.span, rhs.span);
                    Expr {
                        kind: ExprKind::Is {
                            lhs: Box::new(lhs),
                            rhs: Box::new(rhs),
                            negated,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::ISNULL) => {
                    let end = self.advance_span();
                    let span = join_span(lhs.span, end);
                    Expr {
                        kind: ExprKind::IsNull {
                            expr: Box::new(lhs),
                            negated: false,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::NOTNULL) => {
                    let end = self.advance_span();
                    let span = join_span(lhs.span, end);
                    Expr {
                        kind: ExprKind::IsNull {
                            expr: Box::new(lhs),
                            negated: true,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::BETWEEN) => {
                    self.advance();
                    let (lo, hi) = self.between_tail()?;
                    let span = join_span(lhs.span, hi.span);
                    Expr {
                        kind: ExprKind::Between {
                            expr: Box::new(lhs),
                            lo: Box::new(lo),
                            hi: Box::new(hi),
                            negated: false,
                        },
                        span,
                    }
                }
                TokenKind::Keyword(Keyword::IN) => {
                    self.advance();
                    self.in_tail(lhs, false)?
                }
                TokenKind::Keyword(Keyword::LIKE) | TokenKind::Keyword(Keyword::GLOB) => {
                    let glob = self.at_kw(Keyword::GLOB);
                    self.advance();
                    self.like_tail(lhs, glob, false)?
                }
                TokenKind::Keyword(Keyword::NOT) => match self.peek_at(1).kind.clone() {
                    TokenKind::Null => {
                        self.advance();
                        let end = self.advance_span();
                        let span = join_span(lhs.span, end);
                        Expr {
                            kind: ExprKind::IsNull {
                                expr: Box::new(lhs),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::BETWEEN) => {
                        self.advance();
                        self.advance();
                        let (lo, hi) = self.between_tail()?;
                        let span = join_span(lhs.span, hi.span);
                        Expr {
                            kind: ExprKind::Between {
                                expr: Box::new(lhs),
                                lo: Box::new(lo),
                                hi: Box::new(hi),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::IN) => {
                        self.advance();
                        self.advance();
                        self.in_tail(lhs, true)?
                    }
                    TokenKind::Keyword(Keyword::LIKE) | TokenKind::Keyword(Keyword::GLOB) => {
                        let glob =
                            matches!(self.peek_at(1).kind, TokenKind::Keyword(Keyword::GLOB));
                        self.advance();
                        self.advance();
                        self.like_tail(lhs, glob, true)?
                    }
                    _ => break,
                },
                _ => break,
            }

match self.peek_at(1).kind.clone() {
                    TokenKind::Null => {
                        self.advance();
                        let end = self.advance_span();
                        let span = join_span(lhs.span, end);
                        Expr {
                            kind: ExprKind::IsNull {
                                expr: Box::new(lhs),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::BETWEEN) => {
                        self.advance();
                        self.advance();
                        let (lo, hi) = self.between_tail()?;
                        let span = join_span(lhs.span, hi.span);
                        Expr {
                            kind: ExprKind::Between {
                                expr: Box::new(lhs),
                                lo: Box::new(lo),
                                hi: Box::new(hi),
                                negated: true,
                            },
                            span,
                        }
                    }
                    TokenKind::Keyword(Keyword::IN) => {
                        self.advance();
                        self.advance();
                        self.in_tail(lhs, true)?
                    }
                    TokenKind::Keyword(Keyword::LIKE) | TokenKind::Keyword(Keyword::GLOB) => {
                        let glob =
                            matches!(self.peek_at(1).kind, TokenKind::Keyword(Keyword::GLOB));
                        self.advance();
                        self.advance();
                        self.like_tail(lhs, glob, true)?
                    }
                    _ => break,
                }

match self.tokens.get(idx) {
                Some(t) => &t.kind,
                None => return false,
            }

match kind {
                TokenKind::Eof => return false,
                TokenKind::LParen => depth = depth.saturating_add(1),
                TokenKind::RParen => {
                    if depth == 0 {
                        let after_in = matches!(
                            self.tokens.get(idx.saturating_add(1)).map(|t| &t.kind),
                            Some(TokenKind::Keyword(Keyword::IN))
                        );
                        let after_not_in = matches!(
                            self.tokens.get(idx.saturating_add(1)).map(|t| &t.kind),
                            Some(TokenKind::Keyword(Keyword::NOT))
                        ) && matches!(
                            self.tokens.get(idx.saturating_add(2)).map(|t| &t.kind),
                            Some(TokenKind::Keyword(Keyword::IN))
                        );
                        return saw_top_comma && (after_in || after_not_in);
                    }
                    depth = depth.saturating_sub(1);
                }
                TokenKind::Comma if depth == 0 => saw_top_comma = true,
                _ => {}
            }

match self.expr_list() {
            Ok(list) => list,
            Err(_) => {
                self.pos = start_pos;
                return Ok(None);
            }
        }

match this.peek().kind {
                TokenKind::Plus => Some(UnaryOp::Plus),
                TokenKind::Minus => Some(UnaryOp::Minus),
                TokenKind::BitNot => Some(UnaryOp::BitNot),
                _ => None,
            }

match tok.kind {
            TokenKind::Integer(v) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Integer(v)),
                    span: tok.span,
                })
            }
            TokenKind::Float(v) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Float(v)),
                    span: tok.span,
                })
            }
            TokenKind::String(s) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Str(s)),
                    span: tok.span,
                })
            }
            TokenKind::Blob(b) => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Blob(*b)),
                    span: tok.span,
                })
            }
            TokenKind::Null => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::Null),
                    span: tok.span,
                })
            }
            TokenKind::True => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::True),
                    span: tok.span,
                })
            }
            TokenKind::False => {
                self.advance();
                Ok(Expr {
                    kind: ExprKind::Literal(Literal::False),
                    span: tok.span,
                })
            }
            TokenKind::Param(p) => {
                self.advance();
                let kind = match *p {
                    Param::Anonymous => ParamKind::Anonymous,
                    Param::Numbered(n) => ParamKind::Numbered(n),
                    Param::Colon(s) => ParamKind::Colon(s),
                    Param::At(s) => ParamKind::At(s),
                    Param::Dollar(s) => ParamKind::Dollar(s),
                };
                Ok(Expr {
                    kind: ExprKind::Param(kind),
                    span: tok.span,
                })
            }
            TokenKind::Keyword(Keyword::CURRENT_TIME)
            | TokenKind::Keyword(Keyword::CURRENT_DATE)
            | TokenKind::Keyword(Keyword::CURRENT_TIMESTAMP) => {
                self.unsupported("CURRENT_TIME/CURRENT_DATE/CURRENT_TIMESTAMP not yet supported")
            }
            TokenKind::Keyword(Keyword::CASE) => self.case_expr(),
            TokenKind::Keyword(Keyword::CAST) => self.cast_expr(),
            TokenKind::Keyword(Keyword::EXISTS) => {
                let start = tok.span;
                self.advance();
                self.exists_tail(start, false)
            }
            TokenKind::Identifier(name) => {
                self.advance();
                if matches!(self.peek().kind, TokenKind::LParen) {
                    return self.function_call(name, tok.span);
                }
                let mut parts = vec![name];
                while matches!(self.peek().kind, TokenKind::Dot) && parts.len() < 3 {
                    self.advance();
                    let (part, _) = self.identifier()?;
                    parts.push(part);
                }
                let end = self
                    .tokens
                    .get(self.pos.saturating_sub(1))
                    .map_or(tok.span, |t| t.span);
                let span = join_span(tok.span, end);
                let mut parts = parts.into_iter();
                let kind = match parts.len() {
                    1 => ExprKind::Column {
                        table: None,
                        catalog: None,
                        name: parts.next().unwrap_or_default(),
                    },
                    2 => ExprKind::Column {
                        catalog: None,
                        table: Some(parts.next().unwrap_or_default()),
                        name: parts.next().unwrap_or_default(),
                    },
                    _ => ExprKind::Column {
                        catalog: Some(parts.next().unwrap_or_default()),
                        table: Some(parts.next().unwrap_or_default()),
                        name: parts.next().unwrap_or_default(),
                    },
                };
                Ok(Expr { kind, span })
            }
            // SQLite treats most keywords as usable function names when
            // followed by `(` (e.g. `replace(...)`, `glob(...)`) — only
            // the handful matched above (CASE/CAST/EXISTS/CURRENT_*)
            // are true reserved words in expression position.
            TokenKind::Keyword(kw) if matches!(self.peek_at(1).kind, TokenKind::LParen) => {
                self.advance();
                self.function_call(format!("{kw:?}"), tok.span)
            }
            TokenKind::LParen => {
                self.advance();
                if self.at_kw(Keyword::SELECT) {
                    let subquery = self.parse_select_stmt()?;
                    if matches!(
                        self.peek().kind,
                        TokenKind::Keyword(Keyword::UNION)
                            | TokenKind::Keyword(Keyword::INTERSECT)
                            | TokenKind::Keyword(Keyword::EXCEPT)
                    ) {
                        return self.unsupported(
                            "compound SELECT (UNION/INTERSECT/EXCEPT) not yet supported",
                        );
                    }
                    let end = self.expect_punct(TokenKind::RParen, "')' to close subquery")?;
                    let span = join_span(tok.span, end);
                    return Ok(Expr {
                        kind: ExprKind::Subquery(Box::new(subquery)),
                        span,
                    });
                }
                let inner = self.expr()?;
                let end = self.expect_punct(TokenKind::RParen, "')' to close expression")?;
                let span = join_span(tok.span, end);
                Ok(Expr {
                    kind: ExprKind::Paren(Box::new(inner)),
                    span,
                })
            }
            other => Err(ParseFail::Invalid {
                message: format!("expected column or expression, found {other:?}"),
                span: tok.span,
            }),
        }

match parts.len() {
                    1 => ExprKind::Column {
                        table: None,
                        catalog: None,
                        name: parts.next().unwrap_or_default(),
                    },
                    2 => ExprKind::Column {
                        catalog: None,
                        table: Some(parts.next().unwrap_or_default()),
                        name: parts.next().unwrap_or_default(),
                    },
                    _ => ExprKind::Column {
                        catalog: Some(parts.next().unwrap_or_default()),
                        table: Some(parts.next().unwrap_or_default()),
                        name: parts.next().unwrap_or_default(),
                    },
                }

match self.peek().kind.clone() {
            TokenKind::Integer(v) => {
                self.advance();
                Ok(v.to_string())
            }
            other => {
                let span = self.peek().span;
                Err(ParseFail::Invalid {
                    message: format!("expected number, found {other:?}"),
                    span,
                })
            }
        }

match crate::parser::row::parse_select(sql) {
            crate::parser::row::ParseOutcome::Accepted(select) => *select,
            other => panic!("{sql:?} must parse, got {other:?}"),
        }

match &select.columns[0] {
            ResultColumn::Expr { expr, .. } => match &expr.kind {
                ExprKind::FunctionCall { tail, .. } => tail.clone(),
                other => panic!("expected a function call, got {other:?}"),
            },
            other => panic!("expected an expression column, got {other:?}"),
        }

match &expr.kind {
                ExprKind::FunctionCall { tail, .. } => tail.clone(),
                other => panic!("expected a function call, got {other:?}"),
            }

match parser.parse_select_stmt() {
        Ok(select) => match parser.expect_end() {
            Ok(()) => ParseOutcome::Accepted(Box::new(select)),
            Err(ParseFail::Unsupported { message, span }) => {
                ParseOutcome::Unsupported { message, span }
            }
            Err(ParseFail::Invalid { message, span }) => ParseOutcome::Invalid { message, span },
        },
        Err(ParseFail::Unsupported { message, span }) => {
            ParseOutcome::Unsupported { message, span }
        }
        Err(ParseFail::Invalid { message, span }) => ParseOutcome::Invalid { message, span },
    }

match parser.expect_end() {
            Ok(()) => ParseOutcome::Accepted(Box::new(select)),
            Err(ParseFail::Unsupported { message, span }) => {
                ParseOutcome::Unsupported { message, span }
            }
            Err(ParseFail::Invalid { message, span }) => ParseOutcome::Invalid { message, span },
        }

match parser.parse_explain_stmt() {
        Ok(explain) => match parser.expect_end() {
            Ok(()) => ParseOutcome::Accepted(Box::new(explain)),
            Err(ParseFail::Unsupported { message, span }) => {
                ParseOutcome::Unsupported { message, span }
            }
            Err(ParseFail::Invalid { message, span }) => ParseOutcome::Invalid { message, span },
        },
        Err(ParseFail::Unsupported { message, span }) => {
            ParseOutcome::Unsupported { message, span }
        }
        Err(ParseFail::Invalid { message, span }) => ParseOutcome::Invalid { message, span },
    }

match parser.expect_end() {
            Ok(()) => ParseOutcome::Accepted(Box::new(explain)),
            Err(ParseFail::Unsupported { message, span }) => {
                ParseOutcome::Unsupported { message, span }
            }
            Err(ParseFail::Invalid { message, span }) => ParseOutcome::Invalid { message, span },
        }

match parser.parse_insert_stmt() {
        Ok(insert) => match parser.expect_end() {
