match outcome {
            ParseOutcome::Accepted(_) => {}
            other => panic!("expected accepted for {src:?}, got {other:?}"),
        }

match outcome {
            ParseOutcome::Unsupported { .. } => {}
            other => panic!("expected unsupported for {src:?}, got {other:?}"),
        }

match outcome {
            ParseOutcome::Invalid { .. } => {}
            other => panic!("expected invalid for {src:?}, got {other:?}"),
        }

match self.distinct {
            Some(Distinctness::Distinct) => write!(f, " DISTINCT")?,
            Some(Distinctness::All) => write!(f, " ALL")?,
            None => {}
        }

match self.op {
            CompoundOp::UnionAll => write!(f, "UNION ALL SELECT")?,
            CompoundOp::Union => write!(f, "UNION SELECT")?,
        }

match self.distinct {
            Some(Distinctness::Distinct) => write!(f, " DISTINCT")?,
            Some(Distinctness::All) => write!(f, " ALL")?,
            None => {}
        }

match self {
            ResultColumn::Star => write!(f, "*"),
            ResultColumn::TableStar { table } => write!(f, "{table}.*"),
            ResultColumn::Expr { expr, alias } => {
                write!(f, "{expr}")?;
                if let Some(alias) = alias {
                    write!(f, " AS {alias}")?;
                }
                Ok(())
            }
        }

match &self.constraint {
            Some(JoinConstraint::On(expr)) => write!(f, " ON {expr}")?,
            Some(JoinConstraint::Using(cols)) => write!(f, " USING ({})", cols.join(", "))?,
            None => {}
        }

match self.desc {
            Some(false) => write!(f, " ASC")?,
            Some(true) => write!(f, " DESC")?,
            None => {}
        }

match self.nulls_last {
            Some(false) => write!(f, " NULLS FIRST")?,
            Some(true) => write!(f, " NULLS LAST")?,
            None => {}
        }

match &self.kind {
            ExprKind::Literal(lit) => write!(f, "{lit}"),
            ExprKind::Param(p) => write!(f, "{p}"),
            ExprKind::Column {
                catalog,
                table,
                name,
            } => {
                if let Some(catalog) = catalog {
                    write!(f, "{catalog}.")?;
                }
                if let Some(table) = table {
                    write!(f, "{table}.")?;
                }
                write!(f, "{name}")
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                tail,
            } => {
                write!(f, "{name}(")?;
                if *distinct {
                    write!(f, "DISTINCT ")?;
                }
                match args {
                    FunctionArgs::Star => write!(f, "*")?,
                    FunctionArgs::List(list) => {
                        for (i, a) in list.iter().enumerate() {
                            if i > 0 {
                                write!(f, ", ")?;
                            }
                            write!(f, "{a}")?;
                        }
                    }
                }
                write!(f, ")")?;
                if let Some(tail) = tail {
                    if let Some(filter) = &tail.filter {
                        write!(f, " FILTER (WHERE {filter})")?;
                    }
                    if let Some(over) = &tail.over {
                        write!(f, " OVER {over}")?;
                    }
                }
                Ok(())
            }
            ExprKind::Unary { op, expr } => {
                let op = match op {
                    UnaryOp::Not => "NOT ",
                    UnaryOp::Plus => "+",
                    UnaryOp::Minus => "-",
                    UnaryOp::BitNot => "~",
                };
                write!(f, "{op}{expr}")
            }
            ExprKind::Binary { op, lhs, rhs } => {
                write!(f, "{lhs} {} {rhs}", binop_str(*op))
            }
            ExprKind::Is { lhs, rhs, negated } => {
                write!(f, "{lhs} IS {}{rhs}", if *negated { "NOT " } else { "" })
            }
            ExprKind::IsNull { expr, negated } => {
                write!(f, "{expr} {}", if *negated { "NOTNULL" } else { "ISNULL" })
            }
            ExprKind::Between {
                expr,
                lo,
                hi,
                negated,
            } => write!(
                f,
                "{expr} {}BETWEEN {lo} AND {hi}",
                if *negated { "NOT " } else { "" }
            ),
            ExprKind::In {
                expr,
                list,
                negated,
            } => {
                write!(f, "{expr} {}IN (", if *negated { "NOT " } else { "" })?;
                for (i, e) in list.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{e}")?;
                }
                write!(f, ")")
            }
            ExprKind::Like {
                expr,
                pattern,
                glob,
                negated,
                escape,
            } => {
                let op = if *glob { "GLOB" } else { "LIKE" };
                write!(
                    f,
                    "{expr} {}{op} {pattern}",
                    if *negated { "NOT " } else { "" }
                )?;
                if let Some(escape) = escape {
                    write!(f, " ESCAPE {escape}")?;
                }
                Ok(())
            }
            ExprKind::Case {
                operand,
                whens,
                else_,
            } => {
                write!(f, "CASE")?;
                if let Some(operand) = operand {
                    write!(f, " {operand}")?;
                }
                for (cond, res) in whens {
                    write!(f, " WHEN {cond} THEN {res}")?;
                }
                if let Some(else_) = else_ {
                    write!(f, " ELSE {else_}")?;
                }
                write!(f, " END")
            }
            ExprKind::Cast { expr, type_name } => write!(f, "CAST({expr} AS {type_name})"),
            ExprKind::Collate { expr, collation } => write!(f, "{expr} COLLATE {collation}"),
            ExprKind::Paren(inner) => write!(f, "({inner})"),
            ExprKind::Subquery(select) => write!(f, "({select})"),
            ExprKind::Exists { subquery, negated } => {
                if *negated {
                    write!(f, "NOT EXISTS ({subquery})")
                } else {
                    write!(f, "EXISTS ({subquery})")
                }
            }
            ExprKind::InSubquery {
                expr,
                subquery,
                negated,
            } => {
                if *negated {
                    write!(f, "{expr} NOT IN ({subquery})")
                } else {
                    write!(f, "{expr} IN ({subquery})")
                }
            }
            ExprKind::InSubqueryMulti {
                exprs,
                subquery,
                negated,
            } => {
                write!(f, "(")?;
                for (i, e) in exprs.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "{e}")?;
                }
                write!(f, ")")?;
                if *negated {
                    write!(f, " NOT IN ({subquery})")
                } else {
                    write!(f, " IN ({subquery})")
                }
            }
        }

match args {
                    FunctionArgs::Star => write!(f, "*")?,
                    FunctionArgs::List(list) => {
                        for (i, a) in list.iter().enumerate() {
                            if i > 0 {
                                write!(f, ", ")?;
                            }
                            write!(f, "{a}")?;
                        }
                    }
                }

match op {
                    UnaryOp::Not => "NOT ",
                    UnaryOp::Plus => "+",
                    UnaryOp::Minus => "-",
                    UnaryOp::BitNot => "~",
                }

match self {
            Literal::Integer(v) => write!(f, "{v}"),
            Literal::Float(v) => write!(f, "{v}"),
            Literal::Str(s) => write!(f, "'{}'", s.replace('\'', "''")),
            Literal::Blob(bytes) => {
                write!(f, "X'")?;
                for b in bytes {
                    write!(f, "{b:02X}")?;
                }
                write!(f, "'")
            }
            Literal::Null => write!(f, "NULL"),
            Literal::True => write!(f, "TRUE"),
            Literal::False => write!(f, "FALSE"),
        }

match &self.source {
            InsertSource::DefaultValues => write!(f, " DEFAULT VALUES"),
            InsertSource::Values(rows) => {
                write!(f, " VALUES ")?;
                for (i, row) in rows.iter().enumerate() {
                    if i > 0 {
                        write!(f, ", ")?;
                    }
                    write!(f, "(")?;
                    for (j, expr) in row.iter().enumerate() {
                        if j > 0 {
                            write!(f, ", ")?;
                        }
                        write!(f, "{expr}")?;
                    }
                    write!(f, ")")?;
                }
                Ok(())
            }
            InsertSource::Select(select) => write!(f, " {select}"),
        }

match self {
            ColumnConstraint::NotNull => write!(f, "NOT NULL"),
            ColumnConstraint::PrimaryKey {
                desc,
                autoincrement,
            } => {
                write!(f, "PRIMARY KEY")?;
                match desc {
                    Some(false) => write!(f, " ASC")?,
                    Some(true) => write!(f, " DESC")?,
                    None => {}
                }
                if *autoincrement {
                    write!(f, " AUTOINCREMENT")?;
                }
                Ok(())
            }
            ColumnConstraint::Unique => write!(f, "UNIQUE"),
            ColumnConstraint::Default(value) => write!(f, "DEFAULT {value}"),
            ColumnConstraint::Check(expr) => write!(f, "CHECK ({expr})"),
            ColumnConstraint::Collate(name) => write!(f, "COLLATE {name}"),
        }

match desc {
                    Some(false) => write!(f, " ASC")?,
                    Some(true) => write!(f, " DESC")?,
                    None => {}
                }

match self {
            DefaultValue::Literal(expr) => write!(f, "{expr}"),
            DefaultValue::Paren(expr) => write!(f, "({expr})"),
        }

match self {
            TableConstraint::PrimaryKey(cols) => {
                write!(f, "PRIMARY KEY (")?;
                write_indexed_columns(f, cols)?;
                write!(f, ")")
            }
            TableConstraint::Unique(cols) => {
                write!(f, "UNIQUE (")?;
                write_indexed_columns(f, cols)?;
                write!(f, ")")
            }
            TableConstraint::Check(expr) => write!(f, "CHECK ({expr})"),
        }

match self.desc {
            Some(false) => write!(f, " ASC")?,
            Some(true) => write!(f, " DESC")?,
            None => {}
        }

