        } => validate_expr(inner),
        ExprKind::Unary { op, .. } => Err(unsupported(expr.span, format!("unary operator {op:?}"))),
        // `expr IS [NOT] NULL` may parse as `Is{lhs, rhs: NULL literal,
        // negated}` instead of the dedicated `IsNull` node.
        ExprKind::Is { lhs, rhs, .. }
            if matches!(rhs.kind, ExprKind::Literal(AstLiteral::Null)) =>
        {
            validate_expr(lhs)
        }
        ExprKind::Binary { op, lhs, rhs } => {
            ast_binop_allowed(*op, expr.span)?;
            validate_expr(lhs)?;
            validate_expr(rhs)
        }
        ExprKind::IsNull { expr: inner, .. } => validate_expr(inner),
        ExprKind::Paren(inner) => validate_expr(inner),
        ExprKind::InSubquery {
            expr: inner,
            subquery,
            negated: false,
        } => {
            validate_expr(inner)?;
            validate_select(subquery)
        }
        ExprKind::InSubquery { negated: true, .. } => {
            Err(unsupported(expr.span, "NOT IN (SELECT ...)".into()))
        }
        ExprKind::Exists { subquery, .. } => validate_select(subquery),
        other => Err(unsupported(
            expr.span,
            format!("unsupported expression form {other:?}"),
        )),
    }

match &mut from_clause.first.kind {
            TableRefKind::Name(name) => name.clone(),
            TableRefKind::Subquery(subselect) => {
                let Some(alias) = from_clause.first.alias.clone() else {
                    return Err(unsupported(
                        from_clause.first.span,
                        "a subquery in FROM requires an alias".into(),
                    ));
                };
                validate_select(subselect)?;
                alias
            }
        }

match &j.table.kind {
                TableRefKind::Name(table) => table.clone(),
                TableRefKind::Subquery(_) => {
                    return Err(unsupported(j.table.span, "subquery in JOIN".into()))
                }
            }

match &j.constraint {
                Some(JoinConstraint::On(expr)) => {
                    extract_equi_join(expr)?;
                }
                Some(JoinConstraint::Using(_)) => {
                    return Err(unsupported(j.table.span, "USING join".into()))
                }
                None if j.op == JoinOp::Cross => {}
                None => return Err(unsupported(j.table.span, "join without ON".into())),
            }

match &term.expr.kind {
            ExprKind::Column { .. } => {
                column_name(&term.expr)?;
            }
            ExprKind::FunctionCall {
                name,
                distinct,
                args,
                tail,
            } if !matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
                if *distinct {
                    return Err(unsupported(
                        term.expr.span,
                        "DISTINCT inside an aggregate".into(),
                    ));
                }
                validate_aggregate_call(&term.expr, name, args)?;
            }
            _ => {
                return Err(unsupported(
                    term.expr.span,
                    format!(
                        "expected a column reference or aggregate, found {:?}",
                        term.expr.kind
                    ),
                ))
            }
        }

match &select.limit {
        Some(l) => matches!(&l.limit.kind, ExprKind::Literal(AstLiteral::Integer(n)) if *n >= 0),
        None => true,
    }

match crate::parser::row::parse_select(sql_text) {
        ParseOutcome::Accepted(mut select) => {
            validate_select(&mut select)?;
            Ok(*select)
        }
        ParseOutcome::Unsupported { message, span } | ParseOutcome::Invalid { message, span } => {
            Err(from_outcome(message, span))
        }
    }

match crate::parser::row::parse_explain(sql_text) {
        ParseOutcome::Accepted(explain) => {
            let form = if explain.query_plan {
                Explain::QueryPlan
            } else {
                Explain::Opcodes
            };
            let mut select = *explain.select;
            validate_select(&mut select)?;
            Ok((form, select))
        }
        ParseOutcome::Unsupported { message, span } | ParseOutcome::Invalid { message, span } => {
            Err(from_outcome(message, span))
        }
    }

match rc {
            ResultColumn::Expr { expr, alias: None }
                if matches!(expr.kind, ExprKind::Column { .. }) =>
            {
                column_name(expr).ok()
            }
            _ => None,
        }

match &where_expr(&q).kind {
            ExprKind::IsNull { negated, .. } => assert!(!negated),
            ExprKind::Is { negated, .. } => assert!(!negated),
            other => panic!("expected IsNull-shaped expr, found {other:?}"),
        }

match &where_expr(&q).kind {
            ExprKind::IsNull { negated, .. } => assert!(negated),
            ExprKind::Is { negated, .. } => assert!(negated),
            other => panic!("expected IsNull-shaped expr, found {other:?}"),
        }

match self {
            Pragma::JournalMode { span, .. }
            | Pragma::IntegrityCheck { span, .. }
            | Pragma::Synchronous { span, .. } => *span,
        }

match self {
            PlanError::UnknownColumn(name) => write!(f, "unknown column: {name}"),
            PlanError::UnsupportedSemiJoin(msg) => write!(f, "unsupported semi-join: {msg}"),
            PlanError::UnsupportedJoinKind(kind) => write!(
                f,
                "join kind {kind:?} is not yet executable (only Inner/Left are implemented)"
            ),
            PlanError::StarWithAggregation => write!(
                f,
                "SELECT * cannot be combined with GROUP BY, an aggregate, or a window function"
            ),
            PlanError::UnsupportedSelectItem(msg) => write!(f, "unsupported SELECT item: {msg}"),
        }

match &expr.kind {
        ExprKind::Column {
            table: None,
            catalog: None,
            name,
        } => Some(name.clone()),
        ExprKind::Column {
            table: Some(table),
            catalog: None,
            name,
        } => Some(format!("{table}.{name}")),
        _ => None,
    }

match args {
        FunctionArgs::Star => {
            if agg != AggFunc::Count {
                return Err(PlanError::UnsupportedSelectItem(
                    "only COUNT supports (*)".into(),
                ));
            }
            Ok(None)
        }
        FunctionArgs::List(list) => match list.as_slice() {
            [one] => expr_column_name(one).map(Some).ok_or_else(|| {
                PlanError::UnsupportedSelectItem("expected a column reference".into())
            }),
            _ => Err(PlanError::UnsupportedSelectItem(
                "an aggregate takes exactly one column or *".into(),
            )),
        },
    }

match list.as_slice() {
            [one] => expr_column_name(one).map(Some).ok_or_else(|| {
                PlanError::UnsupportedSelectItem("expected a column reference".into())
            }),
            _ => Err(PlanError::UnsupportedSelectItem(
                "an aggregate takes exactly one column or *".into(),
            )),
        }

match (func.is_niladic(), args) {
        (true, FunctionArgs::List(list)) if list.is_empty() => (None, None),
        (true, _) => {
            return Err(PlanError::UnsupportedSelectItem(format!(
                "{name} takes no arguments"
            )))
        }
        (false, FunctionArgs::Star) => {
            if func != WindowFunc::Count {
                return Err(PlanError::UnsupportedSelectItem(
                    "only COUNT supports (*)".into(),
                ));
            }
            (None, None)
        }
        (false, FunctionArgs::List(list)) if matches!(func, WindowFunc::Lag | WindowFunc::Lead) => {
            match list.as_slice() {
                [one] => (expr_column_name(one), None),
                [one, offset_expr] => {
                    let offset = match &offset_expr.kind {
                        ExprKind::Literal(AstLiteral::Integer(n)) => Some(*n),
                        _ => {
                            return Err(PlanError::UnsupportedSelectItem(
                                "non-integer offset".into(),
                            ))
                        }
                    };
                    (expr_column_name(one), offset)
                }
                _ => {
                    return Err(PlanError::UnsupportedSelectItem(format!(
                        "{name} takes 1 or 2 arguments"
                    )))
                }
            }
        }
        (false, FunctionArgs::List(list)) => match list.as_slice() {
            [one] => (expr_column_name(one), None),
            _ => {
                return Err(PlanError::UnsupportedSelectItem(
                    "a window function takes exactly one column or *".into(),
                ))
            }
        },
    }

match list.as_slice() {
                [one] => (expr_column_name(one), None),
                [one, offset_expr] => {
                    let offset = match &offset_expr.kind {
                        ExprKind::Literal(AstLiteral::Integer(n)) => Some(*n),
                        _ => {
                            return Err(PlanError::UnsupportedSelectItem(
                                "non-integer offset".into(),
                            ))
                        }
                    };
                    (expr_column_name(one), offset)
                }
                _ => {
                    return Err(PlanError::UnsupportedSelectItem(format!(
                        "{name} takes 1 or 2 arguments"
                    )))
                }
            }

match &offset_expr.kind {
                        ExprKind::Literal(AstLiteral::Integer(n)) => Some(*n),
                        _ => {
                            return Err(PlanError::UnsupportedSelectItem(
                                "non-integer offset".into(),
                            ))
                        }
                    }

match list.as_slice() {
            [one] => (expr_column_name(one), None),
            _ => {
                return Err(PlanError::UnsupportedSelectItem(
                    "a window function takes exactly one column or *".into(),
                ))
            }
        }

match col {
        ResultColumn::Star => Ok(Item::Star),
        ResultColumn::TableStar { .. } => Err(PlanError::UnsupportedSelectItem(
            "table.* is not supported".into(),
        )),
        ResultColumn::Expr {
            expr: _,
            alias: Some(_),
        } => Err(PlanError::UnsupportedSelectItem(
            "column alias (AS) is not supported".into(),
        )),
        ResultColumn::Expr { expr, alias: None } => match &expr.kind {
            ExprKind::Column { .. } => expr_column_name(expr).map(Item::Column).ok_or_else(|| {
                PlanError::UnsupportedSelectItem("expected a column reference".into())
            }),
            ExprKind::FunctionCall {
                name,
                distinct: _,
                args,
                tail,
            } if matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
                #[allow(clippy::expect_used, reason = "guarded by the match's `if` above")]
                let window_def = tail
                    .as_deref()
                    .and_then(|t| t.over.as_ref())
                    .expect("guarded by the match's `if` above");
                let mut spec = window_spec(name, args, window_def)?;
                let filter = tail.as_deref().and_then(|t| t.filter.as_ref());
                if let Some(f) = filter {
                    if !matches!(
                        spec.func,
                        WindowFunc::Sum | WindowFunc::Avg | WindowFunc::Count
                    ) {
                        return Err(PlanError::UnsupportedSelectItem(format!(
                            "FILTER is not supported on {name} (only SUM/AVG/COUNT window aggregates accept it)"
                        )));
                    }
                    spec.filter = Some(f.clone());
                }
                Ok(Item::Window(spec))
            }
            ExprKind::FunctionCall {
                name,
                distinct: _,
                args,
                tail,
            } => {
                let agg = AggFunc::from_name(name).ok_or_else(|| {
                    PlanError::UnsupportedSelectItem(format!("unknown function {name}"))
                })?;
                let arg = agg_arg(expr, agg, args)?;
                let filter = tail.as_deref().and_then(|t| t.filter.clone());
                Ok(Item::Agg(agg, arg, filter))
            }
            _ => Ok(Item::Expr(expr.clone())),
        },
    }

match &expr.kind {
            ExprKind::Column { .. } => expr_column_name(expr).map(Item::Column).ok_or_else(|| {
                PlanError::UnsupportedSelectItem("expected a column reference".into())
            }),
            ExprKind::FunctionCall {
                name,
                distinct: _,
                args,
                tail,
            } if matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
                #[allow(clippy::expect_used, reason = "guarded by the match's `if` above")]
                let window_def = tail
                    .as_deref()
                    .and_then(|t| t.over.as_ref())
                    .expect("guarded by the match's `if` above");
                let mut spec = window_spec(name, args, window_def)?;
                let filter = tail.as_deref().and_then(|t| t.filter.as_ref());
                if let Some(f) = filter {
                    if !matches!(
                        spec.func,
                        WindowFunc::Sum | WindowFunc::Avg | WindowFunc::Count
                    ) {
                        return Err(PlanError::UnsupportedSelectItem(format!(
                            "FILTER is not supported on {name} (only SUM/AVG/COUNT window aggregates accept it)"
                        )));
                    }
                    spec.filter = Some(f.clone());
                }
                Ok(Item::Window(spec))
            }
            ExprKind::FunctionCall {
                name,
                distinct: _,
                args,
                tail,
            } => {
                let agg = AggFunc::from_name(name).ok_or_else(|| {
                    PlanError::UnsupportedSelectItem(format!("unknown function {name}"))
                })?;
                let arg = agg_arg(expr, agg, args)?;
                let filter = tail.as_deref().and_then(|t| t.filter.clone());
                Ok(Item::Agg(agg, arg, filter))
            }
            _ => Ok(Item::Expr(expr.clone())),
        }

match &expr.kind {
        ExprKind::Binary {
            op: AstBinOp::Eq,
            lhs,
            rhs,
        } => Some((expr_column_name(lhs)?, expr_column_name(rhs)?)),
        _ => None,
    }

match &j.constraint {
                Some(JoinConstraint::On(expr)) => extract_equi_join(expr)
                    .ok_or_else(|| PlanError::UnknownColumn("JOIN ON must be col = col".into()))?,
                None if j.op == JoinOp::Cross => (String::new(), String::new()),
                _ => {
                    return Err(PlanError::UnknownColumn(
                        "unsupported JOIN condition".into(),
                    ))
                }
            }

match lit {
        AstLiteral::Integer(v) => Value::Int(*v),
        AstLiteral::Float(v) => Value::Float(*v),
        AstLiteral::Str(v) => Value::Str(v.clone().into()),
        // Blob/Null/True/False aren't part of the batch planner's literal
        // subset (`parser::column`'s validator rejects them before this
        // module ever runs) -- fall back to NULL rather than panicking.
        AstLiteral::Blob(_) | AstLiteral::Null | AstLiteral::True | AstLiteral::False => {
            Value::Null
        }
    }

match &limit.limit.kind {
        ExprKind::Literal(AstLiteral::Integer(n)) if *n >= 0 => Some(*n as usize),
        _ => None,
    }

match args {
        FunctionArgs::Star if agg == AggFunc::Count => Some(format!("{}(*)", agg.name())),
        FunctionArgs::Star => None,
        FunctionArgs::List(list) => match list.as_slice() {
            [one] => expr_column_name(one).map(|col| format!("{}({col})", agg.name())),
            _ => None,
        },
    }

match list.as_slice() {
            [one] => expr_column_name(one).map(|col| format!("{}({col})", agg.name())),
            _ => None,
        }

match &term.expr.kind {
        ExprKind::Column { .. } => expr_column_name(&term.expr)?,
        ExprKind::FunctionCall {
            name, args, tail, ..
        } if !matches!(tail.as_deref(), Some(t) if t.over.is_some()) => {
            aggregate_call_label(name, args)?
        }
        _ => return None,
    }

match item {
            Item::Star => columns.extend(schema.iter().map(|name| ResultColumn::Expr {
                expr: crate::parser::ast::Expr {
                    kind: ExprKind::Column {
                        table: None,
                        catalog: None,
                        name: name.clone(),
                    },
                    span: crate::parser::Span::UNKNOWN,
                },
                alias: None,
            })),
            _ => columns.push(col.clone()),
        }

match op {
        AstBinOp::Add => MapOp::Add,
        AstBinOp::Sub => MapOp::Sub,
        AstBinOp::Mul => MapOp::Mul,
        AstBinOp::Div => MapOp::Div,
        AstBinOp::Eq => MapOp::Eq,
        AstBinOp::Ne => MapOp::Ne,
        AstBinOp::Lt => MapOp::Lt,
        AstBinOp::Le => MapOp::Le,
        AstBinOp::Gt => MapOp::Gt,
        AstBinOp::Ge => MapOp::Ge,
        AstBinOp::And => MapOp::And,
        AstBinOp::Or => MapOp::Or,
        AstBinOp::Concat => MapOp::Concat,
        // `parser::column`'s validator rejects every other operator
        // (bitwise/shift/modulo) before this module ever sees the query --
        // reaching here means an unvalidated `Select` was compiled
        // directly. Fall back to `Eq` rather than panicking.
        AstBinOp::BitAnd | AstBinOp::BitOr | AstBinOp::Shl | AstBinOp::Shr | AstBinOp::Mod => {
            MapOp::Eq
        }
    }

match &expr.kind {
        ExprKind::Column { .. } => match expr_column_name(expr) {
            Some(name) => ctx.load_column(&name),
            None => {
                let reg = ctx.alloc();
                ctx.push(Opcode::LoadConst {
                    reg,
                    value: Value::Null,
                });
                reg
            }
        },
        ExprKind::Literal(lit) => {
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: literal_value(lit),
            });
            reg
        }
        ExprKind::Paren(inner) => compile_expr(inner, ctx),
        // `compile_semi_join` handles `IN (subquery)` itself and strips it
        // from `where_clause` before ever calling `compile` -- reaching
        // this arm means `IN (subquery)`/`EXISTS` was used via the regular
        // single-table path, which can't run a subquery. Compile to an
        // always-false predicate (no rows) rather than panicking.
        ExprKind::InSubquery { .. } | ExprKind::Exists { .. } => {
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: Value::Bool(false),
            });
            reg
        }
        ExprKind::Binary { op, lhs, rhs } => {
            let a = compile_expr(lhs, ctx);
            let b = compile_expr(rhs, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: map_bin_op(*op),
                a,
                b,
            });
            dst
        }
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Not,
            expr: inner,
        } => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: MapOp::Not,
                a,
                b: a,
            });
            dst
        }
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Minus,
            expr: inner,
        } => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: MapOp::Neg,
                a,
                b: a,
            });
            dst
        }
        // Unary `+` is a no-op.
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Plus,
            expr: inner,
        } => compile_expr(inner, ctx),
        ExprKind::Unary { expr: inner, .. } => compile_expr(inner, ctx),
        ExprKind::IsNull {
            expr: inner,
            negated,
        } => {
            let a = compile_expr(inner, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: if *negated {
                    MapOp::IsNotNull
                } else {
                    MapOp::IsNull
                },
                a,
                b: a,
            });
            dst
        }
        // `expr IS [NOT] NULL` may also parse as `Is{lhs, rhs: NULL
        // literal, negated}`.
        ExprKind::Is { lhs, rhs, negated }
            if matches!(rhs.kind, ExprKind::Literal(AstLiteral::Null)) =>
        {
            let a = compile_expr(lhs, ctx);
            let dst = ctx.alloc();
            ctx.push(Opcode::Map {
                dst,
                op: if *negated {
                    MapOp::IsNotNull
                } else {
                    MapOp::IsNull
                },
                a,
                b: a,
            });
            dst
        }
        // Anything else is outside the validated batch subset -- fall
        // back to NULL rather than panicking.
        _ => {
            let reg = ctx.alloc();
            ctx.push(Opcode::LoadConst {
                reg,
                value: Value::Null,
            });
            reg
        }
    }

match expr_column_name(expr) {
            Some(name) => ctx.load_column(&name),
            None => {
                let reg = ctx.alloc();
                ctx.push(Opcode::LoadConst {
                    reg,
                    value: Value::Null,
                });
                reg
            }
        }

match item {
            Item::Agg(_, arg, filter) => {
                let base = arg.as_ref().map(|name| ctx.load_column(name));
                agg_srcs.push(mask_filtered_source(&mut ctx, base, filter.as_ref()));
            }
            // Plain projected columns are emitted (not aggregated), but they
            // must be loaded here for the same reason as the keys above: a
            // column first loaded below the Filter keeps its full pre-filter
            // length while the filtered registers shrink, and Emit then
            // indexes past the end of the short ones. `load_column` memoizes,
            // so the projection code further down reuses these registers
            // instead of emitting a second LoadColumn.
            Item::Column(name) if group_by.is_empty() => {
                ctx.load_column(name);
                agg_srcs.push(None);
            }
            Item::Expr(expr) if group_by.is_empty() => {
                let mut cols = Vec::new();
                collect_expr_columns(expr, &mut cols);
                for name in &cols {
                    ctx.load_column(name);
                }
                agg_srcs.push(None);
            }
            _ => agg_srcs.push(None),
        }

match simple_part {
                Some(part) => {
                    let dst = ctx.alloc();
                    aggs.push((*func, src));
                    agg_dst.push(dst);
                    agg_parts.push(part);
                    emit_regs.push(dst);
                }
                None => {
                    let sum_dst = ctx.alloc();
                    let count_dst = ctx.alloc();
                    aggs.push((AggFunc::Sum, src));
                    agg_dst.push(sum_dst);
                    aggs.push((AggFunc::Count, src));
                    agg_dst.push(count_dst);
                    let sum_pos = emit_regs.len();
                    agg_parts.push(AggPart::Avg(sum_pos, sum_pos.saturating_add(1)));
                    emit_regs.push(sum_dst);
                    emit_regs.push(count_dst);
                }
            }

match name.split_once('.') {
        Some((table, column)) => (Some(table), column),
        None => (None, name),
    }

match prefix {
            None => left_columns.push(name.clone()),
            Some(p) if p == from_name => left_columns.push(name.clone()),
            Some(p) if p == join.table => right_columns.push(name.clone()),
            Some(_) => return Err(PlanError::UnknownColumn(name.clone())),
        }

match join.op {
        JoinOp::Inner => crate::vm::batch::JoinKind::Inner,
        JoinOp::Left => crate::vm::batch::JoinKind::Left,
        other => return Err(PlanError::UnsupportedJoinKind(other)),
    }

match item {
            Item::Column(name) => push_needed(name, &mut needed),
            Item::Window(spec) => {
                if let Some(arg) = &spec.arg {
                    push_needed(arg, &mut needed);
                }
                for p in &spec.partition_by {
                    push_needed(p, &mut needed);
                }
                for (o, _) in &spec.order_by {
                    push_needed(o, &mut needed);
                }
            }
            Item::Agg(..) | Item::Star | Item::Expr(_) => {}
        }

match item {
            Item::Window(spec) => {
                let base = spec.arg.as_ref().map(|name| ctx.load_column(name));
                mask_filtered_source(&mut ctx, base, spec.filter.as_ref())
            }
            _ => None,
        }

match item {
            Item::Column(name) => emit_regs.push(column_reg(name)),
            Item::Window(spec) => {
                let dst = next_reg;
                next_reg = next_reg.saturating_add(1);
                program.push(Instruction::with_comment(
                    Opcode::Window {
                        func: map_window_func(spec.func),
                        // Already resolved (and `FILTER`-masked, if any)
                        // above -- same register `column_reg(arg)` would
                        // give when there's no filter, since `needed`
                        // seeded `ctx`'s `column_regs`.
                        arg: *filtered_arg,
                        offset: spec.offset,
                        partition_by: spec
                            .partition_by
                            .iter()
                            .map(|p| column_reg(p))
                            .collect::<Vec<_>>()
                            .into(),
                        order_by: spec
                            .order_by
                            .iter()
                            .map(|(o, desc)| (column_reg(o), *desc))
                            .collect::<Vec<_>>()
                            .into(),
                        dst,
                    },
                    format!("r{dst} = {}", window_detail(spec)),
                ));
                emit_regs.push(dst);
            }
            Item::Agg(..) | Item::Star | Item::Expr(_) => {
                let reg = *null_reg.get_or_insert_with(|| {
                    let reg = next_reg;
                    next_reg = next_reg.saturating_add(1);
                    program.push(Instruction::new(Opcode::LoadConst {
                        reg,
                        value: Value::Null,
                    }));
                    reg
                });
                emit_regs.push(reg);
            }
        }

match src {
        Some(s) => format!("{func:?}({s})"),
        None => format!("{func:?}"),
    }

match op {
        Opcode::LoadColumn { reg, column } => format!("reg={reg} column={column}"),
        Opcode::LoadConst { reg, value } => format!("reg={reg} value={value}"),
        Opcode::Map { dst, op, a, b } => format!("dst={dst} op={op:?} a={a} b={b}"),
        Opcode::Filter { predicate } => format!("predicate=r{predicate}"),
        Opcode::Reduce { func, src, dst } => {
            format!("dst={dst} {}", render_agg_pair(*func, *src))
        }
        Opcode::GroupReduce {
            group_by,
            aggs,
            agg_dst,
        } => {
            let aggs: Vec<String> = aggs
                .iter()
                .map(|(func, src)| render_agg_pair(*func, *src))
                .collect();
            format!(
                "group_by={group_by:?} aggs=[{}] agg_dst={agg_dst:?}",
                aggs.join(", ")
            )
        }
        Opcode::HashBuild {
            key_cols,
            payload_cols,
            table,
        } => format!("key_cols={key_cols:?} payload_cols={payload_cols:?} table={table}"),
        Opcode::HashProbe {
            key_cols,
            table,
            payload_dst,
            kind,
        } => format!("key_cols={key_cols:?} table={table} payload_dst={payload_dst:?} kind={kind:?}"),
        Opcode::Window {
            func,
            arg,
            offset,
            partition_by,
            order_by,
            dst,
        } => format!(
            "dst={dst} func={func:?} arg={arg:?} offset={offset:?} partition_by={partition_by:?} order_by={order_by:?}"
        ),
        Opcode::Scan => String::new(),
        Opcode::Emit { registers } => format!("registers={registers:?}"),
        Opcode::NextSegment { loop_start } => format!("loop_start={loop_start}"),
        Opcode::Halt => String::new(),
        Opcode::Combine {
            agg_parts,
            num_group_keys,
            distinct,
        } => format!("agg_parts={agg_parts:?} num_group_keys={num_group_keys} distinct={distinct}"),
        Opcode::Sort { col, descending } => format!("col={col} descending={descending}"),
        Opcode::Limit { n } => format!("n={n}"),
    }

match classify_item(item) {
        Ok(Item::Column(name)) => name,
        Ok(Item::Star) => "*".to_string(),
        Ok(Item::Agg(func, arg, _)) => match arg {
            Some(col) => format!("{}({col})", agg_func_name(func)),
            None => format!("{}(*)", agg_func_name(func)),
        },
        Ok(Item::Window(spec)) => format!("{}()", window_func_name(spec.func)),
        Ok(Item::Expr(expr)) => expr_to_string(&expr),
        Err(_) => String::new(),
    }

match arg {
            Some(col) => format!("{}({col})", agg_func_name(func)),
            None => format!("{}(*)", agg_func_name(func)),
        }

match &expr.kind {
        ExprKind::Column { .. } => expr_column_name(expr).unwrap_or_default(),
        ExprKind::Literal(lit) => literal_to_string(lit),
        ExprKind::Paren(inner) => expr_to_string(inner),
        ExprKind::Binary { op, lhs, rhs } => {
            format!(
                "{} {} {}",
                expr_to_string(lhs),
                bin_op_str(*op),
                expr_to_string(rhs)
            )
        }
        ExprKind::InSubquery { expr, subquery, .. } => {
            let from = subquery.from.as_ref().map(table_name).unwrap_or_default();
            format!("{} IN (SELECT ... FROM {from})", expr_to_string(expr))
        }
        ExprKind::Exists { subquery, negated } => {
            let from = subquery.from.as_ref().map(table_name).unwrap_or_default();
            format!(
                "{}EXISTS (SELECT ... FROM {from})",
                if *negated { "NOT " } else { "" }
            )
        }
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Not,
            expr: inner,
        } => format!("NOT {}", expr_to_string(inner)),
        ExprKind::Unary {
            op: crate::parser::ast::UnaryOp::Minus,
            expr: inner,
        } => format!("-{}", expr_to_string(inner)),
        ExprKind::Unary { expr: inner, .. } => expr_to_string(inner),
        ExprKind::IsNull { expr, negated } => {
            format!(
                "{} IS {}NULL",
                expr_to_string(expr),
                if *negated { "NOT " } else { "" }
            )
        }
        ExprKind::Is { lhs, rhs, negated }
            if matches!(rhs.kind, ExprKind::Literal(AstLiteral::Null)) =>
        {
            format!(
                "{} IS {}NULL",
                expr_to_string(lhs),
                if *negated { "NOT " } else { "" }
            )
        }
        _ => String::new(),
    }

match &expr.kind {
        ExprKind::Column { .. } => {
            if let Some(name) = expr_column_name(expr) {
                push_unique(out, name);
            }
        }
        ExprKind::Literal(_) => {}
        ExprKind::Paren(inner) => collect_expr_columns(inner, out),
        ExprKind::Binary { lhs, rhs, .. } => {
            collect_expr_columns(lhs, out);
            collect_expr_columns(rhs, out);
        }
        ExprKind::InSubquery { expr, .. } => collect_expr_columns(expr, out),
        ExprKind::Exists { .. } => {}
        ExprKind::Unary { expr: inner, .. } => collect_expr_columns(inner, out),
        ExprKind::IsNull { expr, .. } => collect_expr_columns(expr, out),
        ExprKind::Is { lhs, .. } => collect_expr_columns(lhs, out),
        _ => {}
    }

match item {
            Item::Column(name) => push_unique(&mut out, name.clone()),
            Item::Star => {}
            Item::Agg(_, arg, filter) => {
                if let Some(name) = arg {
                    push_unique(&mut out, name.clone());
                }
                if let Some(f) = filter {
                    let mut cols = Vec::new();
                    collect_expr_columns(f, &mut cols);
                    for name in cols {
                        push_unique(&mut out, name);
                    }
                }
            }
            Item::Window(spec) => {
                if let Some(arg) = &spec.arg {
                    push_unique(&mut out, arg.clone());
                }
                for name in &spec.partition_by {
                    push_unique(&mut out, name.clone());
                }
                for (name, _) in &spec.order_by {
                    push_unique(&mut out, name.clone());
                }
                if let Some(f) = &spec.filter {
                    collect_expr_columns(f, &mut out);
                }
            }
            Item::Expr(expr) => collect_expr_columns(expr, &mut out),
        }

match c {
            TableConstraint::Check(expr) => Some(expr.clone()),
            TableConstraint::PrimaryKey(_) | TableConstraint::Unique(_) => None,
        }

match rowid_alias.and_then(|idx| assigned.get(idx).copied().flatten()) {
        Some(expr) => compile_value(em, reg, scope, expr)?,
        None => {
            let r = reg.alloc();
            em.emit(Instruction::new(Opcode::Rowid, TABLE_CURSOR, r, 0));
            r
        }
    }

match expr {
            Some(expr) => compile_value(em, reg, scope, expr)?,
            None => {
                let r = reg.alloc();
                emit_column_read(em, schema, TABLE_CURSOR, idx, r)?;
                r
            }
        }

match parse_create_table(&schema.sql) {
        ParseOutcome::Accepted(create) => Arc::new(*create),
        ParseOutcome::Unsupported { message, .. } | ParseOutcome::Invalid { message, .. } => {
            return Err(CodegenError::Unsupported {
                reason: format!("could not recover constraints from schema DDL: {message}"),
            })
        }
    }

match source {
        ColumnSource::Expr(expr) => compile_value(
            em,
            reg,
            &crate::codegen::row::Scope::single(schema, cursor),
            expr,
        ),
        ColumnSource::Reg(src) => {
            let dest = reg.alloc();
            em.emit(Instruction::new(Opcode::Copy, *src, dest, 0));
            Ok(dest)
        }
    }

match c {
            TableConstraint::Check(expr) => Some(expr.clone()),
            TableConstraint::PrimaryKey(_) | TableConstraint::Unique(_) => None,
        }

match &insert.columns {
        Some(names) => {
            let mut out = Vec::with_capacity(names.len());
            for name in names {
                let idx = column_index(schema, name)
                    .ok_or_else(|| CodegenError::UnknownColumn { name: name.clone() })?;
                out.push(idx);
            }
            out
        }
        None => (0..schema.columns.len()).collect(),
    }

match select_schemas {
            Some([single]) => select_result_column_count(select, single),
            Some(joined) if joined.len() > 1 => {
                let Some(from) = &select.from else {
                    return Err(CodegenError::NoFromClause);
                };
                let table_refs: Vec<&TableRef> = std::iter::once(&from.first)
                    .chain(from.joins.iter().map(|j| &j.table))
                    .collect();
                select_result_column_count_joined(select, joined, &table_refs)?
            }
            Some(_) | None => {
                return Err(CodegenError::Unsupported {
                    reason: "INSERT ... SELECT: the SELECT's FROM table schema(s) were not \
                             resolved"
                        .to_string(),
                })
            }
        }

match &insert.source {
        InsertSource::Values(rows) => {
            for values in rows {
                compile_row(
                    &mut em,
                    &mut reg,
                    schema,
                    &check_schema,
                    &plans,
                    &table_checks,
                    &target_columns,
                    |pos| values.get(pos).cloned().map(ColumnSource::Expr),
                    rowid_alias,
                    action,
                    is_autoincrement,
                )?;
            }
        }
        InsertSource::DefaultValues => {
            compile_row(
                &mut em,
                &mut reg,
                schema,
                &check_schema,
                &plans,
                &table_checks,
                &target_columns,
                |_pos| None,
                rowid_alias,
                action,
                is_autoincrement,
            )?;
        }
        InsertSource::Select(select) => {
            // Re-checked (rather than trusted from the validation above)
            // so this arm never needs an infallible unwrap.
            let Some(select_schemas) = select_schemas else {
                return Err(CodegenError::Unsupported {
                    reason: "INSERT ... SELECT: the SELECT's FROM table schema(s) were not \
                             resolved"
                        .to_string(),
                });
            };
            // The select's source-table scan needs cursor numbers of its
            // own, distinct from this INSERT's target-table/index
            // cursors above — offset above the last index cursor
            // (`open_index_cursors` uses `FIRST_INDEX_CURSOR..
            // FIRST_INDEX_CURSOR+schema.indexes.len()`).
            let select_table_cursor =
                FIRST_INDEX_CURSOR.saturating_add(i32::try_from(schema.indexes.len()).unwrap_or(0));
            let end_label = em.new_label();
            let mut sink = |em: &mut Emitter, reg: &mut RegAlloc, first: i32, count: i32| {
                let count = usize::try_from(count).unwrap_or(0);
                compile_row(
                    em,
                    reg,
                    schema,
                    &check_schema,
                    &plans,
                    &table_checks,
                    &target_columns,
                    |pos| {
                        (pos < count)
                            .then(|| first.saturating_add(i32::try_from(pos).unwrap_or(i32::MAX)))
                            .map(ColumnSource::Reg)
                    },
                    rowid_alias,
                    action,
                    is_autoincrement,
                )
            };
            if select_schemas.len() > 1 {
                // #250: the SELECT's FROM clause has a JOIN — drive the
                // same nested-loop join scan `compile_select_joined`
                // uses, with cursor numbers offset above this INSERT's
                // own cursors (`compile_select_joined_scan` opens every
                // source-table cursor itself, unlike the single-table
                // `compile_select_scan` path below, which expects its
                // one cursor already open).
                // `select_schemas` doubles as the full catalog for a
                // subquery-in-FROM to resolve its own inner FROM table(s)
                // against (#257) — narrower than `compile_select_joined`'s
                // own full-database catalog, so `INSERT ... SELECT` with
                // both a JOIN and a FROM-subquery whose own table isn't
                // among the SELECT's joined tables isn't supported yet.
                compile_select_joined_scan(
                    &mut em,
                    &mut reg,
                    select,
                    select_schemas,
                    select_schemas,
                    select_table_cursor,
                    end_label,
                    &std::collections::HashMap::new(),
                    &mut sink,
                )?;
            } else {
                let Some(select_schema) = select_schemas.first() else {
                    return Err(CodegenError::Unsupported {
                        reason: "INSERT ... SELECT: the SELECT's FROM table schema was not \
                                 resolved"
                            .to_string(),
                    });
                };
                let select_cursors = ScanCursors {
                    table: select_table_cursor,
                    sort: select_table_cursor.saturating_add(1),
                    pseudo: select_table_cursor.saturating_add(2),
                    distinct: select_table_cursor.saturating_add(3),
                };
                let select_root_page = valid_table_root_page(select_schema)?;
                em.emit(Instruction::new(
                    Opcode::OpenRead,
                    select_cursors.table,
                    select_root_page,
                    0,
                ));
                compile_select_scan(
                    &mut em,
                    &mut reg,
                    select,
                    select_schema,
                    select_cursors,
                    end_label,
                    std::slice::from_ref(select_schema),
                    &crate::codegen::row::planner::Stats::default(),
                    &mut sink,
                )?;
            }
            em.place(end_label);
        }
    }

match constraint {
                ColumnConstraint::NotNull => plan.not_null = true,
                // NULL on the rowid-alias column means "assign a fresh
                // rowid", not a constraint violation, so its implicit
                // NOT NULL is deliberately not enforced.
                ColumnConstraint::PrimaryKey { .. } => {
                    if rowid_alias != Some(idx) {
                        plan.not_null = true;
                    }
                }
                ColumnConstraint::Default(
                    DefaultValue::Literal(expr) | DefaultValue::Paren(expr),
                ) => {
                    plan.default = Some(expr.clone());
                }
                ColumnConstraint::Check(expr) => plan.checks.push(expr.clone()),
                ColumnConstraint::Unique | ColumnConstraint::Collate(_) => {}
            }

match rowid_alias {
        Some(idx) => {
            let explicit = value_source_at(idx)
                .filter(|source| !matches!(source, ColumnSource::Expr(e) if is_null_literal(e)));
            match explicit {
                Some(source) => {
                    let r = compile_column_source(em, reg, schema, TABLE_CURSOR, &source)?;
                    let no_conflict = em.new_label();
                    let seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, TABLE_CURSOR, 0, r));
                    em.patch_p2(seek_addr, no_conflict);
                    emit_pk_conflict(em, reg, action, row_skip, schema, idx)?;
                    em.place(no_conflict);
                    r
                }
                None => {
                    let r = reg.alloc();
                    emit_new_rowid(em, r, schema, is_autoincrement);
                    r
                }
            }
        }
        None => {
            let r = reg.alloc();
            emit_new_rowid(em, r, schema, is_autoincrement);
            r
        }
    }

match explicit {
                Some(source) => {
                    let r = compile_column_source(em, reg, schema, TABLE_CURSOR, &source)?;
                    let no_conflict = em.new_label();
                    let seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, TABLE_CURSOR, 0, r));
                    em.patch_p2(seek_addr, no_conflict);
                    emit_pk_conflict(em, reg, action, row_skip, schema, idx)?;
                    em.place(no_conflict);
                    r
                }
                None => {
                    let r = reg.alloc();
                    emit_new_rowid(em, r, schema, is_autoincrement);
                    r
                }
            }

match &chosen {
            Some(source) => compile_column_source(em, reg, schema, TABLE_CURSOR, source)?,
            None => {
                let r = reg.alloc();
                em.emit(Instruction::new(Opcode::Null, 0, r, 0));
                r
            }
        }

match action {
        ConflictAction::Ignore => em.goto(row_skip),
        ConflictAction::Abort
        | ConflictAction::Fail
        | ConflictAction::Rollback
        | ConflictAction::Replace => {
            em.emit(Instruction::with_p4(
                Opcode::Halt,
                code,
                0,
                0,
                P4::Str(message),
            ));
        }
    }

match action {
        ConflictAction::Ignore => em.goto(row_skip),
        ConflictAction::Replace => {
            // `SeekRowid` above landed the cursor on the row this
            // INSERT is about to displace — its secondary-index
            // entries must be removed before it's deleted, exactly
            // like `delete.rs`'s ordinary `DELETE` path, or they go
            // stale (`#196` follow-up: this conflict path predates
            // index maintenance and wasn't updated when it landed).
            emit_index_key_ops(
                em,
                reg,
                schema,
                TABLE_CURSOR,
                FIRST_INDEX_CURSOR,
                Opcode::IdxDelete,
            )?;
            em.emit(Instruction::new(Opcode::Delete, TABLE_CURSOR, 0, 0));
        }
        ConflictAction::Abort | ConflictAction::Fail | ConflictAction::Rollback => {
            let message = format!(
                "UNIQUE constraint failed: {}.{} (PRIMARY KEY)",
                schema.name,
                schema.columns.get(idx).map_or("?", String::as_str)
            );
            em.emit(Instruction::with_p4(
                Opcode::Halt,
                SQLITE_CONSTRAINT_PRIMARYKEY,
                0,
                0,
                P4::Str(message),
            ));
        }
    }

match action {
        ConflictAction::Ignore => em.goto(row_skip),
        ConflictAction::Replace => {
            // The conflicting row's rowid was written into
            // `conflict_rowid_reg` by `NoConflict` itself — seek the
            // table cursor onto it, remove its index entries, then
            // delete it, exactly like `emit_pk_conflict`'s `Replace`
            // branch (which instead already had the cursor positioned
            // via `SeekRowid`).
            let seek_ok = em.new_label();
            let seek_addr = em.emit(Instruction::new(
                Opcode::SeekRowid,
                TABLE_CURSOR,
                0,
                conflict_rowid_reg,
            ));
            em.patch_p2(seek_addr, seek_ok);
            crate::codegen::row::index_maintenance::emit_index_key_ops(
                em,
                reg,
                schema,
                TABLE_CURSOR,
                FIRST_INDEX_CURSOR,
                Opcode::IdxDelete,
            )?;
            em.emit(Instruction::new(Opcode::Delete, TABLE_CURSOR, 0, 0));
            em.place(seek_ok);
        }
        ConflictAction::Abort | ConflictAction::Fail | ConflictAction::Rollback => {
            let message = format!("UNIQUE constraint failed: {}.{}", schema.name, index.name);
            em.emit(Instruction::with_p4(
                Opcode::Halt,
                SQLITE_CONSTRAINT_UNIQUE,
                0,
                0,
                P4::Str(message),
            ));
        }
    }

match begin.mode {
        None | Some(TransactionMode::Deferred) => TRANSACTION_MODE_DEFERRED,
        Some(TransactionMode::Immediate) => TRANSACTION_MODE_IMMEDIATE,
        Some(TransactionMode::Exclusive) => TRANSACTION_MODE_EXCLUSIVE,
    }

match parse_begin("BEGIN") {
            ParseOutcome::Accepted(b) => b,
            other => panic!("expected Accepted, got {other:?}"),
        }

match parse_begin("BEGIN IMMEDIATE") {
            ParseOutcome::Accepted(b) => b,
            other => panic!("expected Accepted, got {other:?}"),
        }

match parse_begin("BEGIN EXCLUSIVE") {
            ParseOutcome::Accepted(b) => b,
            other => panic!("expected Accepted, got {other:?}"),
        }

match parse_begin("BEGIN DEFERRED") {
            ParseOutcome::Accepted(b) => b,
            other => panic!("expected Accepted, got {other:?}"),
        }

match parse_commit("COMMIT") {
            ParseOutcome::Accepted(c) => c,
            other => panic!("expected Accepted, got {other:?}"),
        }

match parse_rollback("ROLLBACK") {
            ParseOutcome::Accepted(r) => r,
            other => panic!("expected Accepted, got {other:?}"),
        }

match self {
            DispatchError::NoSuchTable(name) => write!(f, "no such table: {name}"),
            DispatchError::NoSuchIndex(name) => write!(f, "no such index: {name}"),
            DispatchError::Unrecognized(kw) => {
                write!(f, "unsupported or unrecognized statement: {kw:?} ...")
            }
            DispatchError::NoFromClause => write!(f, "SELECT has no FROM clause"),
            DispatchError::Codegen(source) => write!(f, "{source}"),
            DispatchError::ParseFailed(msg) => write!(f, "{msg}"),
        }

match head {
        "BEGIN" => match parse_begin(sql) {
            ParseOutcome::Accepted(begin) => Ok(compile_begin(&begin)),
            other => Err(parse_error(other)),
        },
        "COMMIT" | "END" => match parse_commit(sql) {
            ParseOutcome::Accepted(commit) => Ok(compile_commit(&commit)),
            other => Err(parse_error(other)),
        },
        "ROLLBACK" => match parse_rollback(sql) {
            ParseOutcome::Accepted(rollback) => Ok(compile_rollback(&rollback)),
            other => Err(parse_error(other)),
        },
        "PRAGMA" => match parse_pragma(sql) {
            ParseOutcome::Accepted(pragma) => Ok(compile_pragma(&pragma)),
            other => Err(parse_error(other)),
        },
        "ANALYZE" => match parse_analyze(sql) {
            ParseOutcome::Accepted(analyze) => {
                let targets: Vec<&TableSchema> = match &analyze.target {
                    None => schemas.iter().collect(),
                    Some(name) => {
                        if let Some(schema) =
                            schemas.iter().find(|s| s.name.eq_ignore_ascii_case(name))
                        {
                            vec![schema]
                        } else if schemas
                            .iter()
                            .flat_map(|s| &s.indexes)
                            .any(|idx| idx.name.eq_ignore_ascii_case(name))
                        {
                            // Real SQLite also accepts `ANALYZE index-name`
                            // (analyzing just that index's owning table) —
                            // syntactically valid, but out of this MVP's
                            // scope (spec 011/Req 1), so `Unsupported`
                            // rather than the `NoSuchTable` a genuinely
                            // unknown name gets below.
                            return Err(CodegenError::Unsupported {
                                reason: format!(
                                    "ANALYZE of a single index ({name:?}) is not yet supported"
                                ),
                            }
                            .into());
                        } else {
                            return Err(DispatchError::NoSuchTable(name.clone()));
                        }
                    }
                };
                Ok(compile_analyze(&targets)?)
            }
            other => Err(parse_error(other)),
        },
        // db-core addition (#219): sqlite-rs dispatches SELECT from its
        // CLI binary (`src/bin/sqlite-rs/query.rs::compile_select_program`),
        // which db-core has no counterpart for -- so that function's pure
        // half lives here as [`compile_select_statement`] /
        // [`explain_select_statement`], and `compile_statement` covers the
        // whole statement vocabulary as a library entry point. `WITH` is a
        // `SELECT`'s CTE prefix (only `Select` carries a `with_clause`).
        "SELECT" | "WITH" => match parse_select(sql) {
            ParseOutcome::Accepted(select) => {
                compile_select_statement(&select, schemas, views, &HashMap::new())
            }
            other => Err(parse_error(other)),
        },
        "EXPLAIN" => match parse_explain(sql) {
            ParseOutcome::Accepted(explain) => {
                if !explain.query_plan {
                    return Err(CodegenError::Unsupported {
                        reason: "bare EXPLAIN (opcode listing) is not yet supported".to_string(),
                    }
                    .into());
                }
                let rows =
                    explain_select_statement(&explain.select, schemas, views, &HashMap::new())?;
                Ok(compile_eqp_program(&rows))
            }
            other => Err(parse_error(other)),
        },
        "INSERT" => match parse_insert(sql) {
            ParseOutcome::Accepted(mut insert) => {
                let schema = find_schema(&insert.table)?;
                let select_schemas: Option<Vec<TableSchema>> = match &insert.source {
                    InsertSource::Select(select) => {
                        // Same `WITH`/view expansion `compile_select_program`
                        // runs for a plain SELECT (#375/#380), so a CTE/view
                        // name in the source at least *resolves* against the
                        // catalog instead of failing with an unexplained "no
                        // such table". The INSERT codegen path below
                        // (`compile_insert`'s single-/joined-table scan)
                        // only knows how to scan a *real* table's root page,
                        // though — it doesn't yet drive `#257`'s FROM-
                        // subquery materialization the way a plain SELECT's
                        // codegen does — so a CTE/view expanding into a
                        // `TableRefKind::Subquery` here is rejected
                        // explicitly rather than falling through to
                        // `compile_insert` and failing with a confusing
                        // "invalid root page (0)" (the subquery's synthetic,
                        // rootpage-less schema).
                        let resolved_views = resolve_views(views);
                        let cte_expanded = expand_with_clause(select);
                        let expanded = cte_expanded.expand_views(&resolved_views)?;

                        let Some(from) = &expanded.from else {
                            return Err(DispatchError::NoFromClause);
                        };
                        let is_subquery = |r: &crate::parser::ast::TableRef| {
                            matches!(r.kind, TableRefKind::Subquery(_))
                        };
                        if is_subquery(&from.first)
