match escape {
                    Some(esc) => rewrite_expr(esc, alias, column_map, require_qualified),
                    None => true,
                }

match operand {
                Some(o) => rewrite_expr(o, alias, column_map, require_qualified),
                None => true,
            }

match else_ {
                Some(e) => rewrite_expr(e, alias, column_map, require_qualified),
                None => true,
            }

match c {
        ResultColumn::Star => false,
        ResultColumn::TableStar { table } => table.eq_ignore_ascii_case(alias),
        ResultColumn::Expr { expr, .. } => expr_references_alias(expr, alias),
    }

match &expr.kind {
        ExprKind::Literal(_) | ExprKind::Param(_) => false,
        ExprKind::Column { table, .. } => table
            .as_deref()
            .is_some_and(|t| t.eq_ignore_ascii_case(alias)),
        ExprKind::FunctionCall { args, .. } => match args {
            FunctionArgs::Star => false,
            FunctionArgs::List(list) => list.iter().any(|e| expr_references_alias(e, alias)),
        },
        ExprKind::Unary { expr: e, .. }
        | ExprKind::IsNull { expr: e, .. }
        | ExprKind::Cast { expr: e, .. }
        | ExprKind::Collate { expr: e, .. }
        | ExprKind::Paren(e) => expr_references_alias(e, alias),
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => {
            expr_references_alias(lhs, alias) || expr_references_alias(rhs, alias)
        }
        ExprKind::Between {
            expr: e, lo, hi, ..
        } => {
            expr_references_alias(e, alias)
                || expr_references_alias(lo, alias)
                || expr_references_alias(hi, alias)
        }
        ExprKind::In { expr: e, list, .. } => {
            expr_references_alias(e, alias) || list.iter().any(|i| expr_references_alias(i, alias))
        }
        ExprKind::Like {
            expr: e,
            pattern,
            escape,
            ..
        } => {
            expr_references_alias(e, alias)
                || expr_references_alias(pattern, alias)
                || escape
                    .as_deref()
                    .is_some_and(|esc| expr_references_alias(esc, alias))
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            operand
                .as_deref()
                .is_some_and(|o| expr_references_alias(o, alias))
                || whens.iter().any(|(w, t)| {
                    expr_references_alias(w, alias) || expr_references_alias(t, alias)
                })
                || else_
                    .as_deref()
                    .is_some_and(|e| expr_references_alias(e, alias))
        }
        ExprKind::Subquery(inner)
        | ExprKind::Exists {
            subquery: inner, ..
        } => select_references_alias(inner, alias),
        ExprKind::InSubquery {
            expr: e, subquery, ..
        } => expr_references_alias(e, alias) || select_references_alias(subquery, alias),
        ExprKind::InSubqueryMulti {
            exprs, subquery, ..
        } => {
            exprs.iter().any(|e| expr_references_alias(e, alias))
                || select_references_alias(subquery, alias)
        }
    }

match args {
            FunctionArgs::Star => false,
            FunctionArgs::List(list) => list.iter().any(|e| expr_references_alias(e, alias)),
        }

match &mut expr.kind {
        ExprKind::Column { table, .. } => {
            *table = alias.map(str::to_string);
        }
        ExprKind::Unary { expr: e, .. }
        | ExprKind::IsNull { expr: e, .. }
        | ExprKind::Cast { expr: e, .. }
        | ExprKind::Collate { expr: e, .. }
        | ExprKind::Paren(e) => qualify_with_outer_alias(e, alias),
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => {
            qualify_with_outer_alias(lhs, alias);
            qualify_with_outer_alias(rhs, alias);
        }
        ExprKind::Between {
            expr: e, lo, hi, ..
        } => {
            qualify_with_outer_alias(e, alias);
            qualify_with_outer_alias(lo, alias);
            qualify_with_outer_alias(hi, alias);
        }
        ExprKind::In { expr: e, list, .. } => {
            qualify_with_outer_alias(e, alias);
            for item in list {
                qualify_with_outer_alias(item, alias);
            }
        }
        ExprKind::Like {
            expr: e,
            pattern,
            escape,
            ..
        } => {
            qualify_with_outer_alias(e, alias);
            qualify_with_outer_alias(pattern, alias);
            if let Some(esc) = escape {
                qualify_with_outer_alias(esc, alias);
            }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            if let Some(o) = operand {
                qualify_with_outer_alias(o, alias);
            }
            for (w, t) in whens {
                qualify_with_outer_alias(w, alias);
                qualify_with_outer_alias(t, alias);
            }
            if let Some(e) = else_ {
                qualify_with_outer_alias(e, alias);
            }
        }
        ExprKind::FunctionCall { args, .. } => {
            if let FunctionArgs::List(list) = args {
                for e in list {
                    qualify_with_outer_alias(e, alias);
                }
            }
        }
        ExprKind::Literal(_)
        | ExprKind::Param(_)
        | ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => {}
    }

match existing {
        Some(e) => Expr {
            span: e.span,
            kind: ExprKind::Binary {
                op: BinaryOp::And,
                lhs: Box::new(e),
                rhs: Box::new(addition),
            },
        },
        None => addition,
    }

match parse_select(sql) {
            ParseOutcome::Accepted(select) => *select,
            other => panic!("expected Accepted, got {other:?}"),
        }

match &expr.kind {
        ExprKind::Column { table, name, .. } => {
            let qualifier_ok = match table {
                Some(t) => own_qualifiers.iter().any(|q| q.eq_ignore_ascii_case(t)),
                None => true,
            };
            let is_own = qualifier_ok
                && own_schema
                    .columns
                    .iter()
                    .any(|c| c.eq_ignore_ascii_case(name));
            if is_own {
                return;
            }
            if !outer_schema
                .columns
                .iter()
                .any(|c| c.eq_ignore_ascii_case(name))
            {
                *ambiguous = true;
                return;
            }
            match found {
                Some(existing) if existing.eq_ignore_ascii_case(name) => {}
                Some(_) => *ambiguous = true,
                None => *found = Some(name.clone()),
            }
        }
        ExprKind::Literal(_) | ExprKind::Param(_) => {}
        ExprKind::FunctionCall { args, .. } => {
            if let FunctionArgs::List(list) = args {
                for a in list {
                    collect_correlated_column(
                        a,
                        own_schema,
                        own_qualifiers,
                        outer_schema,
                        found,
                        ambiguous,
                    );
                }
            }
        }
        ExprKind::Unary { expr: e, .. }
        | ExprKind::IsNull { expr: e, .. }
        | ExprKind::Cast { expr: e, .. }
        | ExprKind::Collate { expr: e, .. }
        | ExprKind::Paren(e) => collect_correlated_column(
            e,
            own_schema,
            own_qualifiers,
            outer_schema,
            found,
            ambiguous,
        ),
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => {
            collect_correlated_column(
                lhs,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
            collect_correlated_column(
                rhs,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
        }
        ExprKind::Between {
            expr: e, lo, hi, ..
        } => {
            collect_correlated_column(
                e,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
            collect_correlated_column(
                lo,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
            collect_correlated_column(
                hi,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
        }
        ExprKind::In { expr: e, list, .. } => {
            collect_correlated_column(
                e,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
            for item in list {
                collect_correlated_column(
                    item,
                    own_schema,
                    own_qualifiers,
                    outer_schema,
                    found,
                    ambiguous,
                );
            }
        }
        ExprKind::Like {
            expr: e,
            pattern,
            escape,
            ..
        } => {
            collect_correlated_column(
                e,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
            collect_correlated_column(
                pattern,
                own_schema,
                own_qualifiers,
                outer_schema,
                found,
                ambiguous,
            );
            if let Some(esc) = escape {
                collect_correlated_column(
                    esc,
                    own_schema,
                    own_qualifiers,
                    outer_schema,
                    found,
                    ambiguous,
                );
            }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            if let Some(o) = operand {
                collect_correlated_column(
                    o,
                    own_schema,
                    own_qualifiers,
                    outer_schema,
                    found,
                    ambiguous,
                );
            }
            for (w, t) in whens {
                collect_correlated_column(
                    w,
                    own_schema,
                    own_qualifiers,
                    outer_schema,
                    found,
                    ambiguous,
                );
                collect_correlated_column(
                    t,
                    own_schema,
                    own_qualifiers,
                    outer_schema,
                    found,
                    ambiguous,
                );
            }
            if let Some(e) = else_ {
                collect_correlated_column(
                    e,
                    own_schema,
                    own_qualifiers,
                    outer_schema,
                    found,
                    ambiguous,
                );
            }
        }
        ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => {
            *ambiguous = true;
        }
    }

match table {
                Some(t) => own_qualifiers.iter().any(|q| q.eq_ignore_ascii_case(t)),
                None => true,
            }

match found {
                Some(existing) if existing.eq_ignore_ascii_case(name) => {}
                Some(_) => *ambiguous = true,
                None => *found = Some(name.clone()),
            }

match col {
            ResultColumn::Star => {
                for schema in schemas {
                    out.extend(schema.columns.iter().cloned());
                }
            }
            ResultColumn::TableStar { table } => {
                if let Some(schema) = table_refs
                    .iter()
                    .position(|t| t.alias.as_deref().or(t.name()).unwrap_or("") == table)
                    .and_then(|idx| schemas.get(idx))
                {
                    out.extend(schema.columns.iter().cloned());
                }
            }
            ResultColumn::Expr { expr, alias } => {
                let name = alias.clone().unwrap_or_else(|| match &expr.kind {
                    ExprKind::Column { name, .. } => name.clone(),
                    _ => format!("column{}", i.saturating_add(1)),
                });
                out.push(name);
            }
        }

match &expr.kind {
                    ExprKind::Column { name, .. } => name.clone(),
                    _ => format!("column{}", i.saturating_add(1)),
                }

match &table_ref.kind {
        crate::parser::ast::TableRefKind::Name(name) => catalog
            .iter()
            .find(|s| s.name.eq_ignore_ascii_case(name))
            .cloned()
            .ok_or_else(|| CodegenError::Unsupported {
                reason: format!("no such table: {name}"),
            }),
        crate::parser::ast::TableRefKind::Subquery(subquery) => {
            let table_refs = subquery_own_table_refs(subquery)?;
            let schemas = resolve_subquery_schemas(&table_refs, catalog)?;
            let mut schema = subquery_result_schema(subquery, &table_refs, &schemas);
            schema.name = table_ref.alias.clone().unwrap_or_default();
            Ok(schema)
        }
    }

match &from.first.kind {
            TableRefKind::Name(_) => {
                let root_page = valid_table_root_page(schema)?;
                em.emit(Instruction::new(
                    Opcode::OpenRead,
                    cursors.table,
                    root_page,
                    0,
                ));
            }
            TableRefKind::Subquery(inner) => {
                // A subquery-in-FROM nested inside this one (#376: a CTE
                // whose own body's FROM names another CTE) — materialize
                // it into the same cursor this level would otherwise
                // `OpenRead` a real table into.
                materialize_from_subquery(em, reg, inner, catalog, cursors.table)?;
            }
        }

match parse_select(sql) {
            ParseOutcome::Accepted(select) => *select,
            other => panic!("expected Accepted, got {other:?}"),
        }

match &select.columns[0] {
            ResultColumn::Expr { expr, .. } => match &expr.kind {
                ExprKind::Subquery(sub) => (**sub).clone(),
                _ => panic!("expected subquery expr"),
            },
            _ => panic!("expected Expr result column"),
        }

match &mut expr.kind {
        ExprKind::Literal(_) | ExprKind::Param(_) => true,
        ExprKind::Column {
            table,
            catalog,
            name,
        } => {
            if catalog.is_some() {
                return false;
            }
            let qualifies = match table {
                Some(t) => t.eq_ignore_ascii_case(alias),
                None => !require_qualified,
            };
            if !qualifies {
                return false;
            }
            match column_map {
                ColumnMap::Wildcard => {
                    *table = None;
                    true
                }
                ColumnMap::Explicit(cols) => {
                    let Some((_, underlying)) =
                        cols.iter().find(|(n, _)| n.eq_ignore_ascii_case(name))
                    else {
                        return false;
                    };
                    *expr = underlying.clone();
                    true
                }
            }
        }
        ExprKind::FunctionCall { args, .. } => match args {
            FunctionArgs::Star => true,
            FunctionArgs::List(list) => list
                .iter_mut()
                .all(|e| rewrite_for_pushdown(e, alias, column_map, require_qualified)),
        },
        ExprKind::Unary { expr: inner, .. } => {
            rewrite_for_pushdown(inner, alias, column_map, require_qualified)
        }
        ExprKind::Binary { lhs, rhs, .. } => {
            rewrite_for_pushdown(lhs, alias, column_map, require_qualified)
                && rewrite_for_pushdown(rhs, alias, column_map, require_qualified)
        }
        ExprKind::Is { lhs, rhs, .. } => {
            rewrite_for_pushdown(lhs, alias, column_map, require_qualified)
                && rewrite_for_pushdown(rhs, alias, column_map, require_qualified)
        }
        ExprKind::IsNull { expr: inner, .. } => {
            rewrite_for_pushdown(inner, alias, column_map, require_qualified)
        }
        ExprKind::Between {
            expr: e, lo, hi, ..
        } => {
            rewrite_for_pushdown(e, alias, column_map, require_qualified)
                && rewrite_for_pushdown(lo, alias, column_map, require_qualified)
                && rewrite_for_pushdown(hi, alias, column_map, require_qualified)
        }
        ExprKind::In { expr: e, list, .. } => {
            rewrite_for_pushdown(e, alias, column_map, require_qualified)
                && list
                    .iter_mut()
                    .all(|item| rewrite_for_pushdown(item, alias, column_map, require_qualified))
        }
        ExprKind::Like {
            expr: e,
            pattern,
            escape,
            ..
        } => {
            rewrite_for_pushdown(e, alias, column_map, require_qualified)
                && rewrite_for_pushdown(pattern, alias, column_map, require_qualified)
                && match escape {
                    Some(esc) => rewrite_for_pushdown(esc, alias, column_map, require_qualified),
                    None => true,
                }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            let operand_ok = match operand {
                Some(o) => rewrite_for_pushdown(o, alias, column_map, require_qualified),
                None => true,
            };
            let whens_ok = whens.iter_mut().all(|(w, t)| {
                rewrite_for_pushdown(w, alias, column_map, require_qualified)
                    && rewrite_for_pushdown(t, alias, column_map, require_qualified)
            });
            let else_ok = match else_ {
                Some(e) => rewrite_for_pushdown(e, alias, column_map, require_qualified),
                None => true,
            };
            operand_ok && whens_ok && else_ok
        }
        ExprKind::Cast { expr: e, .. } => {
            rewrite_for_pushdown(e, alias, column_map, require_qualified)
        }
        ExprKind::Collate { expr: e, .. } => {
            rewrite_for_pushdown(e, alias, column_map, require_qualified)
        }
        ExprKind::Paren(inner) => rewrite_for_pushdown(inner, alias, column_map, require_qualified),
        ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => false,
    }

match column_map {
                ColumnMap::Wildcard => {
                    *table = None;
                    true
                }
                ColumnMap::Explicit(cols) => {
                    let Some((_, underlying)) =
                        cols.iter().find(|(n, _)| n.eq_ignore_ascii_case(name))
                    else {
                        return false;
                    };
                    *expr = underlying.clone();
                    true
                }
            }

match args {
            FunctionArgs::Star => true,
            FunctionArgs::List(list) => list
                .iter_mut()
                .all(|e| rewrite_for_pushdown(e, alias, column_map, require_qualified)),
        }

match escape {
                    Some(esc) => rewrite_for_pushdown(esc, alias, column_map, require_qualified),
                    None => true,
                }

match operand {
                Some(o) => rewrite_for_pushdown(o, alias, column_map, require_qualified),
                None => true,
            }

match else_ {
                Some(e) => rewrite_for_pushdown(e, alias, column_map, require_qualified),
                None => true,
            }

match existing {
        Some(e) => Expr {
            span: e.span,
            kind: ExprKind::Binary {
                op: BinaryOp::And,
                lhs: Box::new(e),
                rhs: Box::new(addition),
            },
        },
        None => addition,
    }

match parse_select(sql) {
            ParseOutcome::Accepted(select) => *select,
            other => panic!("expected Accepted, got {other:?}"),
        }

match &mut table_ref.kind {
        TableRefKind::Name(name) => {
            let Some(cte) = ctes.iter().find(|c| c.name.eq_ignore_ascii_case(name)) else {
                return;
            };
            // A subquery-in-FROM's alias is mandatory to the rest of
            // codegen (`resolve_from_table_schema`'s doc comment) —
            // default it to the CTE's own name when the reference
            // didn't supply one itself (the common `FROM cte_name`
            // case, as opposed to `FROM cte_name AS c`).
            let alias = table_ref.alias.clone().or_else(|| Some(cte.name.clone()));
            table_ref.kind = TableRefKind::Subquery(cte.query.clone());
            table_ref.alias = alias;
        }
        // An inline derived table (`FROM (SELECT ... FROM cte_name) sub`)
        // can itself reference an earlier-declared CTE in its own FROM —
        // recurse into it the same way view expansion does, so a CTE
        // isn't only resolvable directly under a query's top-level FROM.
        TableRefKind::Subquery(inner) => substitute_cte_refs(inner, ctes),
    }

match crate::parser::row::parse_create_view(&v.sql) {
            ParseOutcome::Accepted(create) => Some(ResolvedView {
                name: create.name,
                columns: create.columns,
                query: create.query,
            }),
            _ => None,
        }

match &table_ref.kind {
        TableRefKind::Name(name) => views.iter().any(|v| v.name.eq_ignore_ascii_case(name)),
        TableRefKind::Subquery(inner) => select_references_any_view(inner, views),
    }

match &mut table_ref.kind {
        TableRefKind::Name(name) => {
            let Some(view) = views.iter().find(|v| v.name.eq_ignore_ascii_case(name)) else {
                return Ok(());
            };
            if stack
                .iter()
                .any(|seen| seen.eq_ignore_ascii_case(&view.name))
            {
                return Err(CodegenError::CircularView {
                    name: view.name.clone(),
                });
            }
            // A view's own stored body may carry its own `WITH` clause
            // (`CREATE VIEW v AS WITH cte AS (...) SELECT * FROM cte`) —
            // that never runs through `expand_with_clause` otherwise,
            // since only the outermost query gets that pass at the top
            // of `compile_select_program`. Expanding it here, before
            // recursing for nested views, mirrors the ordering already
            // used at the top level (CTEs first, then views).
            let mut query = expand_with_clause(&view.query).into_owned();
            if let Some(columns) = &view.columns {
                apply_column_aliases(&mut query, columns);
            }
            stack.push(view.name.clone());
            let result = expand_views_in_select(&mut query, views, stack);
            stack.pop();
            result?;
            // Same alias-defaulting rule as CTE substitution (#376): a
            // bare `FROM view_name` (no explicit alias) needs the
            // subquery's alias set to the view's own name, since a
            // `TableRefKind::Subquery`'s alias is mandatory to the rest
            // of codegen (`resolve_from_table_schema`'s doc comment).
            let alias = table_ref.alias.clone().or_else(|| Some(view.name.clone()));
            table_ref.kind = TableRefKind::Subquery(Box::new(query));
            table_ref.alias = alias;
            Ok(())
        }
        TableRefKind::Subquery(inner) => expand_views_in_select(inner, views, stack),
    }

match col {
            ResultColumn::Expr { expr, .. } => {
                walk_expr_for_correlation(expr, schema, &own_qualifiers, &mut correlated);
            }
            // `*`/`table.*` project only the subquery's own columns —
            // never a reference to the enclosing scope.
            ResultColumn::Star | ResultColumn::TableStar { .. } => {}
        }

match &expr.kind {
        ExprKind::Column { table, name, .. } => {
            let qualifier_ok = match table {
                Some(t) => own_qualifiers.iter().any(|q| q.eq_ignore_ascii_case(t)),
                None => true,
            };
            if !qualifier_ok || !schema.columns.iter().any(|c| c.eq_ignore_ascii_case(name)) {
                *correlated = true;
            }
        }
        ExprKind::Literal(_) | ExprKind::Param(_) => {}
        ExprKind::FunctionCall { args, .. } => {
            if let FunctionArgs::List(list) = args {
                for a in list {
                    walk_expr_for_correlation(a, schema, own_qualifiers, correlated);
                }
            }
        }
        ExprKind::Unary { expr: e, .. }
        | ExprKind::IsNull { expr: e, .. }
        | ExprKind::Cast { expr: e, .. }
        | ExprKind::Collate { expr: e, .. }
        | ExprKind::Paren(e) => walk_expr_for_correlation(e, schema, own_qualifiers, correlated),
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => {
            walk_expr_for_correlation(lhs, schema, own_qualifiers, correlated);
            walk_expr_for_correlation(rhs, schema, own_qualifiers, correlated);
        }
        ExprKind::Between {
            expr: e, lo, hi, ..
        } => {
            walk_expr_for_correlation(e, schema, own_qualifiers, correlated);
            walk_expr_for_correlation(lo, schema, own_qualifiers, correlated);
            walk_expr_for_correlation(hi, schema, own_qualifiers, correlated);
        }
        ExprKind::In { expr: e, list, .. } => {
            walk_expr_for_correlation(e, schema, own_qualifiers, correlated);
            for item in list {
                walk_expr_for_correlation(item, schema, own_qualifiers, correlated);
            }
        }
        ExprKind::Like {
            expr: e,
            pattern,
            escape,
            ..
        } => {
            walk_expr_for_correlation(e, schema, own_qualifiers, correlated);
            walk_expr_for_correlation(pattern, schema, own_qualifiers, correlated);
            if let Some(esc) = escape {
                walk_expr_for_correlation(esc, schema, own_qualifiers, correlated);
            }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            if let Some(o) = operand {
                walk_expr_for_correlation(o, schema, own_qualifiers, correlated);
            }
            for (w, t) in whens {
                walk_expr_for_correlation(w, schema, own_qualifiers, correlated);
                walk_expr_for_correlation(t, schema, own_qualifiers, correlated);
            }
            if let Some(e) = else_ {
                walk_expr_for_correlation(e, schema, own_qualifiers, correlated);
            }
        }
        // Nested subquery-bearing expressions: conservatively correlated
        // rather than reasoning through another scope level (out of
        // scope for #306's hoist pass).
        ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => {
            *correlated = true;
        }
    }

match table {
                Some(t) => own_qualifiers.iter().any(|q| q.eq_ignore_ascii_case(t)),
                None => true,
