match &expr.kind {
        ExprKind::Paren(inner) => compile_value(em, reg, scope, inner),
        ExprKind::Collate { expr: inner, .. } => compile_value(em, reg, scope, inner),

        ExprKind::Literal(lit) => {
            let r = reg.alloc();
            match lit {
                Literal::Integer(i) => {
                    // #142: `Opcode::Integer`'s P1 is i32-only, so a
                    // literal outside that range (but within i64) loads
                    // via `Int64`'s P4-carried i64 immediate instead —
                    // the harvested 64-bit counterpart, not a codegen
                    // error.
                    match i32::try_from(*i) {
                        Ok(p1) => {
                            em.emit(Instruction::new(Opcode::Integer, p1, r, 0));
                        }
                        Err(_) => {
                            em.emit(Instruction::with_p4(Opcode::Int64, 0, r, 0, P4::Int(*i)));
                        }
                    }
                }
                Literal::True => {
                    em.emit(Instruction::new(Opcode::Integer, 1, r, 0));
                }
                Literal::False => {
                    em.emit(Instruction::new(Opcode::Integer, 0, r, 0));
                }
                Literal::Str(s) => {
                    em.emit(Instruction::with_p4(
                        Opcode::String8,
                        0,
                        r,
                        0,
                        P4::Str(s.clone()),
                    ));
                }
                // #142: a real literal loads as an actual `Value::Real`
                // via the harvested `Real` opcode, not `String8` text
                // relying on coercion at comparison/arithmetic time
                // (the #138 bug this used to cause).
                Literal::Float(f) => {
                    em.emit(Instruction::with_p4(Opcode::Real, 0, r, 0, P4::Real(*f)));
                }
                // #142: a blob literal loads as an actual `Value::Blob`
                // via the harvested `Blob` opcode — hex-text never
                // actually coerced back to a blob (BLOB affinity never
                // converts text to blob, matching SQLite), so
                // `WHERE b = x'41'` always failed under the old scheme.
                Literal::Blob(bytes) => {
                    let len =
                        i32::try_from(bytes.len()).map_err(|_| CodegenError::Unsupported {
                            reason: format!(
                                "blob literal of {} bytes does not fit in a P1 operand",
                                bytes.len()
                            ),
                        })?;
                    em.emit(Instruction::with_p4(
                        Opcode::Blob,
                        len,
                        r,
                        0,
                        P4::Blob(bytes.clone()),
                    ));
                }
                Literal::Null => {} // Fresh registers already read as NULL.
            }
            Ok(r)
        }

        // `?` and `?NNN` compile to `Variable`, reading whatever the
        // caller bound via `Vm::bind_params`/`execute_with_params`
        // (#137). Named forms (`:name`/`@name`/`$name`) aren't wired to
        // an index yet — out of #137's bounded scope — so they still
        // compile to an always-NULL register (known simplification,
        // same as before).
        ExprKind::Param(kind) => {
            let r = reg.alloc();
            let index = match kind {
                ParamKind::Anonymous => Some(reg.anonymous_param()),
                ParamKind::Numbered(n) => Some(reg.numbered_param(*n)),
                ParamKind::Colon(_) | ParamKind::At(_) | ParamKind::Dollar(_) => None,
            };
            if let Some(index) = index {
                let p1 = i32::try_from(index).map_err(|_| CodegenError::Unsupported {
                    reason: format!("parameter index {index} is out of range"),
                })?;
                em.emit(Instruction::new(Opcode::Variable, p1, r, 0));
            }
            Ok(r)
        }

        ExprKind::Column { table, name, .. } => {
            let (cursor, idx, schema, forced_null) = scope.resolve(table.as_deref(), name)?;
            let r = reg.alloc();
            if forced_null {
                // #237's LEFT JOIN null-extension: this binding has no
                // matching row (or `cursor` may not even be positioned
                // on live data at all), so every column reads as NULL
                // rather than going through a real `Column`/`Rowid`
                // read.
                em.emit(Instruction::new(Opcode::Null, 0, r, 0));
            } else {
                emit_column_read(em, schema, cursor, idx, r)?;
            }
            Ok(r)
        }

        ExprKind::FunctionCall {
            name, args, tail, ..
        } => {
            // The parser (db-core's `parser::row`, #17) accepts inline
            // `OVER (...)` and `FILTER (WHERE ...)` (db-core#67); the
            // planner has no window pass yet (V9) and no FILTER support,
            // and compiling the call as a plain scalar/aggregate would
            // return wrong rows silently — refuse instead.
            if let Some(tail) = tail.as_deref() {
                let reason = if tail.over.is_some() {
                    "window functions (OVER) not yet supported"
                } else {
                    "FILTER (WHERE ...) on a function call not yet supported"
                };
                return Err(CodegenError::Unsupported {
                    reason: reason.to_string(),
                });
            }
            // Aggregates need a grouping/accumulator pass this V2
            // compiler doesn't have. Rejecting them is not just a
            // missing-feature guard: compiling one as an ordinary
            // scalar `Function` call emits it *per row*, so
            // `SELECT count(*) FROM t` silently returns one row per
            // input row instead of a single count — wrong output is
            // worse than a refusal.
            if is_aggregate_call(name, args) {
                return Err(CodegenError::Unsupported {
                    reason: format!("aggregate function {}", name.to_ascii_lowercase()),
                });
            }
            let arg_exprs = match args {
                crate::parser::ast::FunctionArgs::Star => &[][..],
                crate::parser::ast::FunctionArgs::List(list) => list.as_slice(),
            };
            // `Function` reads its arguments from a contiguous register
            // window starting at P2, so the args must land next to each
            // other. Reserving the window up front and *then* compiling
            // into it does not work: `compile_value` allocates its own
            // destination, so every argument landed past the reservation.
            // Instead, compile the args first and take the window from
            // where they actually landed — consecutive simple args are
            // naturally adjacent this way. When that does not hold (an
            // argument whose own lowering allocates its destination
            // before its operands, e.g. `coalesce(i, -1)` alongside
            // another such call), fall back to copying each arg into a
            // freshly reserved contiguous run (#141).
            let mut arg_regs = Vec::with_capacity(arg_exprs.len());
            for arg in arg_exprs.iter() {
                arg_regs.push(compile_value(em, reg, scope, arg)?);
            }
            let mut first = match arg_regs.first().copied() {
                Some(r) => r,
                // Zero-arg call (or `f(*)`): P2 still has to point at a
                // register, and nothing reads it.
                None => reg.alloc(),
            };
            let already_contiguous = arg_regs
                .iter()
                .enumerate()
                .all(|(i, &r)| r == first.saturating_add(i32::try_from(i).unwrap_or(i32::MAX)));
            if !already_contiguous {
                let dests: Vec<i32> = (0..arg_regs.len()).map(|_| reg.alloc()).collect();
                if let Some(&dest_first) = dests.first() {
                    first = dest_first;
                }
                for (&r, &dest) in arg_regs.iter().zip(&dests) {
                    em.emit(Instruction::new(Opcode::Copy, r, dest, 0));
                }
            }
            let dest = reg.alloc();
            em.emit(Instruction::with_p4(
                Opcode::Function,
                0,
                first,
                dest,
                P4::Str(format!(
                    "{}({})",
                    name.to_ascii_lowercase(),
                    arg_exprs.len()
                )),
            ));
            Ok(dest)
        }

        ExprKind::Like {
            expr: inner,
            pattern,
            glob,
            negated,
            escape,
        } => {
            let (name, arity) = match escape {
                Some(_) if !*glob => ("like", 3),
                _ if *glob => ("glob", 2),
                _ => ("like", 2),
            };
            // Registry argument order is (pattern, text[, escape]) —
            // the reverse of SQL's `text LIKE pattern` syntax. Compile
            // operands in that order so the bump allocator hands out a
            // contiguous run matching `Function`'s expected layout.
            let pat_r = compile_value(em, reg, scope, pattern)?;
            let txt_r = compile_value(em, reg, scope, inner)?;
            if txt_r != pat_r.saturating_add(1) {
                return Err(CodegenError::Unsupported {
                    reason: "LIKE/GLOB text operand did not land in the register contiguous \
                             with its pattern operand"
                        .to_string(),
                });
            }
            if let Some(e) = escape {
                let esc_r = compile_value(em, reg, scope, e)?;
                if esc_r != pat_r.saturating_add(2) {
                    return Err(CodegenError::Unsupported {
                        reason: "LIKE ESCAPE operand did not land in the register contiguous \
                                 with its pattern/text operands"
                            .to_string(),
                    });
                }
            }
            let dest = reg.alloc();
            let p4 = P4::Str(format!("{name}({arity})"));
            em.emit(Instruction::with_p4(Opcode::Function, 0, pat_r, dest, p4));
            if *negated {
                let out = compile_negate_value(em, reg, dest);
                return Ok(out);
            }
            Ok(dest)
        }

        ExprKind::Unary { op, expr: inner } => match op {
            UnaryOp::Plus => compile_value(em, reg, scope, inner),
            UnaryOp::Minus => {
                let r = compile_value(em, reg, scope, inner)?;
                let zero = reg.alloc();
                em.emit(Instruction::new(Opcode::Integer, 0, zero, 0));
                let dest = reg.alloc();
                // Subtract: r[P3] = r[P2] - r[P1] -> 0 - r = -r via
                // P1=r, P2=zero.
                em.emit(Instruction::new(Opcode::Subtract, r, zero, dest));
                Ok(dest)
            }
            // `Not` is the whole reason this is not routed through
            // `compile_bool_to_value`: it is the oracle's own lowering
            // for `SELECT NOT x` (one instruction, verified against the
            // pinned 3.53.4 `EXPLAIN`), and it propagates NULL in a
            // register, which jump-mode code cannot do at all.
            UnaryOp::Not => {
                let r = compile_value(em, reg, scope, inner)?;
                let dest = reg.alloc();
                em.emit(Instruction::new(Opcode::Not, r, dest, 0));
                Ok(dest)
            }
            UnaryOp::BitNot => {
                let r = compile_value(em, reg, scope, inner)?;
                let dest = reg.alloc();
                em.emit(Instruction::new(Opcode::BitNot, r, dest, 0));
                Ok(dest)
            }
        },

        ExprKind::Binary { op, lhs, rhs }
            if matches!(
                op,
                BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Mod
            ) =>
        {
            let l = compile_value(em, reg, scope, lhs)?;
            let r = compile_value(em, reg, scope, rhs)?;
            let dest = reg.alloc();
            // The caller's own `matches!` filter guarantees `op` is one
            // of these five; any other value is a codegen-internal
            // error, not a reachable SQL-input case.
            let opcode = match op {
                BinaryOp::Add => Opcode::Add,
                BinaryOp::Sub => Opcode::Subtract,
                BinaryOp::Mul => Opcode::Multiply,
                BinaryOp::Div => Opcode::Divide,
                BinaryOp::Mod => Opcode::Remainder,
                _ => {
                    return Err(CodegenError::Unsupported {
                        reason: "arithmetic lowering reached with a non-arithmetic operator"
                            .to_string(),
                    })
                }
            };
            // Subtract/Divide/Remainder read as `r[P2] <op> r[P1]`
            // (SQLite's own operand order, per arithmetic.rs) — pass
            // (rhs=P1, lhs=P2) so `lhs <op> rhs` is what's computed.
            match opcode {
                Opcode::Subtract | Opcode::Divide | Opcode::Remainder => {
                    em.emit(Instruction::new(opcode, r, l, dest));
                }
                _ => {
                    em.emit(Instruction::new(opcode, l, r, dest));
                }
            }
            Ok(dest)
        }

        ExprKind::Binary { op, lhs, rhs }
            if matches!(
                op,
                BinaryOp::BitAnd
                    | BinaryOp::BitOr
                    | BinaryOp::Shl
                    | BinaryOp::Shr
                    | BinaryOp::Concat
            ) =>
        {
            let l = compile_value(em, reg, scope, lhs)?;
            let r = compile_value(em, reg, scope, rhs)?;
            let dest = reg.alloc();
            let opcode = match op {
                BinaryOp::BitAnd => Opcode::BitAnd,
                BinaryOp::BitOr => Opcode::BitOr,
                BinaryOp::Shl => Opcode::ShiftLeft,
                BinaryOp::Shr => Opcode::ShiftRight,
                BinaryOp::Concat => Opcode::Concat,
                _ => {
                    return Err(CodegenError::Unsupported {
                        reason: "bitwise/concat lowering reached with a non-bitwise operator"
                            .to_string(),
                    })
                }
            };
            // ShiftLeft/ShiftRight/Concat read as `r[P2] <op> r[P1]`
            // (SQLite's own operand order, verified against harvested
            // EXPLAIN) — pass (rhs=P1, lhs=P2) so `lhs <op> rhs` is what's
            // computed. BitAnd/BitOr are commutative, so operand order
            // doesn't change the result.
            match opcode {
                Opcode::ShiftLeft | Opcode::ShiftRight | Opcode::Concat => {
                    em.emit(Instruction::new(opcode, r, l, dest));
                }
                _ => {
                    em.emit(Instruction::new(opcode, l, r, dest));
                }
            }
            Ok(dest)
        }

        // Comparisons and the logical connectives are conditions used
        // in a value context: they answer true/false/unknown, which
        // `compile_bool_to_value` materializes three-valued. Before
        // #134 they fell into the catch-all below and compiled to a
        // bare NULL register, so `SELECT price = 10` answered NULL for
        // every row, NULL operand or not.
        ExprKind::Binary {
            op:
                BinaryOp::Eq
                | BinaryOp::Ne
                | BinaryOp::Lt
                | BinaryOp::Le
                | BinaryOp::Gt
                | BinaryOp::Ge
                | BinaryOp::And
                | BinaryOp::Or,
            ..
        } => compile_bool_to_value(em, reg, scope, expr),

        // Unreachable in practice: `BinaryOp` has no variant left
        // uncovered by the two arms above (#139). Kept as a defensive
        // fallback rather than a `_ => unreachable!()` so a future
        // `BinaryOp` addition fails soft (wrong answer) instead of
        // panicking mid-query.
        ExprKind::Binary { .. } => {
            let r = reg.alloc();
            em.emit(Instruction::new(Opcode::Null, 0, r, 0));
            Ok(r)
        }

        // #142: `CAST` forces its target affinity via the harvested
        // `Cast` opcode (P2 = the affinity's ASCII byte, matching the
        // oracle's own `EXPLAIN` shape: `Cast r[N], affinity(r[N])`),
        // never `MustBeInt`/`RealAffinity` — those are a guard opcode
        // (aborts instead of truncating, wrong for `CAST('apple' AS
        // INTEGER)` = `0`) and a column-load coercion opcode
        // respectively, neither of which implements `CAST`'s own lossy
        // conversion rule (`src/vdbe/cast.rs`).
        ExprKind::Cast {
            expr: inner,
            type_name,
        } => {
            let r = compile_value(em, reg, scope, inner)?;
            let affinity = affinity_of(type_name);
            let p2 = i32::from(affinity.to_p4_byte());
            em.emit(Instruction::new(Opcode::Cast, r, p2, 0));
            Ok(r)
        }

        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            let dest = reg.alloc();
            let end_label = em.new_label();
            for (when_expr, then_expr) in whens {
                let next_label = em.new_label();
                let cond = match operand {
                    Some(op_expr) => Expr {
                        kind: ExprKind::Binary {
                            op: BinaryOp::Eq,
                            lhs: op_expr.clone(),
                            rhs: Box::new(when_expr.clone()),
                        },
                        span: when_expr.span,
                    },
                    None => when_expr.clone(),
                };
                // A `WHEN` whose condition is unknown is not a match,
                // exactly like a false one — `NullTarget::False`, the
                // same setting `WHERE` uses.
                compile_cond(
                    em,
                    reg,
                    scope,
                    &cond,
                    CondTargets::null_is_false(Target::Fallthrough, Target::Jump(next_label)),
                )?;
                emit_branch_into(em, reg, scope, then_expr, dest)?;
                em.goto(end_label);
                em.place(next_label);
            }
            // `dest` is a register slot the scan loop reuses every
            // iteration — a prior row's CASE result would otherwise
            // leak into this row's output when no WHEN matches and
            // there's no ELSE (registers don't reset between loop
            // iterations), so the no-match path always explicitly
            // (re)writes NULL rather than relying on "never written".
            match else_ {
                Some(else_expr) => emit_branch_into(em, reg, scope, else_expr, dest)?,
                None => {
                    // This used to fake a NULL with an out-of-range
                    // `Column` read; `Null` (#134) says what it means,
                    // and is what the oracle emits here.
                    em.emit(Instruction::new(Opcode::Null, 0, dest, 0));
                }
            }
            em.place(end_label);
            Ok(dest)
        }

        // Boolean-valued expressions used in a value context (e.g. `a
        // = b` as a result column) materialize 0/1 via the jump-mode
        // compiler, matching Requirement 11's shape even when the
        // condition's answer must land in a register.
        ExprKind::Is { .. }
        | ExprKind::IsNull { .. }
        | ExprKind::Between { .. }
        | ExprKind::In { .. }
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => compile_bool_to_value(em, reg, scope, expr),

        // #238: a scalar subquery in value position — `SELECT (SELECT
        // max(x) FROM t)`, `x = (SELECT ...)`, etc. #306: if this
        // subquery was hoisted (materialized once, before the enclosing
        // scan's `Rewind`, because it's uncorrelated), its result is
        // already sitting in a register — reuse it instead of
        // re-running the subquery's whole scan on every outer row.
        ExprKind::Subquery(subquery) => {
            let key = crate::codegen::row::subquery::select_id(subquery);
            match scope.hoisted.get(&key) {
                Some(crate::codegen::row::subquery::HoistedSubquery::Scalar { reg: r }) => Ok(*r),
                _ => match scope.memoized.get(&key) {
                    // #314: correlated, but memoized per distinct value
                    // of the one outer column it's correlated against.
                    Some(memo) => crate::codegen::row::subquery::compile_memoized_scalar_subquery(
                        em, reg, scope, subquery, memo,
                    ),
                    None => crate::codegen::row::subquery::compile_scalar_subquery(
                        em, reg, scope, subquery,
                    ),
                },
            }
        }
    }

match lit {
                Literal::Integer(i) => {
                    // #142: `Opcode::Integer`'s P1 is i32-only, so a
                    // literal outside that range (but within i64) loads
                    // via `Int64`'s P4-carried i64 immediate instead —
                    // the harvested 64-bit counterpart, not a codegen
                    // error.
                    match i32::try_from(*i) {
                        Ok(p1) => {
                            em.emit(Instruction::new(Opcode::Integer, p1, r, 0));
                        }
                        Err(_) => {
                            em.emit(Instruction::with_p4(Opcode::Int64, 0, r, 0, P4::Int(*i)));
                        }
                    }
                }
                Literal::True => {
                    em.emit(Instruction::new(Opcode::Integer, 1, r, 0));
                }
                Literal::False => {
                    em.emit(Instruction::new(Opcode::Integer, 0, r, 0));
                }
                Literal::Str(s) => {
                    em.emit(Instruction::with_p4(
                        Opcode::String8,
                        0,
                        r,
                        0,
                        P4::Str(s.clone()),
                    ));
                }
                // #142: a real literal loads as an actual `Value::Real`
                // via the harvested `Real` opcode, not `String8` text
                // relying on coercion at comparison/arithmetic time
                // (the #138 bug this used to cause).
                Literal::Float(f) => {
                    em.emit(Instruction::with_p4(Opcode::Real, 0, r, 0, P4::Real(*f)));
                }
                // #142: a blob literal loads as an actual `Value::Blob`
                // via the harvested `Blob` opcode — hex-text never
                // actually coerced back to a blob (BLOB affinity never
                // converts text to blob, matching SQLite), so
                // `WHERE b = x'41'` always failed under the old scheme.
                Literal::Blob(bytes) => {
                    let len =
                        i32::try_from(bytes.len()).map_err(|_| CodegenError::Unsupported {
                            reason: format!(
                                "blob literal of {} bytes does not fit in a P1 operand",
                                bytes.len()
                            ),
                        })?;
                    em.emit(Instruction::with_p4(
                        Opcode::Blob,
                        len,
                        r,
                        0,
                        P4::Blob(bytes.clone()),
                    ));
                }
                Literal::Null => {} // Fresh registers already read as NULL.
            }

match i32::try_from(*i) {
                        Ok(p1) => {
                            em.emit(Instruction::new(Opcode::Integer, p1, r, 0));
                        }
                        Err(_) => {
                            em.emit(Instruction::with_p4(Opcode::Int64, 0, r, 0, P4::Int(*i)));
                        }
                    }

match kind {
                ParamKind::Anonymous => Some(reg.anonymous_param()),
                ParamKind::Numbered(n) => Some(reg.numbered_param(*n)),
                ParamKind::Colon(_) | ParamKind::At(_) | ParamKind::Dollar(_) => None,
            }

match arg_regs.first().copied() {
                Some(r) => r,
                // Zero-arg call (or `f(*)`): P2 still has to point at a
                // register, and nothing reads it.
                None => reg.alloc(),
            }

match op {
            UnaryOp::Plus => compile_value(em, reg, scope, inner),
            UnaryOp::Minus => {
                let r = compile_value(em, reg, scope, inner)?;
                let zero = reg.alloc();
                em.emit(Instruction::new(Opcode::Integer, 0, zero, 0));
                let dest = reg.alloc();
                // Subtract: r[P3] = r[P2] - r[P1] -> 0 - r = -r via
                // P1=r, P2=zero.
                em.emit(Instruction::new(Opcode::Subtract, r, zero, dest));
                Ok(dest)
            }
            // `Not` is the whole reason this is not routed through
            // `compile_bool_to_value`: it is the oracle's own lowering
            // for `SELECT NOT x` (one instruction, verified against the
            // pinned 3.53.4 `EXPLAIN`), and it propagates NULL in a
            // register, which jump-mode code cannot do at all.
            UnaryOp::Not => {
                let r = compile_value(em, reg, scope, inner)?;
                let dest = reg.alloc();
                em.emit(Instruction::new(Opcode::Not, r, dest, 0));
                Ok(dest)
            }
            UnaryOp::BitNot => {
                let r = compile_value(em, reg, scope, inner)?;
                let dest = reg.alloc();
                em.emit(Instruction::new(Opcode::BitNot, r, dest, 0));
                Ok(dest)
            }
        }

match op {
                BinaryOp::Add => Opcode::Add,
                BinaryOp::Sub => Opcode::Subtract,
                BinaryOp::Mul => Opcode::Multiply,
                BinaryOp::Div => Opcode::Divide,
                BinaryOp::Mod => Opcode::Remainder,
                _ => {
                    return Err(CodegenError::Unsupported {
                        reason: "arithmetic lowering reached with a non-arithmetic operator"
                            .to_string(),
                    })
                }
            }

match opcode {
                Opcode::Subtract | Opcode::Divide | Opcode::Remainder => {
                    em.emit(Instruction::new(opcode, r, l, dest));
                }
                _ => {
                    em.emit(Instruction::new(opcode, l, r, dest));
                }
            }

match op {
                BinaryOp::BitAnd => Opcode::BitAnd,
                BinaryOp::BitOr => Opcode::BitOr,
                BinaryOp::Shl => Opcode::ShiftLeft,
                BinaryOp::Shr => Opcode::ShiftRight,
                BinaryOp::Concat => Opcode::Concat,
                _ => {
                    return Err(CodegenError::Unsupported {
                        reason: "bitwise/concat lowering reached with a non-bitwise operator"
                            .to_string(),
                    })
                }
            }

match opcode {
                Opcode::ShiftLeft | Opcode::ShiftRight | Opcode::Concat => {
                    em.emit(Instruction::new(opcode, r, l, dest));
                }
                _ => {
                    em.emit(Instruction::new(opcode, l, r, dest));
                }
            }

match operand {
                    Some(op_expr) => Expr {
                        kind: ExprKind::Binary {
                            op: BinaryOp::Eq,
                            lhs: op_expr.clone(),
                            rhs: Box::new(when_expr.clone()),
                        },
                        span: when_expr.span,
                    },
                    None => when_expr.clone(),
                }

match else_ {
                Some(else_expr) => emit_branch_into(em, reg, scope, else_expr, dest)?,
                None => {
                    // This used to fake a NULL with an out-of-range
                    // `Column` read; `Null` (#134) says what it means,
                    // and is what the oracle emits here.
                    em.emit(Instruction::new(Opcode::Null, 0, dest, 0));
                }
            }

match scope.hoisted.get(&key) {
                Some(crate::codegen::row::subquery::HoistedSubquery::Scalar { reg: r }) => Ok(*r),
                _ => match scope.memoized.get(&key) {
                    // #314: correlated, but memoized per distinct value
                    // of the one outer column it's correlated against.
                    Some(memo) => crate::codegen::row::subquery::compile_memoized_scalar_subquery(
                        em, reg, scope, subquery, memo,
                    ),
                    None => crate::codegen::row::subquery::compile_scalar_subquery(
                        em, reg, scope, subquery,
                    ),
                },
            }

match scope.memoized.get(&key) {
                    // #314: correlated, but memoized per distinct value
                    // of the one outer column it's correlated against.
                    Some(memo) => crate::codegen::row::subquery::compile_memoized_scalar_subquery(
                        em, reg, scope, subquery, memo,
                    ),
                    None => crate::codegen::row::subquery::compile_scalar_subquery(
                        em, reg, scope, subquery,
                    ),
                }

match &expr.kind {
        ExprKind::Literal(Literal::Integer(i)) => match i32::try_from(*i) {
            Ok(p1) => {
                em.emit(Instruction::new(Opcode::Integer, p1, dest, 0));
            }
            Err(_) => {
                em.emit(Instruction::with_p4(Opcode::Int64, 0, dest, 0, P4::Int(*i)));
            }
        },
        ExprKind::Literal(Literal::True) => {
            em.emit(Instruction::new(Opcode::Integer, 1, dest, 0));
        }
        ExprKind::Literal(Literal::False) => {
            em.emit(Instruction::new(Opcode::Integer, 0, dest, 0));
        }
        ExprKind::Literal(Literal::Str(s)) => {
            em.emit(Instruction::with_p4(
                Opcode::String8,
                0,
                dest,
                0,
                P4::Str(s.clone()),
            ));
        }
        ExprKind::Literal(Literal::Float(f)) => {
            em.emit(Instruction::with_p4(Opcode::Real, 0, dest, 0, P4::Real(*f)));
        }
        ExprKind::Literal(Literal::Blob(bytes)) => {
            let len = i32::try_from(bytes.len()).map_err(|_| CodegenError::Unsupported {
                reason: format!(
                    "blob literal of {} bytes does not fit in a P1 operand",
                    bytes.len()
                ),
            })?;
            em.emit(Instruction::with_p4(
                Opcode::Blob,
                len,
                dest,
                0,
                P4::Blob(bytes.clone()),
            ));
        }
        // `dest` is shared across branches and reused every scan
        // iteration, so an explicit NULL branch has to overwrite it.
        // Emitting nothing (the pre-#134 behavior, correct only for a
        // never-written fresh register) leaked the previous row's
        // result out of `SELECT CASE WHEN c THEN x ELSE NULL END`.
        ExprKind::Literal(Literal::Null) => {
            em.emit(Instruction::new(Opcode::Null, 0, dest, 0));
        }
        ExprKind::Column { table, name, .. } => {
            let (cursor, idx, schema, forced_null) = scope.resolve(table.as_deref(), name)?;
            if forced_null {
                em.emit(Instruction::new(Opcode::Null, 0, dest, 0));
            } else {
                emit_column_read(em, schema, cursor, idx, dest)?;
            }
        }
        _ => {
            let r = compile_value(em, reg, scope, expr)?;
            em.emit(Instruction::new(Opcode::Copy, r, dest, 0));
        }
    }

match i32::try_from(*i) {
            Ok(p1) => {
                em.emit(Instruction::new(Opcode::Integer, p1, dest, 0));
            }
            Err(_) => {
                em.emit(Instruction::with_p4(Opcode::Int64, 0, dest, 0, P4::Int(*i)));
            }
        }

match &expr.kind {
        ExprKind::Paren(inner) => is_definite(inner),
        // #238: EXISTS is always definitely true or false (see
        // `subquery::compile_exists`'s doc comment) — unlike
        // `InSubquery`, whose NULL-LHS case really is unknown.
        ExprKind::Is { .. } | ExprKind::IsNull { .. } | ExprKind::Exists { .. } => true,
        _ => false,
    }

match &expr.kind {
        ExprKind::Paren(inner) => cost_class(inner),
        ExprKind::Literal(_) | ExprKind::Param(_) | ExprKind::Column { .. } => 0,
        ExprKind::Unary { expr: inner, .. } => cost_class(inner).max(1),
        ExprKind::Binary { op, lhs, rhs } => {
            let base = match op {
                BinaryOp::And | BinaryOp::Or => 0,
                _ => 1,
            };
            cost_class(lhs).max(cost_class(rhs)).max(base)
        }
        ExprKind::FunctionCall { .. } => 2,
        ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => 3,
        _ => 1,
    }

match &expr.kind {
        ExprKind::Paren(inner) => compile_cond(em, reg, scope, inner, targets),

        // Swapping the targets is right — it is what SQLite's own
        // `sqlite3ExprIfTrue`/`sqlite3ExprIfFalse` pair does for
        // `TK_NOT` — but only once `on_null` comes along for the
        // ride. Flipping it keeps the unknown outcome on the same
        // address across the swap; without that (the #134 bug) NULL
        // silently inherited whichever target had just become "false",
        // i.e. the keep-the-row one, and `WHERE NOT (x = 5)` returned
        // rows where `x IS NULL`.
        ExprKind::Unary {
            op: UnaryOp::Not,
            expr: inner,
        } => compile_cond(em, reg, scope, inner, targets.negate()),

        ExprKind::Binary {
            op: BinaryOp::And,
            lhs,
            rhs,
        } => {
            // `on_false` must be a real label before `lhs` compiles
            // — if it were left as `Fallthrough`, "fall through" would
            // wrongly mean "continue into rhs's test code" (the next
            // thing physically emitted) rather than the AND's actual
            // false continuation, which only exists after `rhs` compiles.
            //
            // `on_null` passes to both operands unchanged, and that
            // is exactly three-valued AND, both ways round. With
            // `NullTarget::False`: an unknown `lhs` goes straight to
            // the false continuation, which is right because every
            // completion of `unknown AND rhs` (false, or unknown) lands
            // there too. With `NullTarget::True`: an unknown `lhs`
            // falls through into `rhs`'s test, which is also right —
            // `unknown AND false` is false and reaches `false_label`
            // via `rhs`, while `unknown AND true`/`unknown AND unknown`
            // are unknown and reach `on_true`, where NULL belongs
            // under this setting.
            //
            // #581: AND is commutative under three-valued logic, so
            // whichever operand is cheaper (by [`cost_class`]) compiles
            // first — the eagerly-evaluated slot — letting the pricier
            // operand's evaluation be skipped whenever the cheap one
            // already resolves the jump.
            let (first, second) = if rhs_is_cheaper(lhs, rhs) {
                (rhs, lhs)
            } else {
                (lhs, rhs)
            };
            let (false_label, is_new) = ensure_label(em, targets.on_false);
            let operand = targets.with_false(Target::Jump(false_label));
            compile_cond(
                em,
                reg,
                scope,
                first,
                operand.with_true(Target::Fallthrough),
            )?;
            compile_cond(em, reg, scope, second, operand)?;
            if is_new {
                em.place(false_label);
            }
            Ok(())
        }

        ExprKind::Binary {
            op: BinaryOp::Or,
            lhs,
            rhs,
        } => {
            // Symmetric to `And` above: `on_true` must be a real
            // label before `lhs` compiles, or a `Fallthrough` true
            // would wrongly land in `rhs`'s test code instead of OR's
            // actual true continuation. `on_null` threads through
            // unchanged for the mirror-image reason: under
            // `NullTarget::True` an unknown `lhs` jumps straight to
            // `true_label` (every completion of `unknown OR rhs` is
            // true or unknown, and both belong there), and under
            // `NullTarget::False` it falls into `rhs`, which decides
            // between true and the false/unknown continuation.
            //
            // #581: same cheapest-first reordering as AND above — OR
            // is equally commutative under three-valued logic.
            let (first, second) = if rhs_is_cheaper(lhs, rhs) {
                (rhs, lhs)
            } else {
                (lhs, rhs)
            };
            let (true_label, is_new) = ensure_label(em, targets.on_true);
            let operand = targets.with_true(Target::Jump(true_label));
            compile_cond(
                em,
                reg,
                scope,
                first,
                operand.with_false(Target::Fallthrough),
            )?;
            compile_cond(em, reg, scope, second, operand)?;
            if is_new {
                em.place(true_label);
            }
            Ok(())
        }

        ExprKind::Binary { op, lhs, rhs }
            if matches!(
                op,
                BinaryOp::Eq
                    | BinaryOp::Ne
                    | BinaryOp::Lt
                    | BinaryOp::Le
                    | BinaryOp::Gt
                    | BinaryOp::Ge
            ) =>
        {
            let collation = collation_of(lhs)
                .or_else(|| collation_of(rhs))
                .or_else(|| expr_collation(scope, lhs))
                .or_else(|| expr_collation(scope, rhs));
            let affinity =
                comparison_affinity(expr_affinity(scope, lhs), expr_affinity(scope, rhs));
            let l = compile_value(em, reg, scope, lhs)?;
            let r = compile_value(em, reg, scope, rhs)?;
            emit_compare_false_jump(em, *op, l, r, collation, affinity, targets)
        }

        ExprKind::Is { lhs, rhs, negated } => {
            // `a IS b`: true when both NULL, or both non-NULL and
            // equal — unlike `=`, never propagates NULL to "unknown".
            // No single opcode expresses this; compute it into a
            // 0/1 register first, then test truthiness like any other
            // value-mode boolean (LIKE/GLOB take the same shape).
            // `on_null` is deliberately ignored here and in the
            // `IsNull` arm below: these two are the only conditions in
            // SQL that are always definitely true or definitely false,
            // so they have no unknown outcome to route, and swapping
            // the targets for `negated` is sound without flipping it.
            let (t, f) = if *negated {
                (targets.on_false, targets.on_true)
            } else {
                (targets.on_true, targets.on_false)
            };
            let l = compile_value(em, reg, scope, lhs)?;
            let r = compile_value(em, reg, scope, rhs)?;
            let result = reg.alloc();
            let both_null = em.new_label();
            let done = em.new_label();
            let addr = em.emit(Instruction::new(Opcode::IsNull, l, 0, 0));
            em.patch_p2(addr, both_null);

            let eq_true = em.new_label();
            let addr = em.emit(Instruction::new(Opcode::Eq, l, 0, r));
            em.patch_p2(addr, eq_true);
            em.emit(Instruction::new(Opcode::Integer, 0, result, 0));
            em.goto(done);
            em.place(eq_true);
            em.emit(Instruction::new(Opcode::Integer, 1, result, 0));
            em.goto(done);

            em.place(both_null);
            let r_null = em.new_label();
            let addr = em.emit(Instruction::new(Opcode::IsNull, r, 0, 0));
            em.patch_p2(addr, r_null);
            em.emit(Instruction::new(Opcode::Integer, 0, result, 0));
            em.goto(done);
            em.place(r_null);
            em.emit(Instruction::new(Opcode::Integer, 1, result, 0));

            em.place(done);
            finish_bool(em, t, f, |em, false_label| {
                let addr = em.emit(Instruction::new(Opcode::IfNot, result, 0, 1));
                em.patch_p2(addr, false_label);
            });
            Ok(())
        }

        ExprKind::IsNull {
            expr: inner,
            negated,
        } => {
            let r = compile_value(em, reg, scope, inner)?;
            // negated=false is `IS NULL` (condition true when NULL);
            // negated=true is `IS NOT NULL` (condition true when not
            // NULL). Emit the opcode matching "jump when condition is
            // false" so `finish_bool` sees a uniform false-jump
            // primitive.
            // negated=false (IS NULL): condition true iff NULL, so its
            // false-jump primitive fires when NOT null -> `NotNull`.
            // negated=true (IS NOT NULL): condition true iff not NULL,
            // so its false-jump primitive fires when NULL -> `IsNull`.
            let false_jump_op = if *negated {
                Opcode::IsNull
            } else {
                Opcode::NotNull
            };
            finish_bool(em, targets.on_true, targets.on_false, |em, false_label| {
                let addr = em.emit(Instruction::new(false_jump_op, r, 0, 0));
                em.patch_p2(addr, false_label);
            });
            Ok(())
        }

        ExprKind::Between {
            expr: inner,
            lo,
            hi,
            negated,
        } => {
            // Lowered per SQLite's own rule: `x BETWEEN lo AND hi` is
            // `x >= lo AND x <= hi`, and `x NOT BETWEEN lo AND hi` is
            // `x < lo OR x > hi` — NOT the same shape with true/false
            // swapped. Swapping targets would make a NULL `x` (where
            // neither comparison jumps at all, per
            // `emit_compare_false_jump`'s three-valued contract) come
            // out *true* for `NOT BETWEEN`, when the honest answer is
            // "unknown", which WHERE excludes just like false.
            let cmp = |op, rhs: &Expr| Expr {
                kind: ExprKind::Binary {
                    op,
                    lhs: inner.clone(),
                    rhs: Box::new(rhs.clone()),
                },
                span: expr.span,
            };

            if *negated {
                let lt_lo = cmp(BinaryOp::Lt, lo);
                let gt_hi = cmp(BinaryOp::Gt, hi);
                let (t_label, t_is_new) = ensure_label(em, targets.on_true);
                let arm = targets.with_true(Target::Jump(t_label));
                compile_cond(em, reg, scope, &lt_lo, arm.with_false(Target::Fallthrough))?;
                compile_cond(em, reg, scope, &gt_hi, arm)?;
                if t_is_new {
                    em.place(t_label);
                }
            } else {
                let ge_lo = cmp(BinaryOp::Ge, lo);
                let le_hi = cmp(BinaryOp::Le, hi);
                let (f_label, f_is_new) = ensure_label(em, targets.on_false);
                let arm = targets.with_false(Target::Jump(f_label));
                compile_cond(em, reg, scope, &ge_lo, arm.with_true(Target::Fallthrough))?;
                compile_cond(em, reg, scope, &le_hi, arm)?;
                if f_is_new {
                    em.place(f_label);
                }
            }
            Ok(())
        }

        ExprKind::In {
            expr: inner,
            list,
            negated,
        } => {
            if list.is_empty() {
                // `x IN ()` is always false, even for a NULL `x` — an
                // empty list leaves nothing to be uncertain against.
                let (t, f) = if *negated {
                    (targets.on_false, targets.on_true)
                } else {
                    (targets.on_true, targets.on_false)
                };
                return compile_always_false(em, t, f);
            }

            // `IN`'s three outcomes — a definite match, a definite
            // non-match, or "unknown" (no match found, but `inner` or
            // some list item was NULL along the way) — don't collapse
            // to a single true/false jump the way other comparisons
            // do: `NOT IN`'s definite-non-match and unknown outcomes
            // diverge (`NOT FALSE` = true, `NOT NULL` = still NULL),
            // so a per-item comparison can't just swap targets like
            // `emit_compare_false_jump` does. `saw_null` is a small
            // exception to this module's "never an intermediate
            // boolean register" rule (shared with the `Is`/`IsNot`
            // handling above), needed to remember that exception past
            // the loop that discovers it.
            let l = compile_value(em, reg, scope, inner)?;
            let saw_null = reg.alloc();
            em.emit(Instruction::new(Opcode::Integer, 0, saw_null, 0));

            let (true_label, true_is_new) = ensure_label(em, targets.on_true);
            let (false_label, false_is_new) = ensure_label(em, targets.on_false);
            // A match found means IN is true; exhausting the list
            // without one means IN is false — `negated` (`NOT IN`)
            // swaps which final label each of those routes to. An
            // unknown outcome, below, always routes to `false_label`
            // regardless of `negated`: NULL is never true.
            let (found_label, unmatched_label) = if *negated {
                (false_label, true_label)
            } else {
                (true_label, false_label)
            };
            // `negated` does not move the unknown outcome — `NOT
            // unknown` is still unknown — so it routes by `on_null`
            // alone, exactly like every other arm (#134). Before that
            // ticket this was hardcoded to `false_label`, which was
            // right only because `WHERE` was the sole caller.
            let null_label = match targets.on_null {
                NullTarget::True => true_label,
                NullTarget::False => false_label,
            };

            let inner_null_addr = em.emit(Instruction::new(Opcode::IsNull, l, 0, 0));
            em.patch_p2(inner_null_addr, null_label);

            for item in list.iter() {
                let collation = collation_of(inner)
                    .or_else(|| collation_of(item))
                    .or_else(|| expr_collation(scope, inner))
                    .or_else(|| expr_collation(scope, item));
                let affinity =
                    comparison_affinity(expr_affinity(scope, inner), expr_affinity(scope, item));
                let p4 = p4_coll_seq(collation.unwrap_or(Collation::Binary), affinity);
                let r = compile_value(em, reg, scope, item)?;

                let item_null_label = em.new_label();
                let skip_label = em.new_label();
                let addr = em.emit(Instruction::new(Opcode::IsNull, r, 0, 0));
                em.patch_p2(addr, item_null_label);
                let addr = em.emit(Instruction::with_p4(Opcode::Eq, l, 0, r, p4));
                em.patch_p2(addr, found_label);
                em.goto(skip_label);

                em.place(item_null_label);
                em.emit(Instruction::new(Opcode::Integer, 1, saw_null, 0));
                em.place(skip_label);
            }

            // Exhausted the list without a match: route to
            // `unmatched_label` only if every comparison was a clean
            // non-match (`saw_null` still 0); otherwise at least one
            // comparison was against NULL, so the honest answer is
            // "unknown", which goes wherever `on_null` says.
            let addr = em.emit(Instruction::new(Opcode::IfNot, saw_null, 0, 0));
            em.patch_p2(addr, unmatched_label);
            em.goto(null_label);

            if false_is_new {
                em.place(false_label);
            }
            if true_is_new {
                em.place(true_label);
            }
            Ok(())
        }

        ExprKind::Like { .. } => {
            let r = compile_value(em, reg, scope, expr)?;
            finish_truthy(em, r, targets);
            Ok(())
        }

        // #238: EXISTS/NOT EXISTS never has an unknown outcome (see
        // `subquery::compile_exists`'s doc comment), so `targets` is
        // handed through as-is rather than materialized via
        // `compile_bool_to_value`.
        ExprKind::Exists { subquery, negated } => crate::codegen::row::subquery::compile_exists(
            em, reg, scope, subquery, *negated, targets,
        ),

        ExprKind::InSubquery {
            expr: inner,
            subquery,
            negated,
        } => crate::codegen::row::subquery::compile_in_subquery(
            em, reg, scope, inner, subquery, *negated, targets,
        ),

        ExprKind::InSubqueryMulti {
            exprs,
            subquery,
            negated,
        } => crate::codegen::row::subquery::compile_in_subquery_multi(
            em, reg, scope, exprs, subquery, *negated, targets,
        ),

        // A scalar subquery used directly as a boolean condition (e.g.
        // `WHERE (SELECT x FROM t)`): compute its value, then test
        // truthiness like any other value-mode boolean.
        ExprKind::Subquery(_) => {
            let r = compile_value(em, reg, scope, expr)?;
            finish_truthy(em, r, targets);
            Ok(())
        }

        // Any other expression used in boolean context (a bare column,
        // a function call, CASE, etc.): evaluate to a value and test
        // truthiness the same way as LIKE above.
        _ => {
            let r = compile_value(em, reg, scope, expr)?;
            finish_truthy(em, r, targets);
            Ok(())
        }
    }

match targets.on_null {
                NullTarget::True => true_label,
                NullTarget::False => false_label,
            }

match targets.on_null {
        NullTarget::False => {
            finish_bool(em, targets.on_true, targets.on_false, |em, false_label| {
                let addr = em.emit(Instruction::new(Opcode::IfNot, r, 0, 1));
                em.patch_p2(addr, false_label);
            });
        }
        NullTarget::True => {
            let (t_label, t_is_new) = ensure_label(em, targets.on_true);
            let addr = em.emit(Instruction::new(Opcode::IsNull, r, 0, 0));
            em.patch_p2(addr, t_label);
            // NULL is already gone, so `IfNot`'s P3 stays 0 and the
            // remaining test is the plain two-valued one.
            finish_bool(
                em,
                Target::Jump(t_label),
                targets.on_false,
                |em, false_label| {
                    let addr = em.emit(Instruction::new(Opcode::IfNot, r, 0, 0));
                    em.patch_p2(addr, false_label);
                },
            );
            if t_is_new {
                em.place(t_label);
            }
        }
    }

match (true_target, false_target) {
        (Target::Fallthrough, Target::Jump(f)) => emit_false_jump(em, f),
        (Target::Jump(t), Target::Fallthrough) => {
            let synth = em.new_label();
            emit_false_jump(em, synth);
            em.goto(t);
            em.place(synth);
        }
        (Target::Jump(t), Target::Jump(f)) => {
            emit_false_jump(em, f);
            em.goto(t);
        }
        (Target::Fallthrough, Target::Fallthrough) => {
            // Both branches continue at the same point — the condition
            // was evaluated only for a side effect (never emitted by
            // this module), so give false-jump a label that resolves to
            // "here" too.
            let synth = em.new_label();
            emit_false_jump(em, synth);
            em.place(synth);
        }
    }

match target {
        Target::Jump(l) => (l, false),
        Target::Fallthrough => (em.new_label(), true),
    }

match idx {
                None => table_rows = parts.next().and_then(|s| s.parse().ok()),
                Some(name) => {
                    let rows = parts.next().and_then(|s| s.parse().ok());
                    let avg_eq = parts.next().and_then(|s| s.parse().ok());
                    if let (Some(rows), Some(avg_eq)) = (rows, avg_eq) {
                        index_stats.insert(name, (rows, avg_eq));
                    }
                }
            }

match stats.table_rows() {
        Some(rows) => PlanCost {
            estimated_rows: rows,
            estimated_io: rows,
        },
        None => PlanCost::UNKNOWN,
    }

match stats.index_stats(index_name) {
        Some((_rows, avg_eq)) => {
            let estimated_rows = avg_eq.max(1);
            PlanCost {
                estimated_rows,
                estimated_io: estimated_rows,
            }
        }
        None => PlanCost::UNKNOWN,
    }

match &program.instructions[1].p4 {
            P4::Analyze { targets } => {
                assert_eq!(targets.len(), 1);
                assert_eq!(targets[0].table_name, "t");
                assert_eq!(targets[0].table_root_page, 2);
            }
            other => panic!("expected P4::Analyze, got {other:?}"),
        }

match &program.instructions[1].p4 {
            P4::Analyze { targets } => {
                assert_eq!(targets[0].indexes.len(), 1);
                assert_eq!(targets[0].indexes[0].index_name, "idx_a");
                assert_eq!(targets[0].indexes[0].root_page, 3);
            }
            other => panic!("expected P4::Analyze, got {other:?}"),
        }

match self {
            Self::NoFromClause => {
                write!(
                    f,
                    "SELECT has no FROM clause — not supported by this V2-scope compiler"
                )
            }
            Self::UnknownColumn { name } => write!(f, "unknown column {name:?}"),
            Self::AmbiguousColumn { name } => write!(f, "ambiguous column name: {name:?}"),
            Self::Unsupported { reason } => write!(f, "unsupported: {reason}"),
            Self::RowShapeMismatch {
                table,
                expected,
                found,
            } => {
                write!(
                    f,
                    "{table} has {expected} columns but {found} values were supplied"
                )
            }
            Self::CompoundColumnMismatch { expected, found } => write!(
                f,
                "SELECTs to the left and right of UNION ALL do not have the same number of \
                 result columns: expected {expected}, found {found}"
            ),
            Self::CircularView { name } => write!(f, "view {name} is circularly defined"),
        }

match compile(sql, schemas) {
        Ok(p) => p,
        Err(e) => panic!("{sql}: expected Ok, got {e:?}"),
    }

match compile(sql, schemas) {
        Ok(p) => panic!("{sql}: expected Err, got program {p:?}"),
        Err(e) => format!("{e:?}"),
    }

match parse_select(sql) {
        ParseOutcome::Accepted(s) => *s,
        other => panic!("expected {sql:?} to parse as a SELECT, got {other:?}"),
    }

match parse_update(sql) {
        ParseOutcome::Accepted(u) => *u,
        other => panic!("expected {sql:?} to parse as an UPDATE, got {other:?}"),
    }

match parse_select(sql) {
        ParseOutcome::Accepted(select) => *select,
        other => panic!("{sql:?} must parse, got {other:?}"),
    }

match &select.from.as_ref().unwrap().first.kind {
        TableRefKind::Subquery(inner) => inner.where_clause.is_some(),
        TableRefKind::Name(_) => panic!("pushdown must not flatten"),
    }

match select.expand_views(&resolved) {
        Ok(Cow::Owned(expanded)) => assert!(matches!(
            expanded.from.as_ref().unwrap().first.kind,
            TableRefKind::Subquery(_)
        )),
        other => panic!("expected an owned expansion, got {other:?}"),
    }

match parse_insert(sql) {
        ParseOutcome::Accepted(insert) => *insert,
        other => panic!("{sql:?} must parse, got {other:?}"),
    }

match parse_update(sql) {
        ParseOutcome::Accepted(update) => *update,
        other => panic!("{sql:?} must parse, got {other:?}"),
    }

match &expr.kind {
        ExprKind::Literal(_) | ExprKind::Param(_) => {}
        ExprKind::Column { table, name, .. } => {
            for (i, binding) in bindings.iter().enumerate() {
                let matches = match table {
                    Some(t) => binding.matches_qualifier(t),
                    None => column_index(&binding.schema, name).is_some(),
                };
                if matches {
                    acc.push(i);
                }
            }
        }
        ExprKind::FunctionCall { args, .. } => {
            if let FunctionArgs::List(list) = args {
                for e in list {
                    collect_referenced_binding_indices(e, bindings, acc);
                }
            }
        }
        ExprKind::Unary { expr, .. }
        | ExprKind::IsNull { expr, .. }
        | ExprKind::Cast { expr, .. }
        | ExprKind::Collate { expr, .. }
        | ExprKind::Paren(expr) => collect_referenced_binding_indices(expr, bindings, acc),
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => {
            collect_referenced_binding_indices(lhs, bindings, acc);
            collect_referenced_binding_indices(rhs, bindings, acc);
        }
        ExprKind::Between { expr, lo, hi, .. } => {
            collect_referenced_binding_indices(expr, bindings, acc);
            collect_referenced_binding_indices(lo, bindings, acc);
            collect_referenced_binding_indices(hi, bindings, acc);
        }
        ExprKind::In { expr, list, .. } => {
            collect_referenced_binding_indices(expr, bindings, acc);
            for e in list {
                collect_referenced_binding_indices(e, bindings, acc);
            }
        }
        ExprKind::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            collect_referenced_binding_indices(expr, bindings, acc);
            collect_referenced_binding_indices(pattern, bindings, acc);
            if let Some(escape) = escape {
                collect_referenced_binding_indices(escape, bindings, acc);
            }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            if let Some(operand) = operand {
                collect_referenced_binding_indices(operand, bindings, acc);
            }
            for (when, then) in whens {
                collect_referenced_binding_indices(when, bindings, acc);
                collect_referenced_binding_indices(then, bindings, acc);
            }
            if let Some(else_) = else_ {
                collect_referenced_binding_indices(else_, bindings, acc);
            }
        }
        // Scalar subquery / EXISTS / IN (SELECT ...): conservatively
        // treat as referencing every table rather than walk into a
        // nested `Select` (which may itself be correlated against any
        // binding in scope).
        ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => {
            acc.extend(0..bindings.len());
        }
    }

match table {
                    Some(t) => binding.matches_qualifier(t),
                    None => column_index(&binding.schema, name).is_some(),
                }

match table_refs.get(orig).map(|t| &t.kind) {
            Some(TableRefKind::Subquery(subquery)) => {
                crate::codegen::row::subquery::materialize_from_subquery(
                    em,
                    reg,
                    subquery,
                    full_catalog,
                    cursor,
                )?;
            }
            _ => {
                let Some(binding) = bindings.get(orig) else {
                    return Err(CodegenError::Unsupported {
                        reason: "join table binding out of range".to_string(),
                    });
                };
                let root_page = valid_table_root_page(&binding.schema)?;
                em.emit(Instruction::new(Opcode::OpenRead, cursor, root_page, 0));
            }
        }

match acc {
            Some(prev) => Expr {
                kind: ExprKind::Binary {
                    op: BinaryOp::And,
                    lhs: Box::new(prev),
                    rhs: Box::new(eq),
                },
                span: SYNTHETIC_SPAN,
            },
            None => eq,
        }

match order_cursors {
        Some((_, order_pseudo_cursor)) => order_pseudo_cursor.saturating_add(1),
        None => flush_cursor.saturating_add(1),
    }

match &agg.arg {
        Some(expr) => {
            let offset = joined_bare_column_offset(full_scope, expr)?;
            let r = reg.alloc();
            em.emit(Instruction::new(
                Opcode::Column,
                pseudo_cursor,
                i32::try_from(offset).unwrap_or(0),
                r,
            ));
            (
                Some(r),
                1usize,
                collation_of(expr)
                    .or_else(|| expr_collation(full_scope, expr))
                    .unwrap_or(Collation::Binary),
            )
        }
        None => (None, 0usize, Collation::Binary),
    }

match col {
            ResultColumn::Star => {
                for (i, binding) in full_scope.tables.iter().enumerate() {
                    let suppressed = dedup_star.get(i);
                    let base = joined_column_offset(full_scope, i);
                    for idx in 0..binding.schema.columns.len() {
                        let Some(name) = binding.schema.columns.get(idx) else {
                            continue;
                        };
                        if suppressed.is_some_and(|s| s.contains(&name.to_ascii_lowercase())) {
                            continue;
                        }
                        regs.push(read_offset(em, reg, base.saturating_add(idx)));
                    }
                }
            }
            ResultColumn::TableStar { table } => {
                let i = full_scope
                    .tables
                    .iter()
                    .position(|b| b.matches_qualifier(table))
                    .ok_or_else(|| CodegenError::UnknownColumn {
                        name: format!("{table}.*"),
                    })?;
                let base = joined_column_offset(full_scope, i);
                let count = full_scope
                    .tables
                    .get(i)
                    .map(|b| b.schema.columns.len())
                    .unwrap_or(0);
                for idx in 0..count {
                    regs.push(read_offset(em, reg, base.saturating_add(idx)));
                }
            }
            ResultColumn::Expr { expr, .. } => {
                let stripped = strip_paren(expr);
                if let Some(pos) = agg_slots.iter().position(|slot| slot.call == *stripped) {
                    regs.push(read_offset(em, reg, total_width.saturating_add(pos)));
                    continue;
                }
                let ExprKind::Column { table, name, .. } = &stripped.kind else {
                    return Err(CodegenError::Unsupported {
                        reason: "GROUP BY/aggregate combined with a JOIN only supports `*`/\
                                 `table.*`/bare column/whole aggregate-call result columns today"
                            .to_string(),
                    });
                };
                let (binding_idx, local_idx) =
                    resolve_scope_column(full_scope, table.as_deref(), name)?;
                let abs = joined_column_offset(full_scope, binding_idx).saturating_add(local_idx);
                regs.push(read_offset(em, reg, abs));
            }
        }

match (args, &slot.arg) {
        (FunctionArgs::Star, None) => Ok(true),
        (FunctionArgs::List(list), None) => Ok(list.is_empty()),
        (FunctionArgs::List(list), Some(slot_arg)) => {
            let [arg_expr] = list.as_slice() else {
                return Ok(false);
            };
            let a = joined_bare_column_offset(full_scope, arg_expr)?;
            let b = joined_bare_column_offset(full_scope, slot_arg)?;
            Ok(a == b)
        }
        (FunctionArgs::Star, Some(_)) => Ok(false),
    }

match args {
        FunctionArgs::Star => None,
        FunctionArgs::List(list) if list.len() <= 1 => list.first().cloned(),
        FunctionArgs::List(_) => {
            return Err(CodegenError::Unsupported {
                reason: format!(
                    "aggregate function {} with more than one argument is not yet supported",
                    name.to_ascii_lowercase()
                ),
            })
        }
    }

match name.as_str() {
        "count" => {}
        "sum" | "avg" | "min" | "max" if arg.is_some() => {}
        "sum" | "avg" | "min" | "max" => {
            return Err(CodegenError::Unsupported {
                reason: format!("{name}() requires a single argument"),
            })
        }
        other => {
            return Err(CodegenError::Unsupported {
                reason: format!("aggregate function {other} not yet supported in GROUP BY"),
            })
        }
    }

match &expr.kind {
        ExprKind::Paren(inner) | ExprKind::Collate { expr: inner, .. } => {
            find_aggregates(inner, out);
        }
        ExprKind::Unary { expr: inner, .. } => find_aggregates(inner, out),
        ExprKind::Binary { lhs, rhs, .. } => {
            find_aggregates(lhs, out);
            find_aggregates(rhs, out);
        }
        _ => {}
    }

match &expr.kind {
        ExprKind::Paren(inner) => ExprKind::Paren(Box::new(substitute_aggregates(
            inner,
            agg_slots,
            synthetic_names,
        ))),
        ExprKind::Collate {
            expr: inner,
            collation,
        } => ExprKind::Collate {
            expr: Box::new(substitute_aggregates(inner, agg_slots, synthetic_names)),
            collation: collation.clone(),
        },
        ExprKind::Unary { op, expr: inner } => ExprKind::Unary {
            op: *op,
            expr: Box::new(substitute_aggregates(inner, agg_slots, synthetic_names)),
        },
        ExprKind::Binary { op, lhs, rhs } => ExprKind::Binary {
            op: *op,
            lhs: Box::new(substitute_aggregates(lhs, agg_slots, synthetic_names)),
            rhs: Box::new(substitute_aggregates(rhs, agg_slots, synthetic_names)),
        },
        other => other.clone(),
    }

match &agg.arg {
        Some(expr) => {
            let collation = collation_of(expr)
                .or_else(|| expr_collation(scope, expr))
                .unwrap_or(Collation::Binary);
            (
                Some(compile_value(em, reg, scope, expr)?),
                1usize,
                collation,
            )
        }
        None => (None, 0usize, Collation::Binary),
    }

match col {
            ResultColumn::Expr { expr, alias } => ResultColumn::Expr {
                expr: substitute_aggregates(expr, agg_slots, &synthetic_names),
                alias: alias.clone(),
            },
            other => other.clone(),
        }

match &select.where_clause {
        Some(where_expr) => crate::codegen::row::subquery::hoist_uncorrelated_where_subqueries(
            em,
            reg,
            &table_scope,
            where_expr,
        )?,
        None => std::collections::HashMap::new(),
    }

match target {
            OrderByTarget::Column(idx) => *idx,
            OrderByTarget::Expr(e) => {
                let r = compile_value(em, reg, &table_scope, e)?;
                usize::try_from(r.saturating_sub(first)).unwrap_or(0)
            }
        }

match &agg.arg {
        Some(expr) => {
            let collation = collation_of(expr)
                .or_else(|| expr_collation(scope, expr))
                .unwrap_or(Collation::Binary);
            (
                Some(compile_value(em, reg, scope, expr)?),
                1usize,
                collation,
            )
        }
        None => (None, 0usize, Collation::Binary),
    }

match &table_ref.alias {
        Some(alias) => format!("{name} AS {alias}"),
        None => name.to_string(),
    }

match level_joins.get(level).map(Vec::as_slice) {
                Some([j]) => from.joins.get(*j).and_then(|join| match &join.constraint {
                    Some(JoinConstraint::On(e)) => Some(e),
                    _ => None,
                }),
                _ => None,
            }

match c {
                    JoinConstraint::On(e) => Some(e),
                    JoinConstraint::Using(_) => None,
                }

match (
                access,
                covering
                    .as_ref()
                    .and_then(|m| binding.schema.indexes.get(m.index_position)),
                skip_scan
                    .as_ref()
                    .and_then(|m| binding.schema.indexes.get(m.index_position))
                    .zip(skip_scan.as_ref().map(|m| m.column_position)),
            ) {
                (_, Some(index), _) => format!(
                    "SEARCH {} USING COVERING INDEX {} ({}=?)",
                    eqp_display_name(table_ref),
                    index.name,
                    index
                        .columns
                        .first()
                        .map_or_else(String::new, |c| c.name.clone())
                ),
                (None, None, Some((index, column_position))) => {
                    // Oracle sqlite3's own skip-scan EQP text, confirmed
                    // empirically (sqlite3 3.51.0): `SEARCH t USING INDEX
                    // idx (ANY(category) AND price=?)` -- one `ANY(col)`
                    // per unconstrained leading column, then `col=?` for
                    // the actually-probed column.
                    let parts: Vec<String> = index
                        .columns
                        .get(..column_position)
                        .unwrap_or_default()
                        .iter()
                        .map(|c| format!("ANY({})", c.name))
                        .chain(std::iter::once(format!(
                            "{}=?",
                            index
                                .columns
                                .get(column_position)
                                .map_or_else(String::new, |c| c.name.clone())
                        )))
                        .collect();
                    format!(
                        "SEARCH {} USING INDEX {} ({})",
                        eqp_display_name(table_ref),
                        index.name,
                        parts.join(" AND ")
                    )
                }
                // #545/#547: this level builds a transient automatic index
                // rather than falling back to a plain scan -- real sqlite3's
                // own wording for the equivalent case (confirmed empirically,
                // sqlite3 3.51.0): `SEARCH t USING AUTOMATIC COVERING INDEX
                // (col=?)`, no index name (it has none).
                (None, None, None) => match &auto_index_probe {
                    Some(AutoIndexProbe { key_column, .. }) => format!(
                        "SEARCH {} USING AUTOMATIC COVERING INDEX ({}=?)",
                        eqp_display_name(table_ref),
                        binding
                            .schema
                            .columns
                            .get(*key_column)
                            .map_or_else(String::new, |c| c.clone())
                    ),
                    None => format!("SCAN {}", eqp_display_name(table_ref)),
                },
                (Some(JoinAccess::Rowid(_)), None, _) => format!(
                    "SEARCH {} USING INTEGER PRIMARY KEY (rowid=?)",
                    eqp_display_name(table_ref)
                ),
                (Some(JoinAccess::UniqueIndex { index, .. }), None, _) => format!(
                    "SEARCH {} USING INDEX {} ({}=?)",
                    eqp_display_name(table_ref),
                    index.name,
                    index
                        .columns
                        .first()
                        .map_or_else(String::new, |c| c.name.clone())
                ),
            }

match op {
        CompoundOp::Union => "UNION USING TEMP B-TREE",
        CompoundOp::UnionAll => "UNION ALL",
    }

match &select.where_clause {
        None => {
            let root_page = valid_table_root_page(schema)?;
            em.emit(Instruction::new(Opcode::Count, root_page, count_reg, 0));
        }
        Some(where_expr) => {
            let Some((lhs, rhs)) = super::limit_scan::top_level_equality_operands(where_expr)
            else {
                return Ok(false);
            };
            fn where_col(expr: &Expr) -> Option<&str> {
                match &expr.kind {
                    ExprKind::Column { name, .. } => Some(name.as_str()),
                    _ => None,
                }
            }
            let (where_col_name, operand) = match (where_col(lhs), where_col(rhs)) {
                (Some(name), _) => (name, rhs),
                (_, Some(name)) => (name, lhs),
                _ => return Ok(false),
            };
            let is_supported_operand = matches!(
                &operand.kind,
                ExprKind::Literal(Literal::Integer(_))
                    | ExprKind::Param(ParamKind::Anonymous | ParamKind::Numbered(_))
            );
            if !is_supported_operand {
                return Ok(false);
            }
            // Uniqueness is no longer required (#450): a non-`UNIQUE`
            // index's leading-column match may have duplicate-key
            // siblings, walked below via `IdxNext` + a leading-column
            // recheck instead of assuming a single hit means count 1.
            let Some(index) = schema.indexes.iter().find(|idx| {
                idx.columns
                    .first()
                    .is_some_and(|c| c.name.eq_ignore_ascii_case(where_col_name))
            }) else {
                return Ok(false);
            };
            let root_page = valid_index_root_page(index)?;
            let mut open_instr = Instruction::new(Opcode::OpenRead, index_cursor, root_page, 0);
            open_instr.p5 = 1;
            em.emit(open_instr);

            let scope = Scope::single(schema, cursors.table).with_catalog(catalog.to_vec());
            let value_reg = compile_value(em, reg, &scope, operand)?;
            let leading_collation = index
                .columns
                .first()
                .map_or(Collation::Binary, |c| c.collation);
            let miss_label = em.new_label();
            let seek_addr = em.emit(Instruction::with_p4(
                Opcode::SeekIndexEq,
                index_cursor,
                0,
                value_reg,
                P4::SeekKey(vec![leading_collation]),
            ));
            em.patch_p2(seek_addr, miss_label);

            let loop_start = em.new_label();
            em.place(loop_start);
            let one_reg = reg.alloc();
            em.emit(Instruction::new(Opcode::Integer, 1, one_reg, 0));
            em.emit(Instruction::new(Opcode::Add, one_reg, count_reg, count_reg));

            // A `UNIQUE` index's single match falls straight through
            // here on the very first `IdxNext` (nothing shares its
            // key); a non-`UNIQUE` index's duplicate-key siblings loop
            // back to `loop_start`, incrementing once per match.
            let next_addr = em.emit(Instruction::new(Opcode::IdxNext, index_cursor, 0, 0));
            let recheck = em.new_label();
            em.patch_p2(next_addr, recheck);
            let exhausted = em.emit(Instruction::new(Opcode::Goto, 0, 0, 0));
            em.patch_p2(exhausted, miss_label);

            em.place(recheck);
            let leading = reg.alloc();
            em.emit(Instruction::new(Opcode::Column, index_cursor, 0, leading));
            // The leading index column's declared `COLLATE` (#500),
            // matching `SeekIndexEq`'s own probe comparison just above.
            let eq_addr = em.emit(Instruction::with_p4(
                Opcode::Eq,
                leading,
                0,
                value_reg,
                p4_coll_seq(leading_collation, Affinity::Blob),
            ));
            em.patch_p2(eq_addr, loop_start);

            em.place(miss_label);
        }
    }

match (where_col(lhs), where_col(rhs)) {
                (Some(name), _) => (name, rhs),
                (_, Some(name)) => (name, lhs),
                _ => return Ok(false),
            }

match &select.where_clause {
        Some(where_expr) => crate::codegen::row::subquery::hoist_uncorrelated_where_subqueries(
            em,
            reg,
            &table_scope,
            where_expr,
        )?,
        None => std::collections::HashMap::new(),
    }

match col {
            ResultColumn::Expr { expr, .. } => {
                walk_expr_for_column_refs(expr, &mut names, &mut bail)
            }
            ResultColumn::Star | ResultColumn::TableStar { .. } => bail = true,
        }

match schema
            .columns
            .iter()
            .position(|c| c.eq_ignore_ascii_case(name))
        {
            Some(idx) => {
                indices.insert(idx);
            }
            // Should always resolve at this point in codegen — an
            // unknown column would already have failed earlier
            // validation. Fall back to "every column" rather than
            // silently dropping one we can't place, on the off chance
            // this is reached some other way.
            None => return all_columns(),
        }

match &expr.kind {
        ExprKind::Column { name, .. } => {
            names.insert(name.to_ascii_lowercase());
        }
        ExprKind::Literal(_) | ExprKind::Param(_) => {}
        ExprKind::FunctionCall { args, .. } => {
            if let FunctionArgs::List(list) = args {
                for a in list {
                    walk_expr_for_column_refs(a, names, bail);
                }
            }
        }
        ExprKind::Unary { expr: e, .. }
        | ExprKind::IsNull { expr: e, .. }
        | ExprKind::Cast { expr: e, .. }
        | ExprKind::Collate { expr: e, .. }
        | ExprKind::Paren(e) => walk_expr_for_column_refs(e, names, bail),
        ExprKind::Binary { lhs, rhs, .. } | ExprKind::Is { lhs, rhs, .. } => {
            walk_expr_for_column_refs(lhs, names, bail);
            walk_expr_for_column_refs(rhs, names, bail);
        }
        ExprKind::Between {
            expr: e, lo, hi, ..
        } => {
            walk_expr_for_column_refs(e, names, bail);
            walk_expr_for_column_refs(lo, names, bail);
            walk_expr_for_column_refs(hi, names, bail);
        }
        ExprKind::In { expr: e, list, .. } => {
            walk_expr_for_column_refs(e, names, bail);
            for item in list {
                walk_expr_for_column_refs(item, names, bail);
            }
        }
        ExprKind::Like {
            expr: e,
            pattern,
            escape,
            ..
        } => {
            walk_expr_for_column_refs(e, names, bail);
            walk_expr_for_column_refs(pattern, names, bail);
            if let Some(esc) = escape {
                walk_expr_for_column_refs(esc, names, bail);
            }
        }
        ExprKind::Case {
            operand,
            whens,
            else_,
        } => {
            if let Some(o) = operand {
                walk_expr_for_column_refs(o, names, bail);
            }
            for (w, t) in whens {
                walk_expr_for_column_refs(w, names, bail);
                walk_expr_for_column_refs(t, names, bail);
            }
            if let Some(e) = else_ {
                walk_expr_for_column_refs(e, names, bail);
            }
        }
        ExprKind::Subquery(_)
        | ExprKind::Exists { .. }
        | ExprKind::InSubquery { .. }
        | ExprKind::InSubqueryMulti { .. } => {
            *bail = true;
        }
    }

match &select.where_clause {
        Some(where_expr) => crate::codegen::row::subquery::hoist_uncorrelated_where_subqueries(
            em,
            reg,
            &table_scope,
            where_expr,
        )?,
        None => std::collections::HashMap::new(),
    }

match target {
            // Always resolves: `needed_columns` includes every column
            // `select.group_by` references (`columns_needed_for_projection`),
            // so `idx` always has a compacted position.
            OrderByTarget::Column(idx) => compact_of.get(*idx).copied().flatten().unwrap_or(0),
            OrderByTarget::Expr(e) => {
                let r = compile_value(em, reg, &table_scope, e)?;
                usize::try_from(r.saturating_sub(first)).unwrap_or(0)
            }
        }

match target {
            OrderByTarget::Column(idx) => {
                let r = reg.alloc();
                // Always resolves — see the identical comment on
                // pass 1's `sort_keys` loop above.
                let compact_idx = compact_of.get(*idx).copied().flatten().unwrap_or(0);
                read_pseudo_column(em, &pseudo_schema, cursors.pseudo, compact_idx, r)?;
                Ok(r)
            }
            OrderByTarget::Expr(_) => compile_value(em, reg, &pseudo_scope, expr),
        }

match t {
            OrderByTarget::Column(idx) => Some(*idx),
            OrderByTarget::Expr(_) => None,
        }

match t {
            OrderByTarget::Column(idx) => Some(*idx),
            OrderByTarget::Expr(_) => None,
        }

match &expr.kind {
        ExprKind::Literal(Literal::Integer(_) | Literal::Float(_)) => matches!(
            column_affinity,
            Affinity::Integer | Affinity::Real | Affinity::Numeric
        ),
        ExprKind::Literal(Literal::Str(_)) => matches!(column_affinity, Affinity::Text),
        ExprKind::Param(_) => true,
        _ => false,
    }

match col {
            ResultColumn::Expr {
                expr:
                    Expr {
                        kind:
                            ExprKind::Column {
                                table: None,
                                catalog: None,
                                name,
                            },
                        ..
                    },
                ..
            } => Some(name.as_str()),
            _ => None,
        }

match &where_expr.kind {
        ExprKind::Between {
            expr,
            lo,
            hi,
            negated: false,
        } => {
            let col_name = where_col(expr)?;
            if !is_supported_operand(lo) || !is_supported_operand(hi) {
                return None;
            }
            let index_position = find_leading_index(schema, col_name)?;
            let affinity = column_affinity(schema, col_name);
            if !operand_matches_column_affinity(lo, affinity)
                || !operand_matches_column_affinity(hi, affinity)
            {
                return None;
            }
            Some(index_position)
        }
        ExprKind::Like {
            expr,
            pattern,
            glob,
            negated: false,
            escape: None,
        } => {
            let col_name = where_col(expr)?;
            let ExprKind::Literal(Literal::Str(pattern_str)) = &pattern.kind else {
                return None;
            };
            like_literal_prefix(pattern_str, *glob)?;
            let index_position = find_leading_index(schema, col_name)?;
            if column_affinity(schema, col_name) != Affinity::Text {
                return None;
            }
            Some(index_position)
        }
        ExprKind::In {
            expr,
            list,
            negated: false,
        } => {
            if list.is_empty() || !list.iter().all(is_supported_operand) {
                return None;
            }
            let col_name = where_col(expr)?;
            let index_position = find_leading_index(schema, col_name)?;
            let affinity = column_affinity(schema, col_name);
            if !list
                .iter()
                .all(|v| operand_matches_column_affinity(v, affinity))
            {
                return None;
            }
            Some(index_position)
        }
        _ => as_forward_comparison(where_expr).and_then(|(col_name, operand, _inclusive)| {
            if !is_supported_operand(operand) {
                return None;
            }
            let index_position = find_leading_index(schema, col_name)?;
            let affinity = column_affinity(schema, col_name);
            if !operand_matches_column_affinity(operand, affinity) {
                return None;
            }
            Some(index_position)
        }),
    }

match &where_expr.kind {
        ExprKind::Between {
            expr,
            lo,
            hi,
            negated: false,
        } => {
            let col_name = where_col(expr)?;
            if !is_supported_operand(lo) || !is_supported_operand(hi) {
                return None;
            }
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            let affinity = column_affinity(schema, col_name);
            if !operand_matches_column_affinity(lo, affinity)
                || !operand_matches_column_affinity(hi, affinity)
            {
                return None;
            }
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}>? AND {col_name}<?)",
                index.name
            ))
        }
        ExprKind::Like {
            expr,
            pattern,
            glob,
            negated: false,
            escape: None,
        } => {
            let col_name = where_col(expr)?;
            let ExprKind::Literal(Literal::Str(pattern_str)) = &pattern.kind else {
                return None;
            };
            like_literal_prefix(pattern_str, *glob)?;
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            if column_affinity(schema, col_name) != Affinity::Text {
                return None;
            }
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}>? AND {col_name}<?)",
                index.name
            ))
        }
        ExprKind::In {
            expr,
            list,
            negated: false,
        } => {
            if list.is_empty() || !list.iter().all(is_supported_operand) {
                return None;
            }
            let col_name = where_col(expr)?;
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            let affinity = column_affinity(schema, col_name);
            if !list
                .iter()
                .all(|v| operand_matches_column_affinity(v, affinity))
            {
                return None;
            }
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}=?)",
                index.name
            ))
        }
        _ => as_forward_comparison(where_expr).and_then(|(col_name, operand, _inclusive)| {
            if !is_supported_operand(operand) {
                return None;
            }
            let index_position = find_leading_index(schema, col_name)?;
            let index = schema.indexes.get(index_position)?;
            let affinity = column_affinity(schema, col_name);
            if !operand_matches_column_affinity(operand, affinity) {
                return None;
            }
            // Real sqlite3 collapses inclusive and exclusive into the
            // same `(col>?)` wording (see `try_compile_forward_comparison_seek`'s
            // doc) -- `_inclusive` only matters to the compiled seek's
            // dup-skip, not to this report.
            Some(format!(
                "SEARCH {table_display} USING INDEX {} ({col_name}>?)",
                index.name
            ))
        }),
    }

match index_ordering_prefix(schema, index, plans) {
        Some((len, forward)) if len == plans.len() => Some(forward),
        _ => None,
    }

match forward {
            None => forward = Some(this_forward),
            Some(f) if f == this_forward => {}
            _ => break,
        }

match &plan.target {
            OrderByTarget::Column(idx) => *idx,
            OrderByTarget::Expr(expr) => {
                let r = compile_value(em, reg, &scope, expr)?;
                usize::try_from(r.saturating_sub(first)).unwrap_or(0)
            }
        }

match &join.constraint {
        Some(JoinConstraint::On(e)) => Ok(Some(e.clone())),
        Some(JoinConstraint::Using(cols)) => {
            let (expr, shared) = synthesize_equality_constraint(left, right, &cols[..], true)?;
            if let Some(slot) = dedup_star.get_mut(right_idx) {
                slot.extend(shared);
            }
            Ok(expr)
        }
        None if join.natural => {
            let shared_names: Vec<String> = right
                .schema
                .columns
                .iter()
                .filter(|name| {
                    left.iter().any(|b| {
                        b.schema
                            .columns
                            .iter()
                            .any(|c| c.eq_ignore_ascii_case(name))
                    })
                })
                .cloned()
                .collect();
            if shared_names.is_empty() {
                Ok(None)
            } else {
                let (expr, shared) =
                    synthesize_equality_constraint(left, right, &shared_names, false)?;
                if let Some(slot) = dedup_star.get_mut(right_idx) {
                    slot.extend(shared);
                }
                Ok(expr)
            }
        }
        None => Ok(None),
    }

match plan.checks.as_slice() {
        [check] => check.constraint.as_ref().and_then(|constraint| {
            let prior = exec_bindings.get(..level)?;
            choose_join_access(binding, constraint, prior)
        }),
        _ => None,
    }

match plan.checks.as_slice() {
            [check] => check.constraint.as_ref().and_then(|constraint| {
                let prior = exec_bindings.get(..level)?;
                choose_auto_index_probe(binding, constraint, prior)
            }),
            _ => None,
        }

match single_check_access {
        Some(access) => {
            let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star);
            let miss = em.new_label();
            match access {
                JoinAccess::Rowid(operand) => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, value_reg));
                    em.patch_p2(seek_addr, miss);
                }
                JoinAccess::UniqueIndex { index, operand } => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let index_cursor = i32::try_from(exec_bindings.len().saturating_add(level))
                        .unwrap_or(i32::MAX);
                    let root_page = valid_index_root_page(&index)?;
                    let mut open_instr =
                        Instruction::new(Opcode::OpenRead, index_cursor, root_page, 0);
                    open_instr.p5 = 1;
                    em.emit(open_instr);
                    let leading_collation = index
                        .columns
                        .first()
                        .map_or(Collation::Binary, |c| c.collation);
                    let seek_instr = Instruction::with_p4(
                        Opcode::SeekIndexEq,
                        index_cursor,
                        0,
                        value_reg,
                        P4::SeekKey(vec![leading_collation]),
                    );
                    let seek_addr = em.emit(seek_instr);
                    em.patch_p2(seek_addr, miss);
                    let rowid_reg = reg.alloc();
                    em.emit(Instruction::new(
                        Opcode::IdxRowid,
                        index_cursor,
                        rowid_reg,
                        0,
                    ));
                    let table_seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, rowid_reg));
                    em.patch_p2(table_seek_addr, miss);
                }
            }
            if let Some(outer_level) = plan.checks.first().and_then(|c| c.sets_matched) {
                let target = matched_regs
                    .get(outer_level)
                    .copied()
                    .flatten()
                    .ok_or_else(|| CodegenError::Unsupported {
                        reason: "join level plan referenced an unallocated matched register"
                            .to_string(),
                    })?;
                em.emit(Instruction::new(Opcode::Integer, 1, target, 0));
            }
            let next_level = level.saturating_add(1);
            compile_join_level_traverse(
                em,
                reg,
                exec_bindings,
                orig_bindings,
                pos_of,
                levels,
                dedup_star,
                null_mask,
                matched_regs,
                next_level,
                catalog,
                leaf,
            )?;
            em.place(miss);
        }
        None if auto_index_probe.is_some() => {
            // #545: build a transient automatic index over `binding`'s
            // join column (a one-time `Once`-guarded pre-pass), then
            // probe it instead of a `Rewind`/`Next` full scan. Unlike a real
            // index's `SeekIndexEq` + recheck-then-`IdxNext` shape
            // (#450), the `AutoIndexSeek`/`AutoIndexRowid`/
            // `AutoIndexNext` primitives are an exact-key multi-map, so
            // there's no leading-column recheck loop needed — every
            // rowid `AutoIndexNext` yields already shares the seeked
            // key by construction.
            //
            // The match arm's own guard already established
            // `auto_index_probe.is_some()`; a nested `match` (rather
            // than an `unreachable!` else-branch) keeps that fact
            // encoded in the type system instead of a runtime panic
            // path, which this crate's macro-vocabulary gate (`make
            // mvl-limit`) doesn't allow outside its curated allowlist.
            let probe = match &auto_index_probe {
                Some(probe) => probe,
                None => {
                    return Err(CodegenError::Unsupported {
                        reason: "unreachable: guarded by the match arm's own is_some() condition"
                            .to_string(),
                    })
                }
            };
            let rewind_end = em.new_label();
            let eph_cursor = reg.alloc_cursor();

            let once_addr = em.emit(Instruction::new(Opcode::Once, 0, 0, 0));
            let after_build = em.new_label();
            let mut open_instr = Instruction::new(Opcode::OpenEphemeral, eph_cursor, 0, 0);
            open_instr.p5 = 2;
            em.emit(open_instr);
            let build_end = em.new_label();
            let build_rewind = em.emit(Instruction::new(Opcode::Rewind, cursor, 0, 0));
            em.patch_p2(build_rewind, build_end);
            let build_loop = em.new_label();
            em.place(build_loop);
            let key_reg = reg.alloc();
            emit_column_read(em, &binding.schema, cursor, probe.key_column, key_reg)?;
            let build_rowid_reg = reg.alloc();
            em.emit(Instruction::new(Opcode::Rowid, cursor, build_rowid_reg, 0));
            let leading_collation = binding
                .schema
                .column_collations
                .get(probe.key_column)
                .copied()
                .unwrap_or(Collation::Binary);
            em.emit(Instruction::with_p4(
                Opcode::AutoIndexInsert,
                eph_cursor,
                key_reg,
                build_rowid_reg,
                P4::SeekKey(vec![leading_collation]),
            ));
            let build_next = em.emit(Instruction::new(Opcode::Next, cursor, 0, 0));
            em.patch_p2(build_next, build_loop);
            em.place(build_end);
            em.place(after_build);
            em.patch_p2(once_addr, after_build);

            let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star);
            let probe_reg = compile_value(em, reg, &scope, &probe.probe)?;
            let seek_addr = em.emit(Instruction::with_p4(
                Opcode::AutoIndexSeek,
                eph_cursor,
                0,
                probe_reg,
                P4::SeekKey(vec![leading_collation]),
            ));
            em.patch_p2(seek_addr, rewind_end);

            let loop_start = em.new_label();
            em.place(loop_start);

            let skip = em.new_label();
            let idx_rowid_reg = reg.alloc();
            em.emit(Instruction::new(
                Opcode::AutoIndexRowid,
                eph_cursor,
                idx_rowid_reg,
                0,
            ));
            let table_seek_addr = em.emit(Instruction::new(
                Opcode::SeekRowid,
                cursor,
                0,
                idx_rowid_reg,
            ));
            em.patch_p2(table_seek_addr, skip);

            for check in &plan.checks {
                if let Some(constraint) = &check.constraint {
                    let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star);
                    compile_cond(
                        em,
                        reg,
                        &scope,
                        constraint,
                        CondTargets::null_is_false(Target::Fallthrough, Target::Jump(skip)),
                    )?;
                }
                if let Some(outer_level) = check.sets_matched {
                    let target = matched_regs
                        .get(outer_level)
                        .copied()
                        .flatten()
                        .ok_or_else(|| CodegenError::Unsupported {
                            reason: "join level plan referenced an unallocated matched register"
                                .to_string(),
                        })?;
                    em.emit(Instruction::new(Opcode::Integer, 1, target, 0));
                }
            }
            let next_level = level.saturating_add(1);
            compile_join_level_traverse(
                em,
                reg,
                exec_bindings,
                orig_bindings,
                pos_of,
                levels,
                dedup_star,
                null_mask,
                matched_regs,
                next_level,
                catalog,
                leaf,
            )?;

            em.place(skip);
            let next_addr = em.emit(Instruction::new(Opcode::AutoIndexNext, eph_cursor, 0, 0));
            em.patch_p2(next_addr, loop_start);
            em.place(rewind_end);
        }
        None => {
            let rewind_end = em.new_label();

            let rewind_addr = em.emit(Instruction::new(Opcode::Rewind, cursor, 0, 0));
            em.patch_p2(rewind_addr, rewind_end);
            let loop_start = em.new_label();
            em.place(loop_start);

            let skip = em.new_label();
            for check in &plan.checks {
                if let Some(constraint) = &check.constraint {
                    let scope = join_scope(orig_bindings, null_mask, pos_of, catalog, dedup_star);
                    compile_cond(
                        em,
                        reg,
                        &scope,
                        constraint,
                        CondTargets::null_is_false(Target::Fallthrough, Target::Jump(skip)),
                    )?;
                }
                if let Some(outer_level) = check.sets_matched {
                    let target = matched_regs
                        .get(outer_level)
                        .copied()
                        .flatten()
                        .ok_or_else(|| CodegenError::Unsupported {
                            reason: "join level plan referenced an unallocated matched register"
                                .to_string(),
                        })?;
                    em.emit(Instruction::new(Opcode::Integer, 1, target, 0));
                }
            }
            let next_level = level.saturating_add(1);
            compile_join_level_traverse(
                em,
                reg,
                exec_bindings,
                orig_bindings,
                pos_of,
                levels,
                dedup_star,
                null_mask,
                matched_regs,
                next_level,
                catalog,
                leaf,
            )?;
            em.place(skip);
            let next_addr = em.emit(Instruction::new(Opcode::Next, cursor, 0, 0));
            em.patch_p2(next_addr, loop_start);
            em.place(rewind_end);
        }
    }

match access {
                JoinAccess::Rowid(operand) => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, value_reg));
                    em.patch_p2(seek_addr, miss);
                }
                JoinAccess::UniqueIndex { index, operand } => {
                    let value_reg = compile_value(em, reg, &scope, &operand)?;
                    let index_cursor = i32::try_from(exec_bindings.len().saturating_add(level))
                        .unwrap_or(i32::MAX);
                    let root_page = valid_index_root_page(&index)?;
                    let mut open_instr =
                        Instruction::new(Opcode::OpenRead, index_cursor, root_page, 0);
                    open_instr.p5 = 1;
                    em.emit(open_instr);
                    let leading_collation = index
                        .columns
                        .first()
                        .map_or(Collation::Binary, |c| c.collation);
                    let seek_instr = Instruction::with_p4(
                        Opcode::SeekIndexEq,
                        index_cursor,
                        0,
                        value_reg,
                        P4::SeekKey(vec![leading_collation]),
                    );
                    let seek_addr = em.emit(seek_instr);
                    em.patch_p2(seek_addr, miss);
                    let rowid_reg = reg.alloc();
                    em.emit(Instruction::new(
                        Opcode::IdxRowid,
                        index_cursor,
                        rowid_reg,
                        0,
                    ));
                    let table_seek_addr =
                        em.emit(Instruction::new(Opcode::SeekRowid, cursor, 0, rowid_reg));
                    em.patch_p2(table_seek_addr, miss);
                }
            }

match &auto_index_probe {
                Some(probe) => probe,
                None => {
                    return Err(CodegenError::Unsupported {
                        reason: "unreachable: guarded by the match arm's own is_some() condition"
                            .to_string(),
                    })
                }
            }

match col {
            ResultColumn::Star | ResultColumn::TableStar { .. } => {
                for name in &schema.columns {
                    out.push(ResultColumnPlan::Column(name.clone()));
                }
            }
            ResultColumn::Expr { expr, .. } => out.push(ResultColumnPlan::Expr(expr.clone())),
        }

match col {
            ResultColumnPlan::Column(name) => schema
                .columns
                .iter()
                .position(|c| c == name)
                .and_then(|idx| schema.column_collations.get(idx).copied())
                .unwrap_or(Collation::Binary),
            ResultColumnPlan::Expr(expr) => {
                collation_of(expr).unwrap_or_else(|| match &order_by::strip_collate(expr).kind {
                    ExprKind::Column { name, .. } => schema
                        .columns
                        .iter()
                        .position(|c| c == name)
                        .and_then(|idx| schema.column_collations.get(idx).copied())
                        .unwrap_or(Collation::Binary),
                    _ => Collation::Binary,
                })
            }
        }

match col {
            ResultColumnPlan::Column(name) => {
                let idx =
                    column_index(schema, name).ok_or_else(|| CodegenError::UnknownColumn {
                        name: (*name).to_string(),
                    })?;
                let r = reg.alloc();
                if pseudo && schema.rowid_alias == Some(idx) {
                    // `cursor` is a post-`ORDER BY` `OpenPseudo` re-read
                    // of an already-materialized record (see
                    // `compile_sorted_scan`'s pass 1), not a live table
                    // cursor — there is no rowid to fetch via
                    // `Opcode::Rowid` (it isn't a table cursor at all).
                    // Pass 1 built this record via `emit_column_read`
                    // against the *real* cursor, which already resolved
                    // the rowid alias into an ordinary field at this
                    // same position — so a plain `Column` read recovers
                    // it here.
                    em.emit(Instruction::new(
                        Opcode::Column,
                        cursor,
                        i32::try_from(idx).map_err(|_| CodegenError::Unsupported {
                            reason: format!("column index {idx} does not fit in a P2 operand"),
                        })?,
                        r,
                    ));
                } else {
                    // Must go through `emit_column_read`, not a bare
                    // `Column`: this is the `*` / `tbl.*` expansion path, and
                    // an `INTEGER PRIMARY KEY` column is a NULL placeholder
                    // in the record. Emitting `Column` here is why
                    // `SELECT * FROM t` answered NULL for the rowid alias
                    // while `SELECT id FROM t` (which routes through
                    // `compile_value`) answered correctly.
                    emit_column_read(em, schema, cursor, idx, r)?;
                }
                r
            }
            ResultColumnPlan::Expr(expr) => {
                // A bare `name`/`tbl.name` reference — e.g. plain
                // `SELECT id FROM t ORDER BY id` — compiles as an `Expr`
                // here, not the `Column` variant above (that one is
                // reserved for `*`/`tbl.*` expansion), so it needs the
                // same pseudo-cursor rowid-alias special case: `Rowid`
                // only works against a real table cursor, and `cursor`
                // here may be the post-`ORDER BY` pseudo cursor instead.
                // A compound expression that merely *references* the
                // rowid alias (`id + 1`) isn't covered by this — falls
                // through to `compile_value`, matching this crate's
                // existing register-reuse limitations for compound
                // result-column expressions.
                if let ExprKind::Column {
                    name,
                    table: None,
                    catalog: None,
                } = &expr.kind
                {
                    let pseudo_rowid_idx = pseudo
                        .then(|| column_index(schema, name))
                        .flatten()
                        .filter(|idx| schema.rowid_alias == Some(*idx));
                    if let Some(idx) = pseudo_rowid_idx {
                        let r = reg.alloc();
                        em.emit(Instruction::new(
                            Opcode::Column,
                            cursor,
                            i32::try_from(idx).map_err(|_| CodegenError::Unsupported {
                                reason: format!("column index {idx} does not fit in a P2 operand"),
                            })?,
                            r,
                        ));
                        r
                    } else {
                        compile_value(
                            em,
                            reg,
                            &Scope::single(schema, cursor).with_catalog(catalog.to_vec()),
                            expr,
                        )?
                    }
                } else {
                    compile_value(
                        em,
                        reg,
                        &Scope::single(schema, cursor).with_catalog(catalog.to_vec()),
                        expr,
                    )?
                }
            }
        }

match &limit.offset {
        Some(offset_expr) => Some(compile_value(em, reg, scope, offset_expr)?),
        None => None,
    }

match &expr.kind {
        ExprKind::Binary {
            op: BinaryOp::And,
            lhs,
            rhs,
        } => {
            let mut conjuncts = flatten_and_conjuncts(lhs);
            conjuncts.extend(flatten_and_conjuncts(rhs));
            conjuncts
        }
        _ => vec![expr],
    }

match (where_col(lhs), where_col(rhs)) {
            (Some(name), None) if is_supported_seek_operand(rhs) => {
                direct.insert(name.to_ascii_lowercase(), rhs.clone());
            }
            (None, Some(name)) if is_supported_seek_operand(lhs) => {
                direct.insert(name.to_ascii_lowercase(), lhs.clone());
            }
            (Some(a), Some(b)) => {
                column_links.push((a.to_ascii_lowercase(), b.to_ascii_lowercase()));
            }
            _ => {}
        }

match &expr.kind {
        ExprKind::Binary {
            op: BinaryOp::Or,
            lhs,
            rhs,
        } => {
            let mut disjuncts = flatten_or_disjuncts(lhs);
            disjuncts.extend(flatten_or_disjuncts(rhs));
            disjuncts
        }
        _ => vec![expr],
    }

match direct_operand {
        Some(operand) if is_supported_seek_operand(operand) => vec![operand.clone()],
        _ => {
            let constants = propagate_constants(where_expr);
            match resolve_rowid_constant(schema, &constants) {
                Some(value) => vec![value],
                None => {
                    match or_chain_equality_operands(where_expr, |e| is_rowid_reference(schema, e))
                    {
                        Some(or_operands) => or_operands.into_iter().cloned().collect(),
                        None => return Ok(false),
                    }
                }
            }
        }
    }

match resolve_rowid_constant(schema, &constants) {
                Some(value) => vec![value],
                None => {
                    match or_chain_equality_operands(where_expr, |e| is_rowid_reference(schema, e))
                    {
                        Some(or_operands) => or_operands.into_iter().cloned().collect(),
                        None => return Ok(false),
                    }
                }
            }

match or_chain_equality_operands(where_expr, |e| is_rowid_reference(schema, e))
                    {
                        Some(or_operands) => or_operands.into_iter().cloned().collect(),
                        None => return Ok(false),
                    }

match col {
            ResultColumn::Star => out.extend(schema.columns.iter().cloned()),
            ResultColumn::TableStar { table } if table.eq_ignore_ascii_case(&schema.name) => {
                out.extend(schema.columns.iter().cloned());
            }
            ResultColumn::Expr {
                expr:
                    Expr {
                        kind: ExprKind::Column { name, .. },
                        ..
                    },
                ..
            } => out.push(name.clone()),
            _ => return None,
        }

match direct {
        Some(found) => found,
        None => schema
            .indexes
            .iter()
            .enumerate()
            .find_map(|(index_position, idx)| {
                let leading = idx.columns.first()?;
                let matches =
                    |e: &Expr| where_col(e).is_some_and(|n| n.eq_ignore_ascii_case(&leading.name));
                let operands = or_chain_equality_operands(where_expr, matches)?;
                Some((index_position, operands.into_iter().cloned().collect()))
            })?,
    }

match index
                .columns
                .iter()
                .position(|c| c.name.eq_ignore_ascii_case(name))
            {
                Some(col_idx) => em.emit(Instruction::new(
                    Opcode::Column,
                    index_cursor,
                    i32::try_from(col_idx).unwrap_or(0),
                    r,
                )),
                // #535: not one of the index's own columns — must be the
                // rowid-alias column `covers()` (in `find_covering_index`)
                // let through, retrievable from the index leaf's own rowid
                // rather than a declared column.
                None => em.emit(Instruction::new(Opcode::IdxRowid, index_cursor, r, 0)),
            }

super::range_scan::try_compile_between_seek(
        em, reg, select, schema, cursors, end_label, catalog, sink,
