match constraint {
        JoinConstraint::On(expr) => format!("JoinConstraint::On({})", render_expr(expr)),
        JoinConstraint::Using(cols) => format!(
            "JoinConstraint::Using(vec![{}])",
            cols.iter()
                .map(|c| format!("{}.to_string()", rust_str_literal(c)))
                .collect::<Vec<_>>()
                .join(", ")
        ),
    }

match col {
        ResultColumn::Star => "ResultColumn::Star".to_string(),
        ResultColumn::TableStar { table } => format!(
            "ResultColumn::TableStar {{ table: {}.to_string() }}",
            rust_str_literal(table)
        ),
        ResultColumn::Expr { expr, alias } => format!(
            "ResultColumn::Expr {{ expr: {}, alias: {} }}",
            render_expr(expr),
            render_option_str(alias.as_deref())
        ),
    }

match kind {
        ExprKind::Literal(lit) => format!("ExprKind::Literal({})", render_literal(lit)),
        ExprKind::Column {
            table,
            catalog,
            name,
        } => format!(
            "ExprKind::Column {{ table: {}, catalog: {}, name: {}.to_string() }}",
            render_option_str(table.as_deref()),
            render_option_str(catalog.as_deref()),
            rust_str_literal(name)
        ),
        ExprKind::FunctionCall {
            name,
            distinct,
            args,
            tail,
        } => format!(
            "ExprKind::FunctionCall {{ name: {}.to_string(), distinct: {distinct}, args: {}, tail: {} }}",
            rust_str_literal(name),
            render_function_args(args),
            match tail {
                Some(t) => format!(
                    "Some(Box::new(FunctionTail {{ filter: {}, over: {} }}))",
                    match &t.filter {
                        Some(f) => format!("Some({})", render_expr(f)),
                        None => "None".to_string(),
                    },
                    match &t.over {
                        Some(w) => format!("Some({})", render_window_def(w)),
                        None => "None".to_string(),
                    }
                ),
                None => "None".to_string(),
            }
        ),
        ExprKind::Unary { op, expr } => {
            format!("ExprKind::Unary {{ op: UnaryOp::{}, expr: Box::new({}) }}", render_unary_op(*op), render_expr(expr))
        }
        ExprKind::Binary { op, lhs, rhs } => format!(
            "ExprKind::Binary {{ op: BinaryOp::{}, lhs: Box::new({}), rhs: Box::new({}) }}",
            render_binary_op(*op),
            render_expr(lhs),
            render_expr(rhs)
        ),
        ExprKind::Is { lhs, rhs, negated } => format!(
            "ExprKind::Is {{ lhs: Box::new({}), rhs: Box::new({}), negated: {negated} }}",
            render_expr(lhs),
            render_expr(rhs)
        ),
        ExprKind::IsNull { expr, negated } => format!(
            "ExprKind::IsNull {{ expr: Box::new({}), negated: {negated} }}",
            render_expr(expr)
        ),
        ExprKind::Paren(inner) => format!("ExprKind::Paren(Box::new({}))", render_expr(inner)),
        ExprKind::InSubquery {
            expr,
            subquery,
            negated,
        } => format!(
            "ExprKind::InSubquery {{ expr: Box::new({}), subquery: Box::new({}), negated: {negated} }}",
            render_expr(expr),
            render_select(subquery)
        ),
        ExprKind::Exists { subquery, negated } => format!(
            "ExprKind::Exists {{ subquery: Box::new({}), negated: {negated} }}",
            render_select(subquery)
        ),
        // Not part of the batch planner's validated subset -- `generate`
        // never plans a query containing these, so no renderer feeds
        // this arm today. Not a feature gap to silently paper over: once
        // a real caller needs one of these, this arm should become a
        // real render, not before.
        ExprKind::Param(_)
        | ExprKind::Between { .. }
        | ExprKind::In { .. }
        | ExprKind::Like { .. }
        | ExprKind::Case { .. }
        | ExprKind::Cast { .. }
        | ExprKind::Collate { .. }
        | ExprKind::Subquery(_)
        | ExprKind::InSubqueryMulti { .. } => {
            // Rendered as a `compile_error!` in the *generated* source, so
            // if a planner ever does feed one of these here the consumer's
            // build fails loudly with the exact shape -- rather than this
            // emitter panicking (an `unreachable!` the qualified subset
            // forbids) or silently emitting a fake rendering.
            format!(
                "compile_error!(\"db-core emit does not yet render {}\")",
                format!("{kind:?}").replace('"', "'")
            )
        }
    }

match op {
        UnaryOp::Not => "Not",
        UnaryOp::Plus => "Plus",
        UnaryOp::Minus => "Minus",
        UnaryOp::BitNot => "BitNot",
    }

match op {
        Opcode::LoadColumn { reg, column } => format!(
            "Opcode::LoadColumn {{ reg: {reg}, column: std::borrow::Cow::Borrowed({}) }}",
            rust_str_literal(column)
        ),
        Opcode::LoadConst { reg, value } => format!(
            "Opcode::LoadConst {{ reg: {reg}, value: {} }}",
            render_value(value)
        ),
        Opcode::Map { dst, op, a, b } => format!(
            "Opcode::Map {{ dst: {dst}, op: MapOp::{}, a: {a}, b: {b} }}",
            render_map_op(*op)
        ),
        Opcode::Filter { predicate } => format!("Opcode::Filter {{ predicate: {predicate} }}"),
        Opcode::Reduce { func, src, dst } => format!(
            "Opcode::Reduce {{ func: AggFunc::{}, src: {}, dst: {dst} }}",
            render_agg_func(*func),
            render_option_usize(*src)
        ),
        Opcode::GroupReduce {
            group_by,
            aggs,
            agg_dst,
        } => {
            let group_by = render_usize_slice(group_by);
            let agg_dst = render_usize_slice(agg_dst);
            let aggs: Vec<String> = aggs
                .iter()
                .map(|(f, s)| {
                    format!(
                        "(AggFunc::{}, {})",
                        render_agg_func(*f),
                        render_option_usize(*s)
                    )
                })
                .collect();
            format!("Opcode::GroupReduce {{ group_by: std::borrow::Cow::Borrowed(&{group_by}), aggs: std::borrow::Cow::Borrowed(&[{}]), agg_dst: std::borrow::Cow::Borrowed(&{agg_dst}) }}", aggs.join(", "))
        }
        Opcode::Scan => "Opcode::Scan".to_string(),
        Opcode::Emit { registers } => format!(
            "Opcode::Emit {{ registers: std::borrow::Cow::Borrowed(&{}) }}",
            render_usize_slice(registers)
        ),
        Opcode::NextSegment { loop_start } => {
            format!("Opcode::NextSegment {{ loop_start: {loop_start} }}")
        }
        Opcode::Halt => "Opcode::Halt".to_string(),
        Opcode::Combine {
            agg_parts,
            num_group_keys,
            distinct,
        } => {
            let parts: Vec<String> = agg_parts.iter().map(render_agg_part).collect();
            format!(
                "Opcode::Combine {{ agg_parts: std::borrow::Cow::Borrowed(&[{}]), num_group_keys: {num_group_keys}, distinct: {distinct} }}",
                parts.join(", "),
            )
        }
        Opcode::Sort { col, descending } => {
            format!("Opcode::Sort {{ col: {col}, descending: {descending} }}")
        }
        Opcode::Limit { n } => format!("Opcode::Limit {{ n: {n} }}"),
        // No caller-side planner emits these three yet -- the join/semi-
        // join/window bypass shapes ([`render_joined`]/
        // [`render_semi_join`]/[`render_windowed`]) still reconstruct a
        // `Select` literal instead of a `const PROGRAM` for those cases
        // (see this module's top doc comment), so no flat program this
        // module renders contains them. Not a feature gap to silently
        // paper over with a fake rendering: once a real planner starts
        // emitting these, this arm should become a real render_*
        // implementation at that point, not before.
        Opcode::HashBuild { .. } | Opcode::HashProbe { .. } | Opcode::Window { .. } => {
            // Same `compile_error!`-in-generated-source strategy as
            // `render_expr_kind`'s unsupported arm: loud at the consumer's
            // build, no panic here.
            format!(
                "compile_error!(\"db-core emit does not yet render {}\")",
                format!("{op:?}").replace('"', "'")
            )
        }
    }

match value {
        Value::Int(v) => format!("Value::Int({v})"),
        Value::Float(v) => format!("Value::Float({v:?})"),
        Value::Bool(v) => format!("Value::Bool({v})"),
        Value::Str(v) => format!(
            "Value::Str(std::borrow::Cow::Borrowed({}))",
            rust_str_literal(v)
        ),
        Value::Null => "Value::Null".to_string(),
    }

match self.on_null {
                NullTarget::True => NullTarget::False,
                NullTarget::False => NullTarget::True,
            }

match self.resolve_own(table, name) {
            Ok(v) => Ok(v),
            Err(own_err) => match &self.outer {
                Some(outer) => outer.resolve(table, name),
                None => Err(own_err),
            },
        }

match &self.outer {
                Some(outer) => outer.resolve(table, name),
                None => Err(own_err),
            }

match c {
                TableConstraint::PrimaryKey(cols) => match cols.as_slice() {
                    [col] => matches!(&col.expr.kind, ExprKind::Column { name, .. } if name.eq_ignore_ascii_case(&only.name)),
                    _ => false,
                },
                _ => false,
            }

match cols.as_slice() {
                    [col] => matches!(&col.expr.kind, ExprKind::Column { name, .. } if name.eq_ignore_ascii_case(&only.name)),
                    _ => false,
                }

match v {
        Value::Null => 0,
        Value::Integer(_) | Value::Real(_) => 1,
        Value::Text(_) => 2,
        Value::Blob(_) => 3,
    }

match (x.is_nan(), y.is_nan()) {
        (true, true) => Ordering::Equal,
        (true, false) => Ordering::Greater,
        (false, true) => Ordering::Less,
        (false, false) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
    }

match self {
            Value::Int(v) => Some(*v as f64),
            Value::Float(v) => Some(*v),
            _ => None,
        }

match opcodes.as_slice() {
                [combine @ Opcode::Combine { .. }] => Some((Some(*combine), None, None)),
                [combine @ Opcode::Combine { .. }, sort @ Opcode::Sort { .. }] => {
                    Some((Some(*combine), Some(*sort), None))
                }
                [combine @ Opcode::Combine { .. }, limit @ Opcode::Limit { .. }] => {
                    Some((Some(*combine), None, Some(*limit)))
                }
                [combine @ Opcode::Combine { .. }, sort @ Opcode::Sort { .. }, limit @ Opcode::Limit { .. }] => {
                    Some((Some(*combine), Some(*sort), Some(*limit)))
                }
                _ => None,
            }

match (matches!(a, Value::Null), matches!(b, Value::Null)) {
        (true, true) => Ordering::Equal,
        (true, false) => Ordering::Greater,
        (false, true) => Ordering::Less,
        (false, false) => {
            let ord = match (a.as_f64(), b.as_f64()) {
                (Some(x), Some(y)) => x.partial_cmp(&y).unwrap_or(Ordering::Equal),
                _ => a.to_string().cmp(&b.to_string()),
            };
            if descending {
                ord.reverse()
            } else {
                ord
            }
        }
    }

match self {
            VmError::UnknownColumn { opcode, column } => {
                write!(f, "{opcode}: unknown column: {column}")
            }
            VmError::UnknownRegister { opcode, register } => {
                write!(f, "{opcode}: unknown register: {register}")
            }
            VmError::RegisterLengthMismatch { opcode } => {
                write!(f, "{opcode}: register length mismatch")
            }
            VmError::UnknownJoinTable { opcode, table } => {
                write!(f, "{opcode}: unknown join table: {table}")
            }
            VmError::StepLimitExceeded { opcode, limit } => {
                write!(f, "{opcode}: exceeded step limit of {limit}")
            }
            VmError::UnsupportedOp { opcode, op } => {
                write!(f, "{opcode}: no dispatch for {op}")
            }
        }

match value {
                Value::Int(v) => {
                    0u8.hash(state);
                    v.hash(state);
                }
                Value::Float(v) => {
                    1u8.hash(state);
                    v.to_bits().hash(state);
                }
                Value::Bool(v) => {
                    2u8.hash(state);
                    v.hash(state);
                }
                Value::Str(v) => {
                    3u8.hash(state);
                    v.hash(state);
                }
                Value::Null => 4u8.hash(state),
            }

match source.next_batch() {
            Some(b) => b,
            None => return Ok(Vec::new()),
        }

match op {
                Opcode::NextSegment { loop_start } => match source.next_batch() {
                    Some(next) => {
                        batch = next;
                        pc = *loop_start;
                    }
                    None => pc = pc.saturating_add(1),
                },
                Opcode::Halt => break,
                other => {
                    self.step(&batch, other)?;
                    pc = pc.saturating_add(1);
                }
            }

match source.next_batch() {
                    Some(next) => {
                        batch = next;
                        pc = *loop_start;
                    }
                    None => pc = pc.saturating_add(1),
                }

match op {
            Opcode::LoadColumn { reg, column } => {
                let values =
                    batch
                        .columns
                        .get(column.as_ref())
                        .ok_or_else(|| VmError::UnknownColumn {
                            opcode,
                            column: column.to_string(),
                        })?;
                self.registers.insert(*reg, values.clone());
            }
            Opcode::LoadConst { reg, value } => {
                self.registers
                    .insert(*reg, vec![value.clone(); batch.num_rows]);
            }
            Opcode::Map { dst, op, a, b } => {
                let (a_vals, b_vals) = (self.reg(*a, opcode)?, self.reg(*b, opcode)?);
                if a_vals.len() != b_vals.len() {
                    return Err(VmError::RegisterLengthMismatch { opcode });
                }
                let result = a_vals
                    .iter()
                    .zip(b_vals)
                    .map(|(x, y)| apply_map_op(*op, x, y))
                    .collect();
                self.registers.insert(*dst, result);
            }
            Opcode::Filter { predicate } => {
                let mask: Vec<bool> = self
                    .reg(*predicate, opcode)?
                    .iter()
                    .map(|v| matches!(v, Value::Bool(true)))
                    .collect();
                // #110: size each kept-values buffer to the actual survivor
                // count (not the pre-filter length) -- at 50% selectivity on
                // a 10M-row scan, over-allocating by 2x per live register is
                // real peak-RSS waste for no benefit (the excess capacity is
                // never used, just reserved).
                let kept_len = mask.iter().filter(|&&keep| keep).count();
                for values in self.registers.values_mut() {
                    if values.len() != mask.len() {
                        return Err(VmError::RegisterLengthMismatch { opcode });
                    }
                    let mut kept = Vec::with_capacity(kept_len);
                    for (value, keep) in values.drain(..).zip(&mask) {
                        if *keep {
                            kept.push(value);
                        }
                    }
                    *values = kept;
                }
            }
            Opcode::Reduce { func, src, dst } => {
                let result = match src {
                    Some(reg) => reduce_values(*func, self.reg(*reg, opcode)?),
                    None => reduce_count_star(*func, batch.num_rows),
                };
                self.registers.insert(*dst, vec![result]);
            }
            Opcode::GroupReduce {
                group_by,
                aggs,
                agg_dst,
            } => {
                let key_columns: Vec<Vec<Value>> = group_by
                    .iter()
                    .map(|reg| self.reg(*reg, opcode).map(<[Value]>::to_vec))
                    .collect::<Result<_>>()?;
                let num_rows = match key_columns.first() {
                    Some(c) => c.len(),
                    None => match aggs.iter().find_map(|(_, src)| {
                        src.map(|reg| self.reg(reg, opcode).map(<[Value]>::len))
                    }) {
                        Some(len) => len?,
                        None => self
                            .registers
                            .values()
                            .next()
                            .map_or(batch.num_rows, Vec::len),
                    },
                };

                let mut group_index: HashMap<String, usize> = HashMap::new();
                let mut group_keys: Vec<Vec<Value>> = Vec::new();
                let mut row_group: Vec<usize> = Vec::with_capacity(num_rows);
                for row in 0..num_rows {
                    let key: Vec<Value> = key_columns.iter().map(|c| c[row].clone()).collect();
                    let key_str = key
                        .iter()
                        .map(Value::to_string)
                        .collect::<Vec<_>>()
                        .join("\u{0}");
                    let group = *group_index.entry(key_str).or_insert_with(|| {
                        group_keys.push(key);
                        group_keys.len() - 1
                    });
                    row_group.push(group);
                }
                let num_groups = group_keys.len();

                for (i, reg) in group_by.iter().enumerate() {
                    self.registers
                        .insert(*reg, group_keys.iter().map(|k| k[i].clone()).collect());
                }

                for ((func, src), dst) in aggs.iter().zip(agg_dst.iter()) {
                    let mut per_group: Vec<Vec<Value>> = vec![Vec::new(); num_groups];
                    match src {
                        Some(reg) => {
                            // #110: borrow instead of `.to_vec()` -- same
                            // redundant-clone pattern as the old `Emit`.
                            let values = self.reg(*reg, opcode)?;
                            for (row, group) in row_group.iter().enumerate() {
                                per_group[*group].push(values[row].clone());
                            }
                        }
                        None => {
                            for group in &row_group {
                                per_group[*group].push(Value::Null);
                            }
                        }
                    }
                    let result = per_group
                        .iter()
                        .map(|vals| {
                            if src.is_none() {
                                Value::Int(vals.len() as i64)
                            } else {
                                reduce_values(*func, vals)
                            }
                        })
                        .collect();
                    self.registers.insert(*dst, result);
                }
            }
            Opcode::HashBuild {
                key_cols,
                payload_cols,
                table,
            } => {
                let key_columns: Vec<&[Value]> = key_cols
                    .iter()
                    .map(|r| self.reg(*r, opcode))
                    .collect::<Result<_>>()?;
                let payload_columns: Vec<&[Value]> = payload_cols
                    .iter()
                    .map(|r| self.reg(*r, opcode))
                    .collect::<Result<_>>()?;
                let num_rows = key_columns.first().map_or(0, |c| c.len());

                let mut ht: JoinHashTable<JoinKey, Vec<Value>> =
                    JoinHashTable::with_capacity(num_rows);
                for row in 0..num_rows {
                    let key = JoinKey(key_columns.iter().map(|c| c[row].clone()).collect());
                    let payload = payload_columns.iter().map(|c| c[row].clone()).collect();
                    ht.insert(key, payload);
                }
                self.join_tables.insert(*table, ht);
            }
            Opcode::HashProbe {
                key_cols,
                table,
                payload_dst,
                kind,
            } => {
                let key_columns: Vec<&[Value]> = key_cols
                    .iter()
                    .map(|r| self.reg(*r, opcode))
                    .collect::<Result<_>>()?;
                let num_rows = key_columns.first().map_or(0, |c| c.len());
                let ht = self
                    .join_tables
                    .get(table)
                    .ok_or(VmError::UnknownJoinTable {
                        opcode,
                        table: *table,
                    })?;

                // Owned so the borrow of `self.join_tables` (via `ht`) and
                // of `self.registers` (via `key_columns`) both end here,
                // before the reshape below needs to mutably borrow
                // `self.registers`.
                let mut emitted: Vec<(usize, Option<Vec<Value>>)> = Vec::with_capacity(num_rows);
                for row in 0..num_rows {
                    let key = JoinKey(key_columns.iter().map(|c| c[row].clone()).collect());
                    let matches: Vec<&Vec<Value>> = ht.get_all(&key);
                    if matches.is_empty() {
                        if should_emit(*kind, false, false) {
                            emitted.push((row, None));
                        }
                    } else if matches!(kind, JoinKind::Semi) {
                        // At most one row per probe-side match, regardless
                        // of build-side fanout; no payload (see doc comment
                        // on `Opcode::HashProbe`).
                        emitted.push((row, None));
                    } else {
                        for m in matches {
                            if should_emit(*kind, true, true) {
                                emitted.push((row, Some(m.clone())));
                            }
                        }
                    }
                }

                for values in self.registers.values_mut() {
                    if values.len() != num_rows {
                        return Err(VmError::RegisterLengthMismatch { opcode });
                    }
                    *values = emitted
                        .iter()
                        .map(|(row, _)| values[*row].clone())
                        .collect();
                }

                for (i, dst) in payload_dst.iter().enumerate() {
                    let col: Vec<Value> = emitted
                        .iter()
                        .map(|(_, payload)| match payload {
                            Some(p) => p.get(i).cloned().unwrap_or(Value::Null),
                            None => Value::Null,
                        })
                        .collect();
                    self.registers.insert(*dst, col);
                }
            }
            Opcode::Window {
                func,
                arg,
                offset,
                partition_by,
                order_by,
                dst,
            } => {
                let partition_cols: Vec<&[Value]> = partition_by
                    .iter()
                    .map(|r| self.reg(*r, opcode))
                    .collect::<Result<_>>()?;
                let order_cols: Vec<(&[Value], bool)> = order_by
                    .iter()
                    .map(|(r, desc)| self.reg(*r, opcode).map(|c| (c, *desc)))
                    .collect::<Result<_>>()?;
                let arg_col: Option<&[Value]> = match arg {
                    Some(r) => Some(self.reg(*r, opcode)?),
                    None => None,
                };

                let num_rows = partition_cols.first().map_or_else(
                    || {
                        order_cols.first().map_or_else(
                            || arg_col.map_or(batch.num_rows, <[Value]>::len),
                            |(c, _)| c.len(),
                        )
                    },
                    |c| c.len(),
                );

                let result = compute_window(
                    *func,
                    *offset,
                    &partition_cols,
                    &order_cols,
                    arg_col,
                    num_rows,
                )?;
                self.registers.insert(*dst, result);
            }
            Opcode::Emit { registers } => {
                // #110: borrow each register instead of `.to_vec()`-ing it
                // first -- the transpose loop below already clones every
                // cell once to build each output row, so cloning the whole
                // column again first (the previous `.to_vec()`) doubled the
                // clone cost of every surviving value for no reason.
                let cols: Vec<&[Value]> = registers
                    .iter()
                    .map(|r| self.reg(*r, opcode))
                    .collect::<Result<_>>()?;
                let num_rows = cols.first().map_or(0, |c| c.len());
                let mut rows = Vec::with_capacity(num_rows);
                for row in 0..num_rows {
                    rows.push(cols.iter().map(|c| c[row].clone()).collect());
                }
                drop(cols);
                self.output.extend(rows);
            }
            // Meaningful only as loop markers interpreted by `run` --
            // and `Combine`/`Sort`/`Limit` are the cross-segment
            // sequential phase applied once by `crate::vm::engine::run`,
            // never inside a single segment.
            Opcode::Scan
            | Opcode::NextSegment { .. }
            | Opcode::Halt
            | Opcode::Combine { .. }
            | Opcode::Sort { .. }
            | Opcode::Limit { .. } => {}
        }

match src {
                    Some(reg) => reduce_values(*func, self.reg(*reg, opcode)?),
                    None => reduce_count_star(*func, batch.num_rows),
                }

match key_columns.first() {
                    Some(c) => c.len(),
                    None => match aggs.iter().find_map(|(_, src)| {
                        src.map(|reg| self.reg(reg, opcode).map(<[Value]>::len))
                    }) {
                        Some(len) => len?,
                        None => self
                            .registers
                            .values()
                            .next()
                            .map_or(batch.num_rows, Vec::len),
                    },
                }

match aggs.iter().find_map(|(_, src)| {
                        src.map(|reg| self.reg(reg, opcode).map(<[Value]>::len))
                    }) {
                        Some(len) => len?,
                        None => self
                            .registers
                            .values()
                            .next()
                            .map_or(batch.num_rows, Vec::len),
                    }

match src {
                        Some(reg) => {
                            // #110: borrow instead of `.to_vec()` -- same
                            // redundant-clone pattern as the old `Emit`.
                            let values = self.reg(*reg, opcode)?;
                            for (row, group) in row_group.iter().enumerate() {
                                per_group[*group].push(values[row].clone());
                            }
                        }
                        None => {
                            for group in &row_group {
                                per_group[*group].push(Value::Null);
                            }
                        }
                    }

match payload {
                            Some(p) => p.get(i).cloned().unwrap_or(Value::Null),
                            None => Value::Null,
                        }

match arg {
                    Some(r) => Some(self.reg(*r, opcode)?),
                    None => None,
                }

match func {
            WindowFunc::RowNumber => {
                for (pos, &row) in indices.iter().enumerate() {
                    output[row] = Value::Int((pos + 1) as i64);
                }
            }
            WindowFunc::Rank | WindowFunc::DenseRank => {
                let mut rank = 0i64;
                let mut dense = 0i64;
                let mut prev: Option<usize> = None;
                for (pos, &row) in indices.iter().enumerate() {
                    let is_new = match prev {
                        None => true,
                        Some(prev_row) => order_cols
                            .iter()
                            .any(|(col, _)| col[row].to_string() != col[prev_row].to_string()),
                    };
                    if is_new {
                        rank = (pos + 1) as i64;
                        dense += 1;
                    }
                    output[row] = Value::Int(if func == WindowFunc::Rank {
                        rank
                    } else {
                        dense
                    });
                    prev = Some(row);
                }
            }
            WindowFunc::Lag | WindowFunc::Lead => {
                let offset = offset.unwrap_or(1);
                #[allow(
                    clippy::expect_used,
                    reason = "codegen guarantees the argument column for this window function"
                )]
                let arg = arg_col.expect("Lag/Lead always have an argument column");
                let n = indices.len() as i64;
                for (pos, &row) in indices.iter().enumerate() {
                    let target = if func == WindowFunc::Lag {
                        pos as i64 - offset
                    } else {
                        pos as i64 + offset
                    };
                    output[row] = if target >= 0 && target < n {
                        arg[indices[target as usize]].clone()
                    } else {
                        Value::Null
                    };
                }
            }
            WindowFunc::FirstValue => {
                #[allow(
                    clippy::expect_used,
                    reason = "codegen guarantees the argument column for this window function"
                )]
                let arg = arg_col.expect("FirstValue always has an argument column");
                if let Some(&first) = indices.first() {
                    let v = arg[first].clone();
                    for &row in &indices {
                        output[row] = v.clone();
                    }
                }
            }
            WindowFunc::LastValue => {
                #[allow(
                    clippy::expect_used,
                    reason = "codegen guarantees the argument column for this window function"
                )]
                let arg = arg_col.expect("LastValue always has an argument column");
                for &row in &indices {
                    output[row] = arg[row].clone();
                }
            }
            WindowFunc::Sum | WindowFunc::Avg | WindowFunc::Count => {
                if order_cols.is_empty() {
                    let agg = whole_partition_aggregate(func, arg_col, &indices)?;
                    for &row in &indices {
                        output[row] = agg.clone();
                    }
                } else {
                    let mut running_sum = 0.0;
                    let mut running_count = 0i64;
                    for &row in &indices {
                        let counted = match arg_col {
                            Some(a) => !matches!(a[row], Value::Null),
                            None => true,
                        };
                        if counted {
                            running_count += 1;
                            if let Some(a) = arg_col {
                                if let Some(v) = a[row].as_f64() {
                                    running_sum += v;
                                }
                            }
                        }
                        output[row] = match func {
                            WindowFunc::Count => Value::Int(running_count),
                            WindowFunc::Sum => {
                                if running_count > 0 {
                                    Value::Float(running_sum)
                                } else {
                                    Value::Null
                                }
                            }
                            WindowFunc::Avg => {
                                if running_count > 0 {
                                    Value::Float(running_sum / running_count as f64)
                                } else {
                                    Value::Null
                                }
                            }
                            other => {
                                return Err(VmError::UnsupportedOp {
                                    opcode: "Window",
                                    op: format!("{other:?} as a running aggregate"),
                                })
                            }
                        };
                    }
                }
            }
        }

match prev {
                        None => true,
                        Some(prev_row) => order_cols
                            .iter()
                            .any(|(col, _)| col[row].to_string() != col[prev_row].to_string()),
                    }

match arg_col {
                            Some(a) => !matches!(a[row], Value::Null),
                            None => true,
                        }

match func {
                            WindowFunc::Count => Value::Int(running_count),
                            WindowFunc::Sum => {
                                if running_count > 0 {
                                    Value::Float(running_sum)
                                } else {
                                    Value::Null
                                }
                            }
                            WindowFunc::Avg => {
                                if running_count > 0 {
                                    Value::Float(running_sum / running_count as f64)
                                } else {
                                    Value::Null
                                }
                            }
                            other => {
                                return Err(VmError::UnsupportedOp {
                                    opcode: "Window",
                                    op: format!("{other:?} as a running aggregate"),
                                })
                            }
                        }

match func {
        WindowFunc::Sum => Ok(Value::Float(values.iter().sum())),
        WindowFunc::Avg => Ok(Value::Float(
            values.iter().sum::<f64>() / values.len() as f64,
        )),
        other => Err(VmError::UnsupportedOp {
            opcode: "Window",
            op: format!("{other:?} as a partition aggregate"),
        }),
    }

match func {
        AggFunc::Count => Value::Int(num_rows as i64),
        _ => Value::Null,
    }

match func {
        AggFunc::Count => {
            Value::Int(values.iter().filter(|v| !matches!(v, Value::Null)).count() as i64)
        }
        AggFunc::Sum => {
            if non_null.is_empty() {
                Value::Null
            } else {
                Value::Float(non_null.iter().sum())
            }
        }
        AggFunc::Avg => {
            if non_null.is_empty() {
                Value::Null
            } else {
                Value::Float(non_null.iter().sum::<f64>() / non_null.len() as f64)
            }
        }
        AggFunc::Min => non_null
            .into_iter()
            .fold(None, |acc: Option<f64>, v| {
                Some(acc.map_or(v, |a| a.min(v)))
            })
            .map_or(Value::Null, Value::Float),
        AggFunc::Max => non_null
            .into_iter()
            .fold(None, |acc: Option<f64>, v| {
                Some(acc.map_or(v, |a| a.max(v)))
            })
            .map_or(Value::Null, Value::Float),
    }

match op {
        MapOp::Add => arithmetic(op, a, b, |x, y| x + y),
        MapOp::Sub => arithmetic(op, a, b, |x, y| x - y),
        MapOp::Mul => arithmetic(op, a, b, |x, y| x * y),
        MapOp::Div => arithmetic(op, a, b, |x, y| x / y),
        MapOp::Eq => comparison(a, b, |o| o == Some(Equal)),
        MapOp::Ne => comparison(a, b, |o| o != Some(Equal)),
        MapOp::Lt => comparison(a, b, |o| o == Some(Less)),
        MapOp::Le => comparison(a, b, |o| matches!(o, Some(Less | Equal))),
        MapOp::Gt => comparison(a, b, |o| o == Some(Greater)),
        MapOp::Ge => comparison(a, b, |o| matches!(o, Some(Greater | Equal))),
        MapOp::And => Value::Bool(as_bool(a) && as_bool(b)),
        MapOp::Or => Value::Bool(as_bool(a) || as_bool(b)),
        MapOp::Not => Value::Bool(!as_bool(a)),
        MapOp::Concat => Value::Str(Cow::Owned(format!("{a}{b}"))),
        MapOp::Neg => match a {
            // `-i64::MIN` has no integer representation; SQLite promotes
            // that one case to REAL rather than overflowing.
            Value::Int(v) => v
                .checked_neg()
                .map_or(Value::Float(-(*v as f64)), Value::Int),
            Value::Float(v) => Value::Float(-v),
            _ => Value::Null,
        },
        // Already answered by the early returns above (they must see
        // `Null`); the same semantics here keep this match total without
        // an `unreachable!` the qualified subset forbids.
        MapOp::IsNull => Value::Bool(matches!(a, Value::Null)),
        MapOp::IsNotNull => Value::Bool(!matches!(a, Value::Null)),
        MapOp::MaskIf => {
            if matches!(b, Value::Bool(true)) {
                a.clone()
            } else {
                Value::Null
            }
        }
    }

match a {
            // `-i64::MIN` has no integer representation; SQLite promotes
            // that one case to REAL rather than overflowing.
            Value::Int(v) => v
                .checked_neg()
                .map_or(Value::Float(-(*v as f64)), Value::Int),
            Value::Float(v) => Value::Float(-v),
            _ => Value::Null,
        }

match (a, b) {
        (Value::Str(x), Value::Str(y)) => Some(x.cmp(y)),
        (Value::Bool(x), Value::Bool(y)) => Some(x.cmp(y)),
        _ => a.as_f64()?.partial_cmp(&b.as_f64()?),
    }

match name {
            "part" => 0,
            "ord" => 1,
            "val" => 2,
            other => panic!("unexpected test column: {other}"),
        }

match &r[0] {
                Value::Int(v) => *v,
                other => panic!("expected Value::Int, got {other:?}"),
            }

match (lhs, rhs) {
        (Some(a), Some(b)) => {
            if a.is_numeric() || b.is_numeric() {
                Affinity::Numeric
            } else {
                Affinity::Blob
            }
        }
        (Some(a), None) | (None, Some(a)) => a,
        (None, None) => Affinity::Blob,
    }

match value {
            Value::Integer(i) => *value = Value::Text(i.to_string().into()),
            Value::Real(r) => *value = Value::Text(format_real(*r).into()),
            Value::Text(_) | Value::Blob(_) | Value::Null => {}
        }

match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Null, _) | (_, Value::Null) => false,
        _ => compare(a, b, collation) == Ordering::Equal,
    }

match (a, b) {
        (Some(false), _) | (_, Some(false)) => Some(false),
        (Some(true), Some(true)) => Some(true),
        _ => None,
    }

match (a, b) {
        (Some(true), _) | (_, Some(true)) => Some(true),
        (Some(false), Some(false)) => Some(false),
        _ => None,
    }

match self {
            ExecError::RegisterOutOfRange { opcode, index } => {
                write!(f, "{opcode}: register index {index} is out of range")
            }
            ExecError::RegisterRangeTooLarge { opcode, count } => write!(
                f,
                "{opcode}: register range count {count} exceeds the maximum ({MAX_REGISTERS})"
            ),
            ExecError::TypeMismatch { opcode, found } => {
                write!(
                    f,
                    "{opcode}: expected a different value type, found {found}"
                )
            }
            ExecError::MustBeInt => write!(
                f,
                "MustBeInt: value cannot be converted to an integer without data loss"
            ),
            ExecError::MalformedInstruction { opcode, reason } => {
                write!(f, "{opcode}: malformed instruction ({reason})")
            }
            ExecError::Unimplemented { opcode } => {
                write!(f, "opcode {opcode:?} is not yet implemented by this VM")
            }
            ExecError::CursorNotOpen { slot } => write!(f, "cursor slot {slot} is not open"),
            ExecError::ProgramCounterOutOfRange { pc } => {
                write!(f, "program counter {pc} is out of range")
            }
            ExecError::StepLimitExceeded => write!(
                f,
                "program exceeded the maximum step count ({MAX_STEPS}) without halting"
            ),
            ExecError::Halted { code, message } => write!(
                f,
                "statement halted with result code {code}{}",
                message
                    .as_deref()
                    .map(|m| format!(": {m}"))
                    .unwrap_or_default()
            ),
            ExecError::JournalModeChangeDuringTransaction => write!(
                f,
                "SetJournalMode: cannot change journal mode within a transaction"
            ),
            ExecError::TransactionAlreadyActive => {
                write!(f, "cannot start a transaction within a transaction")
            }
            ExecError::NoActiveTransactionToCommit => {
                write!(f, "cannot commit - no transaction is active")
            }
            ExecError::NoActiveTransactionToRollback => {
                write!(f, "cannot rollback - no transaction is active")
            }
            ExecError::TransactionFailed(err) => write!(f, "transaction hook failed: {err}"),
            ExecError::AttachedDatabasesUnsupported => {
                write!(f, "attached databases are not supported")
            }
            ExecError::CursorFactoryFailed(err) => write!(f, "cursor factory failed: {err}"),
            ExecError::SchemaStorageMissing { opcode } => {
                write!(f, "{opcode}: no schema storage hook is installed")
            }
            ExecError::SchemaStorageFailed(err) => write!(f, "schema storage failed: {err}"),
        }

match v {
        Value::Integer(i) => *i == 0,
        Value::Real(r) => *r == 0.0,
        Value::Null => false,
        Value::Text(s) => match coerce::coerce_text_to_numeric(s) {
            Value::Integer(i) => i == 0,
            Value::Real(r) => r == 0.0,
            _ => true,
        },
        Value::Blob(_) => true,
    }

match coerce::coerce_text_to_numeric(s) {
            Value::Integer(i) => i == 0,
            Value::Real(r) => r == 0.0,
            _ => true,
        }

match self.registers.get_mut(idx) {
            Some(slot) => std::mem::replace(slot, Value::Null),
            None => Value::Null,
        }

match self.register(reg)? {
            Value::Blob(bytes) => {
                Ok(decode_column(bytes, col, self.text_encoding).unwrap_or(Value::Null))
            }
            Value::Null => Ok(Value::Null),
            other => Err(ExecError::MalformedInstruction {
                opcode,
                reason: format!("pseudo-cursor register holds {other:?}, not a record blob"),
            }),
        }

match &instr.p4 {
        P4::CollSeq {
            collation,
            affinity,
        } => (*collation, Affinity::from_p4_byte(*affinity)),
        _ => (Collation::Binary, Affinity::Blob),
    }

match vm.register(instr.p1)? {
        Value::Null => Value::Null,
        other => coerce::bit_not(other),
    }

match vm.register(reg)? {
        Value::Integer(i) => Ok(*i),
        other => Err(ExecError::TypeMismatch {
            opcode: "control counter",
            found: value_kind(other),
        }),
    }

match p4 {
        P4::SeekKey(collations) => Ok(collations.clone()),
        P4::Int(n) => {
            let count = Vm::bounded_count(
                opcode,
                i32::try_from(*n).map_err(|_| ExecError::MalformedInstruction {
                    opcode,
                    reason: format!("key count {n} does not fit in p4"),
                })?,
            )?;
            Ok(vec![Collation::Binary; count])
        }
        other => Err(ExecError::MalformedInstruction {
            opcode,
            reason: format!("expected a SeekKey or Int P4 (key columns), got {other:?}"),
        }),
    }

match instr.opcode {
        Opcode::Init => Ok(if instr.p2 == 0 {
            Step::Next
        } else {
            Step::Jump(to_pc(instr.p2))
        }),
        Opcode::Goto => Ok(Step::Jump(to_pc(instr.p2))),
        Opcode::Once => {
            if vm.once_fired.insert(pc) {
                Ok(Step::Next)
            } else {
                Ok(Step::Jump(to_pc(instr.p2)))
            }
        }
        Opcode::BeginSubrtn => Ok(Step::Next),
        Opcode::Return => match vm.register(instr.p1)? {
            Value::Integer(i) => match i32::try_from(*i) {
                Ok(target) => Ok(Step::Jump(to_pc(target))),
                Err(_) => Err(ExecError::MalformedInstruction {
                    opcode: "Return",
                    reason: format!("return address {i} does not fit in a PC"),
                }),
            },
            other => Err(ExecError::TypeMismatch {
                opcode: "Return",
                found: value_kind(other),
            }),
        },
        Opcode::Halt => {
            let message = match &instr.p4 {
                P4::Str(s) => Some(s.clone()),
                _ => None,
            };
            Ok(Step::Halt {
                code: instr.p1,
                message,
            })
        }
        Opcode::IsNull => {
            let jump = matches!(vm.register(instr.p1)?, Value::Null);
            Ok(if jump {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }
        Opcode::NotNull => {
            let jump = !matches!(vm.register(instr.p1)?, Value::Null);
            Ok(if jump {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }
        Opcode::IfNot => {
            let v = vm.register(instr.p1)?;
            let take_jump = match v {
                Value::Null => instr.p3 != 0,
                other => is_falsy(other),
            };
            Ok(if take_jump {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }
        Opcode::MustBeInt => {
            let v = vm.register(instr.p1)?.clone();
            match try_to_integer(&v) {
                Some(i) => {
                    vm.set_register(instr.p1, Value::Integer(i))?;
                    Ok(Step::Next)
                }
                None if instr.p2 != 0 => Ok(Step::Jump(to_pc(instr.p2))),
                None => Err(ExecError::MustBeInt),
            }
        }
        Opcode::OffsetLimit => {
            let limit = register_as_i64(vm, instr.p1)?;
            let offset = register_as_i64(vm, instr.p3)?;
            let combined = if limit > 0 {
                limit.saturating_add(offset.max(0))
            } else {
                -1
            };
            vm.set_register(instr.p2, Value::Integer(combined))?;
            Ok(Step::Next)
        }
        Opcode::IfPos => {
            let v = register_as_i64(vm, instr.p1)?;
            if v > 0 {
                vm.set_register(
                    instr.p1,
                    Value::Integer(v.saturating_sub(i64::from(instr.p3))),
                )?;
                Ok(Step::Jump(to_pc(instr.p2)))
            } else {
                Ok(Step::Next)
            }
        }
        Opcode::IfNotZero => {
            let v = register_as_i64(vm, instr.p1)?;
            if v != 0 {
                if v > 0 {
                    vm.set_register(instr.p1, Value::Integer(v.saturating_sub(1)))?;
                }
                Ok(Step::Jump(to_pc(instr.p2)))
            } else {
                Ok(Step::Next)
            }
        }
        Opcode::DecrJumpZero => {
            let v = register_as_i64(vm, instr.p1)?.saturating_sub(1);
            vm.set_register(instr.p1, Value::Integer(v))?;
            Ok(if v == 0 {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }

        Opcode::Eq => compare_jump(vm, instr, |o| o == Ordering::Equal),
        Opcode::Ge => compare_jump(vm, instr, |o| o != Ordering::Less),
        Opcode::Gt => compare_jump(vm, instr, |o| o == Ordering::Greater),
        Opcode::Le => compare_jump(vm, instr, |o| o != Ordering::Greater),
        Opcode::Lt => compare_jump(vm, instr, |o| o == Ordering::Less),
        Opcode::RealAffinity => real_affinity(vm, instr),
        Opcode::Cast => cast(vm, instr),

        Opcode::Add => binary_op(vm, instr, coerce::checked_add),
        Opcode::Subtract => binary_op_reversed(vm, instr, coerce::checked_sub),
        Opcode::Multiply => binary_op(vm, instr, coerce::checked_mul),
        Opcode::Divide => binary_op_reversed(vm, instr, coerce::checked_div),
        Opcode::Remainder => binary_op_reversed(vm, instr, coerce::checked_rem),
        Opcode::Not => arith_not(vm, instr),
        Opcode::BitAnd => binary_op(vm, instr, coerce::bit_and),
        Opcode::BitOr => binary_op(vm, instr, coerce::bit_or),
        Opcode::ShiftLeft => binary_op_reversed(vm, instr, coerce::shift_left),
        Opcode::ShiftRight => binary_op_reversed(vm, instr, coerce::shift_right),
        Opcode::BitNot => bit_not(vm, instr),
        Opcode::Concat => binary_op_reversed(vm, instr, coerce::concat),

        Opcode::Integer => {
            vm.set_register(instr.p2, Value::Integer(i64::from(instr.p1)))?;
            Ok(Step::Next)
        }
        Opcode::Int64 => {
            let i = match &instr.p4 {
                P4::Int(i) => *i,
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "Int64",
                        reason: format!("expected an integer P4, got {other:?}"),
                    })
                }
            };
            vm.set_register(instr.p2, Value::Integer(i))?;
            Ok(Step::Next)
        }
        Opcode::Real => {
            let r = match &instr.p4 {
                P4::Real(r) => *r,
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "Real",
                        reason: format!("expected a real P4, got {other:?}"),
                    })
                }
            };
            vm.set_register(instr.p2, Value::Real(r))?;
            Ok(Step::Next)
        }
        Opcode::Blob => {
            let bytes = match &instr.p4 {
                P4::Blob(bytes) => bytes.clone(),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "Blob",
                        reason: format!("expected a blob P4, got {other:?}"),
                    })
                }
            };
            vm.set_register(instr.p2, Value::Blob(bytes.into()))?;
            Ok(Step::Next)
        }
        Opcode::Null => {
            let last = instr.p3.max(instr.p2);
            for reg in instr.p2..=last {
                vm.set_register(reg, Value::Null)?;
            }
            Ok(Step::Next)
        }
        Opcode::String8 => {
            let s = match &instr.p4 {
                P4::Str(s) => s.clone(),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "String8",
                        reason: format!("expected a string P4, got {other:?}"),
                    })
                }
            };
            vm.set_register(instr.p2, Value::Text(s.into()))?;
            Ok(Step::Next)
        }
        Opcode::Variable => {
            let value = vm.param(instr.p1).cloned().unwrap_or(Value::Null);
            vm.set_register(instr.p2, value)?;
            Ok(Step::Next)
        }
        Opcode::Copy => {
            let value = vm.register(instr.p1)?.clone();
            vm.set_register(instr.p2, value)?;
            Ok(Step::Next)
        }
        Opcode::MakeRecord => {
            let count = Vm::bounded_count("MakeRecord", instr.p2)?;
            let affinities: &[u8] = match &instr.p4 {
                P4::Affinity(bytes) => bytes,
                _ => &[],
            };
            let mut values = Vec::with_capacity(count);
            for i in 0..count {
                let reg = instr
                    .p1
                    .checked_add(i as i32)
                    .ok_or(ExecError::RegisterOutOfRange {
                        opcode: "MakeRecord",
                        index: instr.p1,
                    })?;
                let mut value = vm.register(reg)?.clone();
                if let Some(byte) = affinities.get(i) {
                    apply_affinity(&mut value, Affinity::from_p4_byte(*byte));
                }
                values.push(value);
            }
            let payload = encode_record(&values, TextEncoding::Utf8);
            vm.set_register(instr.p3, Value::Blob(payload.into()))?;
            Ok(Step::Next)
        }
        Opcode::ResultRow => {
            let count = Vm::bounded_count("ResultRow", instr.p2)?;
            let mut row = Vec::with_capacity(count);
            for i in 0..count {
                let reg = instr
                    .p1
                    .checked_add(i as i32)
                    .ok_or(ExecError::RegisterOutOfRange {
                        opcode: "ResultRow",
                        index: instr.p1,
                    })?;
                row.push(vm.take_register(reg)?);
            }
            vm.emit_row(row);
            Ok(Step::Next)
        }

        Opcode::Rewind => {
            vm.clear_null_row(instr.p1)?;
            let has_row = vm.cursor_mut(instr.p1)?.rewind();
            Ok(if has_row {
                Step::Next
            } else {
                Step::Jump(to_pc(instr.p2))
            })
        }
        Opcode::Next => {
            vm.clear_null_row(instr.p1)?;
            let has_row = vm.cursor_mut(instr.p1)?.next();
            Ok(if has_row {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }
        Opcode::Last => {
            vm.clear_null_row(instr.p1)?;
            let has_row = vm.cursor_mut(instr.p1)?.last();
            Ok(if has_row {
                Step::Next
            } else {
                Step::Jump(to_pc(instr.p2))
            })
        }
        Opcode::Column => {
            #[allow(clippy::cast_sign_loss)]
            let col = instr.p2 as usize;
            let value = if vm.is_null_row(instr.p1)? {
                Value::Null
            } else if let Some(reg) = vm.pseudo_reg(instr.p1) {
                vm.pseudo_column(reg, col, "Column")?
            } else {
                vm.cursor(instr.p1)?.column(col)
            };
            vm.set_register(instr.p3, value)?;
            Ok(Step::Next)
        }
        Opcode::Rowid => {
            // sqlite-rs: a NullRow'd cursor reads NULL for its rowid too.
            let value = if vm.is_null_row(instr.p1)? {
                Value::Null
            } else {
                Value::Integer(vm.cursor(instr.p1)?.rowid())
            };
            vm.set_register(instr.p2, value)?;
            Ok(Step::Next)
        }
        Opcode::SeekRowid => {
            vm.clear_null_row(instr.p1)?;
            let rowid = register_as_i64(vm, instr.p3)?;
            let found = vm.cursor_mut(instr.p1)?.seek(rowid);
            Ok(if found {
                Step::Next
            } else {
                Step::Jump(to_pc(instr.p2))
            })
        }
        Opcode::NullRow => {
            vm.set_null_row(instr.p1)?;
            Ok(Step::Next)
        }
        Opcode::Sequence => {
            let value = vm.next_sequence(instr.p1)?;
            vm.set_register(instr.p2, Value::Integer(value))?;
            Ok(Step::Next)
        }
        Opcode::Count => {
            // sqlite-rs: p1 is the *root page* of the table to count (the
            // `SELECT count(*)` fast path opens its own cursor); with no
            // cursor factory (in-memory programs) p1 names an open slot.
            let count = if let Some(factory) = vm.cursor_factory.as_deref_mut() {
                #[allow(clippy::cast_sign_loss)]
                let root = instr.p1 as u32;
                let mut cursor = factory
                    .open_read(root)
                    .map_err(ExecError::CursorFactoryFailed)?;
                count_rows(cursor.as_mut())
            } else {
                count_rows(vm.cursor_mut(instr.p1)?.as_mut())
            };
            vm.set_register(instr.p2, Value::Integer(count))?;
            Ok(Step::Next)
        }
        Opcode::AutoIndexInsert => {
            // sqlite-rs: p2 = first key register (count/collations from P4),
            // p3 = rowid register.
            let (key, collations) = key_from_registers(vm, "AutoIndexInsert", instr.p2, &instr.p4)?;
            let rowid = register_as_i64(vm, instr.p3)?;
            if vm.cursor(instr.p1).is_err() {
                vm.open_cursor(instr.p1, Box::new(super::cursor::AutoIndexCursor::new()))?;
            }
            let ok = vm
                .cursor_mut(instr.p1)?
                .auto_index_insert(key, &collations, rowid);
            if !ok {
                return Err(ExecError::MalformedInstruction {
                    opcode: "AutoIndexInsert",
                    reason: "cursor slot is not an automatic-index cursor".to_string(),
                });
            }
            Ok(Step::Next)
        }
        Opcode::AutoIndexSeek => {
            let (key, collations) = key_from_registers(vm, "AutoIndexSeek", instr.p3, &instr.p4)?;
            let found = vm.cursor_mut(instr.p1)?.auto_index_seek(&key, &collations);
            Ok(if found {
                Step::Next
            } else {
                Step::Jump(to_pc(instr.p2))
            })
        }
        Opcode::AutoIndexRowid => {
            let rowid = vm.cursor(instr.p1)?.rowid();
            vm.set_register(instr.p2, Value::Integer(rowid))?;
            Ok(Step::Next)
        }
        Opcode::AutoIndexNext => {
            let has_next = vm.cursor_mut(instr.p1)?.auto_index_next();
            Ok(if has_next {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }
        Opcode::OpenRead | Opcode::OpenWrite => {
            if instr.p3 != 0 {
                return Err(ExecError::AttachedDatabasesUnsupported);
            }
            let Some(factory) = vm.cursor_factory.as_deref_mut() else {
                // No factory installed -- fall back to the pre-wired
                // path: assert the caller already wired this slot via
                // `open_cursor` before running the program.
                vm.cursor(instr.p1)?;
                return Ok(Step::Next);
            };
            #[allow(clippy::cast_sign_loss)]
            let root = instr.p2 as u32;
            // sqlite-rs flags an index cursor with `p5 != 0` (no key
            // descriptor); a `P4::SortKey` carries one when the planner has it.
            let cursor = match (&instr.p4, instr.p5, instr.opcode) {
                (P4::SortKey(key), _, _) => factory.open_index(root, key),
                (_, p5, _) if p5 != 0 => factory.open_index(root, &[]),
                (_, _, Opcode::OpenWrite) => factory.open_write(root),
                _ => factory.open_read(root),
            }
            .map_err(ExecError::CursorFactoryFailed)?;
            vm.open_cursor(instr.p1, cursor)?;
            vm.set_cursor_root(instr.p1, root)?;
            Ok(Step::Next)
        }
        Opcode::OpenDup => {
            // sqlite-rs: a second cursor sharing an ephemeral table's rows.
            if let Some(dup) = vm.cursor(instr.p2)?.dup() {
                vm.open_cursor(instr.p1, dup)?;
                return Ok(Step::Next);
            }
            let root = vm.cursor_root(instr.p2)?;
            let factory =
                vm.cursor_factory
                    .as_deref_mut()
                    .ok_or(ExecError::CursorFactoryFailed(CursorFactoryError(
                        "OpenDup requires a cursor factory".to_string(),
                    )))?;
            let cursor = factory
                .open_read(root)
                .map_err(ExecError::CursorFactoryFailed)?;
            vm.open_cursor(instr.p1, cursor)?;
            vm.set_cursor_root(instr.p1, root)?;
            Ok(Step::Next)
        }
        Opcode::OpenPseudo => {
            // sqlite-rs: the cursor reads register p2 *lazily* — codegen
            // opens it before the register holds a row (`SorterData` /
            // `MakeRecord` fill it later, and rewrite it between rows).
            vm.open_cursor(instr.p1, Box::new(PseudoCursor::new(&[])))?;
            vm.set_pseudo_reg(instr.p1, Some(instr.p2))?;
            Ok(Step::Next)
        }
        Opcode::OpenEphemeral => {
            // sqlite-rs `cursor::open_ephemeral`: p5 = 0 -> ephemeral index
            // (DISTINCT / IN-subquery), 1 -> ephemeral table (materialized
            // rows by rowid), 2 -> automatic join index.
            let cursor: Box<dyn Cursor> = match instr.p5 {
                0 => Box::new(super::cursor::EphemeralIndexCursor::new()),
                2 => Box::new(super::cursor::AutoIndexCursor::new()),
                _ => Box::new(EphemeralTableCursor::new()),
            };
            vm.open_cursor(instr.p1, cursor)?;
            Ok(Step::Next)
        }
        Opcode::SorterOpen => {
            let keys = match &instr.p4 {
                P4::SortKey(keys) => keys.clone(),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "SorterOpen",
                        reason: format!("expected a SortKey P4, got {other:?}"),
                    })
                }
            };
            let bound = if instr.p5 == 0 {
                None
            } else {
                match vm.register(instr.p2)? {
                    Value::Integer(n) if *n >= 0 => usize::try_from(*n).ok(),
                    _ => None,
                }
            };
            vm.open_cursor(instr.p1, Box::new(SorterCursor::new(keys, bound)))?;
            Ok(Step::Next)
        }
        Opcode::SorterInsert => {
            let blob = match vm.register(instr.p2)? {
                Value::Blob(bytes) => bytes.clone(),
                other => {
                    return Err(ExecError::TypeMismatch {
                        opcode: "SorterInsert",
                        found: value_kind(other),
                    })
                }
            };
            let inserted = vm.cursor_mut(instr.p1)?.sorter_insert(blob);
            if !inserted {
                return Err(ExecError::MalformedInstruction {
                    opcode: "SorterInsert",
                    reason: "cursor slot is not a sorter".to_string(),
                });
            }
            Ok(Step::Next)
        }
        Opcode::SorterSort | Opcode::Sort | Opcode::HashAggRewind => {
            let has_row = vm.cursor_mut(instr.p1)?.rewind();
            Ok(if has_row {
                Step::Next
            } else {
                Step::Jump(to_pc(instr.p2))
            })
        }
        Opcode::SorterNext | Opcode::HashAggNext => {
            let has_row = vm.cursor_mut(instr.p1)?.next();
            Ok(if has_row {
                Step::Jump(to_pc(instr.p2))
            } else {
                Step::Next
            })
        }
        Opcode::SorterData => {
            let blob =
                vm.cursor(instr.p1)?
                    .current_blob()
                    .ok_or(ExecError::MalformedInstruction {
                        opcode: "SorterData",
                        reason: "sorter has not been sorted yet, or has no current row".to_string(),
                    })?;
            vm.set_register(instr.p2, blob)?;
            Ok(Step::Next)
        }
        Opcode::HashAggOpen => {
            let keys = match &instr.p4 {
                P4::GroupKey(keys) => keys.clone(),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "HashAggOpen",
                        reason: format!("expected a GroupKey P4, got {other:?}"),
                    })
                }
            };
            vm.open_cursor(instr.p1, Box::new(HashAggCursor::new(keys)))?;
            Ok(Step::Next)
        }
        Opcode::HashAggFind => {
            let blob = match vm.register(instr.p2)? {
                Value::Blob(bytes) => bytes.clone(),
                other => {
                    return Err(ExecError::TypeMismatch {
                        opcode: "HashAggFind",
                        found: value_kind(other),
                    })
                }
            };
            let found = vm.cursor_mut(instr.p1)?.hash_agg_find(blob);
            if !found {
                return Err(ExecError::MalformedInstruction {
                    opcode: "HashAggFind",
                    reason: "cursor slot is not a hash-aggregation cursor".to_string(),
                });
            }
            Ok(Step::Next)
        }
        Opcode::HashAggStep => {
            let (name, arity, collation) = match &instr.p4 {
                P4::AggFunc {
                    name,
                    arity,
                    collation,
                } => (name.as_str(), *arity, *collation),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "HashAggStep",
                        reason: format!("expected an AggFunc P4, got {other:?}"),
                    })
                }
            };
            let mut args = Vec::with_capacity(arity);
            for i in 0..arity {
                let reg = instr
                    .p2
                    .checked_add(i32::try_from(i).unwrap_or(i32::MAX))
                    .ok_or(ExecError::RegisterOutOfRange {
                        opcode: "HashAggStep",
                        index: instr.p2,
                    })?;
                args.push(vm.register(reg)?.clone());
            }
            #[allow(clippy::cast_sign_loss)]
            let slot = instr.p1.max(0) as usize;
            let handled = vm
                .cursor_mut(instr.p3)?
                .hash_agg_step(slot, name, &args, collation)
                .map_err(|e| ExecError::MalformedInstruction {
                    opcode: "HashAggStep",
                    reason: e.to_string(),
                })?;
            if !handled {
                return Err(ExecError::MalformedInstruction {
                    opcode: "HashAggStep",
                    reason: "cursor slot has no current group".to_string(),
                });
            }
            Ok(Step::Next)
        }
        Opcode::HashAggData => {
            let blob =
                vm.cursor(instr.p1)?
                    .current_blob()
                    .ok_or(ExecError::MalformedInstruction {
                    opcode: "HashAggData",
                    reason:
                        "hash-aggregation cursor has not been rewound yet, or has no current group"
                            .to_string(),
                })?;
            let accumulators: Vec<Option<AggState>> = vm
                .cursor(instr.p1)?
                .hash_agg_group_accumulators()
                .map(<[_]>::to_vec)
                .unwrap_or_default();
            for (slot, state) in accumulators.into_iter().enumerate() {
                let slot = i32::try_from(slot).unwrap_or(i32::MAX);
                match state {
                    Some(state) => vm.set_agg_context(slot, state)?,
                    None => vm.clear_agg_context(slot)?,
                }
            }
            vm.set_register(instr.p2, blob)?;
            Ok(Step::Next)
        }
        Opcode::Insert => {
            let rowid = match vm.register(instr.p2)? {
                Value::Integer(i) => *i,
                other => {
                    return Err(ExecError::TypeMismatch {
                        opcode: "Insert",
                        found: value_kind(other),
                    })
                }
            };
            let payload = match vm.register(instr.p3)? {
                Value::Blob(bytes) => bytes.clone(),
                other => {
                    return Err(ExecError::TypeMismatch {
                        opcode: "Insert",
                        found: value_kind(other),
                    })
                }
            };
            let encoding = vm.text_encoding;
            let cursor = vm.cursor_mut(instr.p1)?;
            // A storage-backed cursor takes the record bytes as they are
            // (byte-exact with MakeRecord); in-memory ones decode them.
            let inserted = match cursor.insert_payload(rowid, &payload) {
                Some(ok) => ok,
                None => {
                    let values = decode_record(&payload, encoding).map_err(|e| {
                        ExecError::MalformedInstruction {
                            opcode: "Insert",
                            reason: e.to_string(),
                        }
                    })?;
                    cursor.insert(rowid, values)
                }
            };
            if !inserted {
                return Err(ExecError::MalformedInstruction {
                    opcode: "Insert",
                    reason: "cursor slot does not support insertion".to_string(),
                });
            }
            Ok(Step::Next)
        }

        Opcode::Function => {
            let descriptor = match &instr.p4 {
                P4::Str(s) => s.as_str(),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "Function",
                        reason: format!("expected a \"name(arity)\" string P4, got {other:?}"),
                    })
                }
            };
            let (name, arity) = parse_function_descriptor(descriptor).ok_or_else(|| {
                ExecError::MalformedInstruction {
                    opcode: "Function",
                    reason: format!("malformed function descriptor {descriptor:?}"),
                }
            })?;
            let mut args = Vec::with_capacity(arity);
            for i in 0..arity {
                let reg = instr
                    .p2
                    .checked_add(i32::try_from(i).unwrap_or(i32::MAX))
                    .ok_or(ExecError::RegisterOutOfRange {
                        opcode: "Function",
                        index: instr.p2,
                    })?;
                args.push(vm.register(reg)?.clone());
            }
            let result =
                functions::call(name, &args).map_err(|e| ExecError::MalformedInstruction {
                    opcode: "Function",
                    reason: e.to_string(),
                })?;
            vm.set_register(instr.p3, result)?;
            Ok(Step::Next)
        }

        Opcode::AggStep => {
            let (name, arity, collation) = match &instr.p4 {
                P4::AggFunc {
                    name,
                    arity,
                    collation,
                } => (name.as_str(), *arity, *collation),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "AggStep",
                        reason: format!("expected an AggFunc P4, got {other:?}"),
                    })
                }
            };
            let mut args = Vec::with_capacity(arity);
            for i in 0..arity {
                let reg = instr
                    .p2
                    .checked_add(i32::try_from(i).unwrap_or(i32::MAX))
                    .ok_or(ExecError::RegisterOutOfRange {
                        opcode: "AggStep",
                        index: instr.p2,
                    })?;
                args.push(vm.register(reg)?.clone());
            }
            let current = if instr.p5 == 0 {
                vm.agg_context(instr.p1)?.cloned()
            } else {
                None
            };
            let updated = aggregate::step(name, current, &args, collation).map_err(|e| {
                ExecError::MalformedInstruction {
                    opcode: "AggStep",
                    reason: e.to_string(),
                }
            })?;
            vm.set_agg_context(instr.p1, updated)?;
            Ok(Step::Next)
        }
        Opcode::AggFinal => {
            let descriptor = match &instr.p4 {
                P4::Str(s) => s.as_str(),
                other => {
                    return Err(ExecError::MalformedInstruction {
                        opcode: "AggFinal",
                        reason: format!("expected a \"name(arity)\" string P4, got {other:?}"),
                    })
                }
            };
            let (name, _arity) = parse_function_descriptor(descriptor).ok_or_else(|| {
                ExecError::MalformedInstruction {
                    opcode: "AggFinal",
                    reason: format!("malformed aggregate descriptor {descriptor:?}"),
                }
            })?;
            let state = vm.agg_context(instr.p1)?;
            let result =
                aggregate::finalize(name, state).map_err(|e| ExecError::MalformedInstruction {
                    opcode: "AggFinal",
                    reason: e.to_string(),
                })?;
            vm.set_register(instr.p3, result)?;
            vm.clear_agg_context(instr.p1)?;
            Ok(Step::Next)
        }

        Opcode::Transaction => {
            if !vm.autocommit {
                return Err(ExecError::TransactionAlreadyActive);
            }
            if let Some(hook) = vm.transaction_hook.as_mut() {
                hook.begin(instr.p1).map_err(ExecError::TransactionFailed)?;
            }
            vm.autocommit = false;
            Ok(Step::Next)
        }
        Opcode::AutoCommit => {
            if vm.autocommit {
                return Err(if instr.p2 == 0 {
                    ExecError::NoActiveTransactionToRollback
                } else {
                    ExecError::NoActiveTransactionToCommit
                });
            }
            if let Some(hook) = vm.transaction_hook.as_mut() {
                if instr.p2 == 0 {
                    hook.rollback().map_err(ExecError::TransactionFailed)?;
                } else {
                    hook.commit().map_err(ExecError::TransactionFailed)?;
                }
            }
            vm.autocommit = true;
            Ok(Step::Next)
        }
        Opcode::SetJournalMode => {
            if !vm.autocommit {
                return Err(ExecError::JournalModeChangeDuringTransaction);
            }
            // The attached pager (via the transaction hook) switches its
            // on-disk journal mode; with no hook this is the no-op
            // sqlite-rs itself falls back to for a read-only connection.
            if let Some(hook) = vm.transaction_hook.as_mut() {
                hook.set_journal_mode(instr.p1)
                    .map_err(ExecError::TransactionFailed)?;
            }
            Ok(Step::Next)
        }
        Opcode::Synchronous => {
            // Query form reports the pager's level (FULL with no pager,
            // sqlite-rs's no-writer fallback); otherwise sets it.
            if instr.p1 == SYNCHRONOUS_QUERY {
                let level = vm
                    .transaction_hook
                    .as_deref()
                    .and_then(|h| h.synchronous())
                    .unwrap_or(SYNCHRONOUS_FULL);
                vm.emit_row(vec![Value::Integer(i64::from(level))]);
                return Ok(Step::Next);
            }
            if let Some(hook) = vm.transaction_hook.as_mut() {
                hook.set_synchronous(instr.p1)
                    .map_err(ExecError::TransactionFailed)?;
            }
            Ok(Step::Next)
        }
        Opcode::IntegrityCheck => {
            // `p1 != 0` is quick_check. One TEXT row per problem line
            // (sqlite-rs `pragma::integrity_check`); without a hook that
            // can read the file this stays Unimplemented.
            let quick = instr.p1 != 0;
            let Some(result) = vm
                .transaction_hook
                .as_mut()
                .and_then(|h| h.integrity_check(quick))
            else {
                return Err(ExecError::Unimplemented {
                    opcode: Opcode::IntegrityCheck,
                });
            };
            for line in result.map_err(ExecError::TransactionFailed)? {
                vm.emit_row(vec![Value::Text(line.into())]);
            }
            Ok(Step::Next)
        }

        Opcode::Delete => {
            let deleted = vm.cursor_mut(instr.p1)?.delete();
            if !deleted {
                return Err(ExecError::MalformedInstruction {
                    opcode: "Delete",
                    reason: "cursor slot does not support deletion".to_string(),
                });
            }
            Ok(Step::Next)
        }
        Opcode::NewRowid => {
            let next = vm.cursor(instr.p1)?.next_rowid();
            // sqlite-rs: p5 != 0 with P4::Str(table) is AUTOINCREMENT —
            // the schema hook consults/updates sqlite_sequence so a rowid
            // is never reused after a delete.
            let rowid = if instr.p5 != 0 {
                let table = match &instr.p4 {
                    P4::Str(name) => name.clone(),
                    other => {
                        return Err(ExecError::MalformedInstruction {
                            opcode: "NewRowid",
                            reason: format!(
                                "AUTOINCREMENT requested (P5 nonzero) but P4 is not a table-name string, got {other:?}"
                            ),
                        })
                    }
                };
                let max_from_table = next.saturating_sub(1);
                vm.schema_storage
                    .as_deref_mut()
                    .ok_or(ExecError::SchemaStorageMissing { opcode: "NewRowid" })?
                    .autoincrement_rowid(&table, max_from_table)
                    .map_err(ExecError::SchemaStorageFailed)?
            } else {
                next
            };
            vm.set_register(instr.p2, Value::Integer(rowid))?;
            Ok(Step::Next)
        }
        Opcode::IdxInsert | Opcode::IdxDelete => {
            let opcode = if instr.opcode == Opcode::IdxInsert {
                "IdxInsert"
            } else {
                "IdxDelete"
            };
            let (key, collations) = key_from_registers(vm, opcode, instr.p2, &instr.p4)?;
            let ok = if instr.opcode == Opcode::IdxInsert {
                // sqlite-rs: on an ephemeral index the stored row is the key
                // columns plus `p5` trailing payload columns.
                let total = key.len().checked_add(usize::from(instr.p5)).ok_or(
                    ExecError::RegisterRangeTooLarge {
                        opcode,
                        count: i32::from(instr.p5),
                    },
                )?;
                let stored = register_range(vm, opcode, instr.p2, total)?;
                let cursor = vm.cursor_mut(instr.p1)?;
                match cursor.ephemeral_idx_insert(&key, &collations, stored) {
                    Some(ok) => ok,
                    None => cursor.idx_insert(key),
                }
            } else {
                vm.cursor_mut(instr.p1)?.idx_delete(&key)
            };
            if !ok {
                return Err(ExecError::MalformedInstruction {
                    opcode,
                    reason:
                        "cursor slot does not support this index operation, or no matching entry"
                            .to_string(),
                });
            }
            Ok(Step::Next)
        }

        Opcode::CreateTable => {
            let P4::CreateTable { name, sql } = &instr.p4 else {
                return Err(ExecError::MalformedInstruction {
                    opcode: "CreateTable",
                    reason: format!("expected a CreateTable P4, got {:?}", instr.p4),
                });
            };
            let (name, sql) = (name.clone(), sql.clone());
            let storage = vm.schema_storage("CreateTable")?;
            let root = storage
                .create_table_root()
                .map_err(ExecError::SchemaStorageFailed)?;
            storage
                .insert_master_row("table", &name, &name, root, &sql)
                .map_err(ExecError::SchemaStorageFailed)?;
            storage
                .bump_schema_cookie()
                .map_err(ExecError::SchemaStorageFailed)?;
            Ok(Step::Next)
        }
        Opcode::CreateView => {
            // sqlite-rs `cursor::create_view`: a view has no b-tree — one
            // sqlite_master row with rootpage 0, then the cookie bump.
            let P4::CreateView { name, sql } = &instr.p4 else {
                return Err(ExecError::MalformedInstruction {
                    opcode: "CreateView",
                    reason: format!("expected a CreateView P4, got {:?}", instr.p4),
                });
            };
            let (name, sql) = (name.clone(), sql.clone());
            let storage = vm.schema_storage("CreateView")?;
            storage
                .insert_master_row("view", &name, &name, 0, &sql)
                .map_err(ExecError::SchemaStorageFailed)?;
            storage
                .bump_schema_cookie()
                .map_err(ExecError::SchemaStorageFailed)?;
            Ok(Step::Next)
        }
        Opcode::CreateIndex => {
            let P4::CreateIndex {
                name,
                table_name,
                table_root_page,
                sql,
                column_indices,
                ..
            } = &instr.p4
            else {
                return Err(ExecError::MalformedInstruction {
                    opcode: "CreateIndex",
                    reason: format!("expected a CreateIndex P4, got {:?}", instr.p4),
                });
            };
            let (name, table_name, table_root_page, sql, column_indices) = (
                name.clone(),
                table_name.clone(),
                *table_root_page,
                sql.clone(),
                column_indices.clone(),
            );
            let storage = vm.schema_storage("CreateIndex")?;
            let root = storage
                .create_index_root()
                .map_err(ExecError::SchemaStorageFailed)?;
            storage
                .populate_index(root, table_root_page, &column_indices)
